local config = {
  ui_story_5075_50750100_1_dialog_content = "(신풍호의 위험천만한 항해를 마치고, 우리는 마침내 대해를 넘어\n용주 대륙의 땅을 밟을 수 있었다.)",
  ui_story_5075_50750100_2_dialog_content = "(월백 씨와 종서 씨 일행은 항구에서 상회 화물을 호송하느라 이틀 정도 여정이 늦어졌다.)",
  ui_story_5075_50750100_3_dialog_content = "(린 가문 상회에서는 함께 일해보자며 진심으로 권유했지만...)",
  ui_story_5075_50750100_4_dialog_content = "(내겐 아스트라 대륙 사절의 의무가 있다. 먼저 단당 씨와 함께 제나라 수도로 가야만 한다.)",
  ui_story_5075_50750100_5_dialog_content = "『용낭랑, 용낭랑, 비나이다, 비나이다.』",
  ui_story_5075_50750100_6_dialog_content = "『비를 거두면 아침결에 간사 바치리다──』",
  ui_story_5075_50750100_7_dialog_content = "<color=#e8d9bb>철썩──</color>",
  ui_story_5075_50750100_8_dialog_content = "으앗!",
  ui_story_5075_50750100_9_dialog_content = "PlayerName 공자, 조심하거라!",
  ui_story_5075_50750100_10_dialog_content = "제나라의 풍경이 신기한 것은 이해한다만, 강을 건너는 작은 배는 신풍호와는 다르다.",
  ui_story_5075_50750100_11_dialog_content = "경치에 정신이 팔려서 조심하지 않으면 물에 빠질지도 모르는 것이야.",
  ui_story_5075_50750100_12_dialog_content = "내 어렵게 아스트라 대륙에서 그대라는 귀한 사절을 청해 와서...",
  ui_story_5075_50750100_13_dialog_content = "망망대해를 지나면서 암귀와 해적의 습격에서도 공자를 무탈하게 지켰거늘...",
  ui_story_5075_50750100_14_dialog_content = "왕궁을 한 치 앞에 두고 물에 빠져서야 내 죄가 너무나도 크지 않겠느냐.",
  ui_story_5075_50750100_15_dialog_content = "아하하... 걱정하게 만들어서 미안해요.",
  ui_story_5075_50750100_16_dialog_content = "뱃사공의 노래를 듣느라 배 위라는 것도 잊고 있었어요.",
  ui_story_5075_50750100_17_dialog_content = "그나저나 항구를 떠난 뒤로 계속 비슷한 노래가 들리는 것 같은데요.",
  ui_story_5075_50750100_18_dialog_content = "현지 언어인 것 같은데, 박자도 빠르네요. 무슨 내용이죠?",
  ui_story_5075_50750100_19_dialog_content = "저것은 뱃노래다.",
  ui_story_5075_50750100_20_dialog_content = "제나라는 하천과 호수가 많은 나라다. 백성들은 물과 함께 살고, 뱃사람과 어부도 많지.",
  ui_story_5075_50750100_21_dialog_content = "그런 풍토와 역사가 뱃노래를 만들어 낸 것이야.",
  ui_story_5075_50750100_22_dialog_content = "산의 푸르름과 물의 맑음을 노래하고, 수면 위 버드나무나 활짝 핀 꽃을 노래하기도 하지.",
  ui_story_5075_50750100_23_dialog_content = "그 외에도 지금 그대가 들은 것처럼 신의 가호를 바라는 노래도 있다.",
  ui_story_5075_50750100_24_dialog_content = "「용녀님, 부디 하늘이 맑아 항해가 순조롭길 비나이다.」",
  ui_story_5075_50750100_25_dialog_content = "「무사히 집에 돌아가면 맛있는 건두부를 바치겠나이다.」",
  ui_story_5075_50750100_26_dialog_content = "대략 이런 뜻인 게지.",
  ui_story_5075_50750100_27_dialog_content = "아, 용녀님 얘기였군요!",
  ui_story_5075_50750100_28_dialog_content = "전에 쌍사성에서 단당 씨가 바이스한테 가르쳤던 춤이 <color=#FFB400>「용녀진해무」</color>였잖아요.",
  ui_story_5075_50750100_29_dialog_content = "용녀는 용주 바닷가에 사는 사람들이 믿는 신령이라고 말씀해 주셨던 것 같아요.",
  ui_story_5075_50750100_30_dialog_content = "...근데 신도 건두부를 좋아하나요?",
  ui_story_5075_50750100_31_dialog_content = "후훗, 그런 게 아니다. 사실 이 노래의 끝부분은 정해진 가사가 없느니라.",
  ui_story_5075_50750100_32_dialog_content = "용녀님은 공물을 요구하지 않으신다.\n하여 백성들은 자신이 바치고 싶은 것을 가사에 담아 마음을 표현하는 것이지.",
  ui_story_5075_50750100_33_dialog_content = "방금 저 사공이 「건두부」라고 부른 것은 아마 지금 막 집에서\n건두부를 만들었기 때문일지도 모르겠구나.",
  ui_story_5075_50750100_34_dialog_content = "그렇게 해도 되는 건가요? 꽤 소탈한 신이네요.",
  ui_story_5075_50750100_35_dialog_content = "용주의 문화는 쌍사성에서 이미 꽤 알게 됐었다고 생각했는데...",
  ui_story_5075_50750100_36_dialog_content = "막상 용주에 와보니 들어본 적도 없는 신기한 일들을 매 순간 보고 있어요.",
  ui_story_5075_50750100_37_dialog_content = "바이스랑 카렌한테도 정말 보여주고 싶네요.",
  ui_story_5075_50750100_38_dialog_content = "그 소원, 금방 이루어질지도 모르겠구나.",
  ui_story_5075_50750100_39_dialog_content = "맞아요. 우리 임무는 두 대륙 간의 교류를 증진하는 거니까요.",
  ui_story_5075_50750100_40_dialog_content = "모든 게 순조롭게 끝나면, 아스트라의 친구들도 용주로 여행을 올 수 있을지도 몰라요!",
  ui_story_5075_50750100_41_dialog_content = "양 대륙이 암귀에 맞설 방책과 기술도 잊어서는 아니 된다.",
  ui_story_5075_50750100_42_dialog_content = "노력하여 서로를 이끌어 두 대륙의 백성들이 안녕한 나날을 보낼 수 있게 해야겠지.",
  ui_story_5075_50750100_43_dialog_content = "그것을 실현하기 위해서는 우리 아스트라 사절 나리의 덕을 많이 보아야 하지 않겠느냐~",
  ui_story_5075_50750100_44_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5075_50750100_45_dialog_content = "전하, PlayerName 님, 도착했습니다. 이 앞이 바로 목적지입니다.",
  ui_story_5075_50750100_46_dialog_content = "여기서 상륙하고 입성해야 합니다.",
  ui_story_5075_50750100_47_dialog_content = "PlayerName 공자, 잠시만 기다리거라.",
  ui_story_5075_50750100_48_dialog_content = "<color=#e8d9bb>단당은 먼저 배를 내려 해안가에 섰고, 미소와 함께 손을 모아들고 가볍게 몸을 숙여 인사했다.</color>",
  ui_story_5075_50750100_49_dialog_content = "나 작화군주는 제나라 국군의 왕명을 받들어 사절로서 아스트라 대륙에 보내졌다.",
  ui_story_5075_50750100_50_dialog_content = "그리고 귀하는 나의 초청에 응하여 만 리 길도 마다치 않고 용주에 당도했다.",
  ui_story_5075_50750100_51_dialog_content = "이에 다시 한번 귀하에게 경의와 사의를 표하는 바이다.",
  ui_story_5075_50750100_52_dialog_content = "<color=#FFB400>제나라 도성</color>...",
  ui_story_5075_50750100_53_dialog_content = "<color=#FFB400>호진</color>에 온 것을 환영한다.",
  ui_story_5075_50750100_54_dialog_content = "네, 고마워요!",
  ui_story_5075_50750100_55_dialog_content = "그럼 이젠 제가 이 용주에서 아스트라 대륙 사절로서의 임무를 완수할 차례네요.",
  ui_story_5075_50750100_56_dialog_content = "전하, 앞에 시종이 마중을 나왔습니다. 이제 궁으로 돌아가 대왕께 보고드려야 합니다.",
  ui_story_5075_50750100_57_dialog_content = "하면 PlayerName 공자는...",
  ui_story_5075_50750100_58_dialog_content = "군주 전하, 사절 나리, 어서 오십시오.",
  ui_story_5075_50750100_59_dialog_content = "저는 사절 나리의 응접을 맡은 영빈관의 책임자입니다.",
  ui_story_5075_50750100_60_dialog_content = "앞으로 사절 나리께서 제나라에 머무시는 동안 일상 활동과 호위는 저희 영빈관이 맡을 것입니다.",
  ui_story_5075_50750100_61_dialog_content = "아무래도 잠시 따로 움직여야 할 모양이로구나.",
  ui_story_5075_50750100_62_dialog_content = "임무가 끝나면 월백 선장도 돌아올 터이니, 그때 모여서 그대에게 이 호진성을 안내해 주마.",
  ui_story_5075_50750100_63_dialog_content = "이제 곧 춘삭절이니 말이야. 용주에서 가장 중요한 명절이지.",
  ui_story_5075_50750100_64_dialog_content = "거리에는 사람들이 용탈을 쓰고 등춤을 추며, 가는 곳마다 화려함을 뽐낸다.\n게다가 사당 장터에는 다양한 음식을 맛볼 수 있는 노점이 즐비하지...",
  ui_story_5075_50750100_65_dialog_content = "필시 공자에게도 좋은 추억이 될 게야.",
  ui_story_5075_50750100_66_dialog_content = "네, 기대하고 있을게요!",
  ui_story_5075_50750100_67_dialog_content = "(하지만 그때의 우리들은 이 평범한 계획에 그토록 많은 곡절이 벌어질 줄은 알지 못했다...)",
  ui_story_5075_50750100_68_dialog_content = "<color=#e8d9bb>영빈관</color>",
  ui_story_5075_50750100_69_dialog_content = "사절 나리, 차 한 잔 드시지요.",
  ui_story_5075_50750100_70_dialog_content = "산에서 갓 길어온 샘물로 우려낸 자순차이옵니다.\n깔끔함과 단맛을 가장 잘 느낄 수 있는 품종이지요.",
  ui_story_5075_50750100_71_dialog_content = "진짜 맛있네요! 고마워요!",
  ui_story_5075_50750100_72_dialog_content = "소녀가 사절 나리의 간식을 취향을 알지 못하여, 여러 가지로 조금씩 준비해 보았사옵니다.",
  ui_story_5075_50750100_73_dialog_content = "금유소, 칠첩고, 옥로단... 다른 드시고 싶은 게 있으시면 언제든 분부하시지요.",
  ui_story_5075_50750100_74_dialog_content = "이, 이게... 「조금씩」인가요?!",
  ui_story_5075_50750100_75_dialog_content = "사절 나리, 소녀가 환복과 목욕 시중을 들겠사옵니다.",
  ui_story_5075_50750100_76_dialog_content = "이, 아, 아니에요! 괜찮아요! 제가 알아서 할게요!",
  ui_story_5075_50750100_77_dialog_content = "너, 너무 대접이 극진한 거 아닌가요...",
  ui_story_5075_50750100_78_dialog_content = "(저러니까 엄청 긴장된단 말이지... 잘못하면 아스트라의 인상을\n망칠 것 같잖아... 하하...)",
  ui_story_5075_50750100_79_dialog_content = "(뭐, 내일이면 궁에 들어가서 본격적인 이야기를 할 수 있겠지. 여기 오래 있진 않을 테니까.)",
  ui_story_5075_50750100_80_dialog_content = "<color=#e8d9bb>다음 날</color>",
  ui_story_5075_50750100_81_dialog_content = "(드디어 왔다! 궁에서 날 부르러 온 건가?)",
  ui_story_5075_50750100_82_dialog_content = "사절 나리, 나리께서 먼 길 마다않고 바다 건너에서 오셨다는 소식을 들으시고\n대왕님께서도 무척 기뻐하고 계십니다.",
  ui_story_5075_50750100_83_dialog_content = "이에 특별히 소녀를 보내시어 명차와 과일, 금의와 옥대, 비단과 무명,\n그리고 각종 훈향을 사절 나리께 전하라 하셨사옵니다.",
  ui_story_5075_50750100_84_dialog_content = "이걸 다 저한테요? 그치만...",
  ui_story_5075_50750100_85_dialog_content = "선물은 잘 드렸으니, 소녀 이만 물러가겠사옵니다.",
  ui_story_5075_50750100_86_dialog_content = "부디 사절 나리께서 제나라에 머무는 동안 건강하고 즐겁게 지내시어,\n<color=#FFB400>작화군주 전하</color>께 심려를 끼치는 일이 없기를 바라옵니다.",
  ui_story_5075_50750100_87_dialog_content = "<color=#e8d9bb>셋째 날</color>",
  ui_story_5075_50750100_88_dialog_content = "...왜 아직도 궁에서 부르질 않는 거죠?",
  ui_story_5075_50750100_89_dialog_content = "사절 나리, 심심하신지요? 하면 연극 관람은 좋아하시는지요?",
  ui_story_5075_50750100_90_dialog_content = "좋아하신다면 소녀가 유명한 배우를 초대하여 공연을 열어 드리겠사옵니다.",
  ui_story_5075_50750100_91_dialog_content = "저기, 그게 아니라...",
  ui_story_5075_50750100_92_dialog_content = "연극이 마음에 들지 않으십니까? 하면 만담이나 곡예 공연은 어떠신지요?",
  ui_story_5075_50750100_93_dialog_content = "전부 마음에 들지 않으신다면 귀뚜라미싸움이나 닭싸움도 있사옵니다.\n호진에는 이 외에도 많은 놀거리가 있지요.",
  ui_story_5075_50750100_94_dialog_content = "아니, 지금 그런 게 필요한 게 아닌데요...",
  ui_story_5075_50750100_95_dialog_content = "밖에 나가고 싶어요! 제나라 국왕님을 만나야 한다구요!",
  ui_story_5075_50750100_96_dialog_content = "<color=#e8d9bb>넷째 날</color>",
  ui_story_5075_50750100_97_dialog_content = "휴... 드디어 밖에 나왔네.",
  ui_story_5075_50750100_98_dialog_content = "근데 여기가 어디죠? 간판이 잔뜩 있네요...\n제나라 국왕님이 이런 곳에 살지는 않을 것 같은데...",
  ui_story_5075_50750100_99_dialog_content = "소녀 답하겠사옵니다. 사절 나리께서 며칠간 차나 식사에도 무심하시기에,\n혹여 마음이 갑갑하신 것이 아닌가 사료하였사옵니다.",
  ui_story_5075_50750100_100_dialog_content = "하여 주사관 나리께 청을 드려 나들이 일정을 잡아 드렸사옵니다.",
  ui_story_5075_50750100_101_dialog_content = "이 남산의 용녀 사당은 처음 호진에 온 여행객이라면 놓치지 말아야 할 절경이옵니다.",
  ui_story_5075_50750100_102_dialog_content = "산세가 아름다울 뿐만 아니라, 정교한 기석도 있으며,\n한때 용녀낭랑께서 이곳에 강림하셨다는 전설도 있사옵니다.",
  ui_story_5075_50750100_103_dialog_content = "나리께선 마음 편히 감상하시거나, 용녀낭랑을 참배하셔도 되옵니다.\n관계없는 이들은 모두 물러가도록 하였으니, 나리를 불편케 할 이는 없을 것이옵니다.",
  ui_story_5075_50750100_104_dialog_content = "네? 저 때문에 사람들을 다 내쫓았다고요? 어쩐지 조용하더라니...",
  ui_story_5075_50750100_105_dialog_content = "그런 거 안 해도 돼요. 전 그런 대단한 사람도 아닌데요.\n다른 사람들이랑 같이 관람해도 괜찮아요.",
  ui_story_5075_50750100_106_dialog_content = "그게 무슨 말씀이십니까, 사절 나리께서는 제나라의 귀빈이시옵니다.\n저희도 응당 성의를 다해야지요.",
  ui_story_5075_50750100_107_dialog_content = "그럼, 모쪼록 편히 즐겨 주시지요.",
  ui_story_5075_50750100_108_dialog_content = "(뭐, 괜찮겠지... 기왕 왔으니까 한번 둘러보자.)",
  ui_story_5075_50750100_109_dialog_content = "(정전 가운데에 있는 조각상이 그 전설의 용녀낭랑인가? 되게 엄숙한 분위기네.)",
  ui_story_5075_50750100_110_dialog_content = "(단당 씨 말처럼 별의별 물건을 다 공물로 바쳤잖아. 과일, 채소, 찻잎에 간식까지...)",
  ui_story_5075_50750100_111_dialog_content = "(어라? 누가 있나?)",
  ui_story_5075_50750100_112_dialog_content = "<color=#e8d9bb>찰랑──</color>",
  ui_story_5075_50750100_113_dialog_content = "(이건... 시녀가 떨어트린 건가? 아니면 방금 그 사람?)",
  ui_story_5075_50750100_114_dialog_content = "사절 나리──",
  ui_story_5075_50750100_115_dialog_content = "소녀 이미 여러 차례 조사해 보았으나, 사당에 다른 참배객은 없었사옵니다.",
  ui_story_5075_50750100_116_dialog_content = "근데 확실히 누군가 있었고, 물건도 떨어트리고 간 것 같아요...",
  ui_story_5075_50750100_117_dialog_content = "소녀는 아무것도... 앗!",
  ui_story_5075_50750100_118_dialog_content = "공물이 전부 없어졌사옵니다!",
  ui_story_5075_50750100_119_dialog_content = "어, 어떻게 이런...",
  ui_story_5075_50750100_120_dialog_content = "사절 나리, 송구하옵니다. 저희가 불민하여 좀도둑이 들게 만들었습니다.",
  ui_story_5075_50750100_121_dialog_content = "용녀 사당에는 요마가 감히 접근하지 못하옵니다. 하면 필시 또 그 수요령들 짓일 것이겠지요...",
  ui_story_5075_50750100_122_dialog_content = "수요령이 왜요?",
  ui_story_5075_50750100_123_dialog_content = "벼, 별일 아니옵니다. 사절 나리께서 괘념하실 필요는 없사옵니다.",
  ui_story_5075_50750100_124_dialog_content = "오늘 여정은 저희가 소홀했사옵니다. 먼저 호위와 함께 하산하시지요.\n이 일은 소녀가 주사관 나리께 보고하겠습니다.",
  ui_story_5075_50750100_125_dialog_content = "여봐라! 사절 나리를 영빈관으로 모시거라!",
  ui_story_5075_50750100_126_dialog_content = "예!",
  ui_story_5075_50750100_127_dialog_content = "아, 아니... 잠깐만요... 신선한 공기 좀 더 마시게 해달라구요오오──!",
  ui_story_5075_50750100_128_dialog_content = "(그 후 며칠간, 나는 똑같은 나날을 보냈다.)",
  ui_story_5075_50750100_129_dialog_content = "(먹고, 자고, 놀고... 무척이나 세심한 대접을 받았고, 좀 돌아다니기만 해도 호위가 따라다녔다.)",
  ui_story_5075_50750100_130_dialog_content = "(하지만 궁에 들어가는 일만은 아무리 물어도 명확한 답을 받을 수 없었다.)",
  ui_story_5075_50750100_131_dialog_content = "(...이대로는 안 되겠어. 직접 그 주사관한테 물어보자.)",
  ui_story_5075_50750100_132_dialog_content = "(대체 언제쯤 제나라 왕을 만나서 단당 씨가 말한 두 대륙의 교류 얘기를 할 수 있는 거냐고.)",
  ui_story_5075_50750100_133_dialog_content = "(이번엔 호위가 막지 않았으면 좋겠는데...)",
  ui_story_5075_50750100_134_dialog_content = "...작화군주 말이야.",
  ui_story_5075_50750100_135_dialog_content = "(어? 지금 누가 단당 씨 이야기를 하는 것 같은데?)",
  ui_story_5075_50750100_136_dialog_content = "그게 진짜야?!",
  ui_story_5075_50750100_137_dialog_content = "아하하, 아니 땐 굴뚝에 연기가 나겠니?",
  ui_story_5075_50750100_138_dialog_content = "우리 세자 저하께서 저 군주님한테 푹 빠져서 다른 여인들에겐 눈길도 안 주신대.",
  ui_story_5075_50750100_139_dialog_content = "군주님은 답을 안 하셨다는데, 궁 안의 친구 말로는...\n대왕님께서 두 사람을 결혼시킬 뜻이 있으신 것 같아!",
  ui_story_5075_50750100_140_dialog_content = "그럼 경삿날도 얼마 안 남았네! 그러니까 궁이 계속 바빠서 다른 일에 신경을 못 쓴 거였구나.",
  ui_story_5075_50750100_141_dialog_content = "참 나, 볼모 주제에 팔자도 좋으시다니까! 그 군주님, 빚 대신 온 거 아니었나?",
  ui_story_5075_50750100_142_dialog_content = "?!",
  ui_story_5075_50750100_143_dialog_content = "저기... 지금 얘기하는 거 설마...",
  ui_story_5075_50750100_144_dialog_content = "사절 나리, 여기 계셨군요. 한참 찾았습니다.",
  ui_story_5075_50750100_145_dialog_content = "대왕님께서 명을 내리셨습니다. 오늘 연회에 특별히 사절 나리를 초대하여,\n나리께 이역의 이야기를 듣고 싶다 하십니다.",
  ui_story_5075_50750100_146_dialog_content = "어서 준비해 주시지요. 저와 함께 입궁하시면 됩니다.",
  ui_story_5075_50750100_147_dialog_content = "하필 지금요?! 진작 좀 말씀하시지!",
  ui_story_5075_50750201_1_dialog_content = "<color=#e8d9bb>화려한 궁전이 우뚝 솟아 있고, 우아한 음악이 사방에서 울려 퍼지고 있다.</color>",
  ui_story_5075_50750201_2_dialog_content = "아스트라 사절 입조요──!",
  ui_story_5075_50750201_3_dialog_content = "서쪽 대륙 사람은 역시 우리와 다르군요.",
  ui_story_5075_50750201_4_dialog_content = "의복은 새롭고 기이하나, 재단이 너무 과하여 우아함이 부족하지 않습니까.",
  ui_story_5075_50750201_5_dialog_content = "듣자 하니 서쪽 대륙에서도 드문 아이테르라는 일족이라더군요.",
  ui_story_5075_50750201_6_dialog_content = "(다들 내 얘기 하는 것 같네.)",
  ui_story_5075_50750201_7_dialog_content = "(단당 씨가 있어 줘서 다행이야. 적어도 단당 씨를 괴롭힐 사람은 없을 테니까.\n근데 단당 씨, 왜 저렇게 엄숙한 표정이지?)",
  ui_story_5075_50750201_8_dialog_content = "그대가 바로 PlayerName인가?\n두 대륙의 항로 재개를 위해 그대가 힘을 썼던 일은 과인도 들은 바 있다.",
  ui_story_5075_50750201_9_dialog_content = "오늘 이렇게 보니 소문대로 전도유망한 청년이로구나.",
  ui_story_5075_50750201_10_dialog_content = "별말씀을요. 신풍호가 무사히 귀항할 수 있었던 건 배의 모두가 힘을 합친 덕분인걸요...",
  ui_story_5075_50750201_11_dialog_content = "그리 겸손할 필요는 없다. 여봐라, 사절을 자리로 안내하고 차를 내오거라.",
  ui_story_5075_50750201_12_dialog_content = "그대는 바다 건너 멀리서 온 드문 손님이다.\n하면 우리 경들에게 이역 대륙의 이야기를 조금 들려줄 수 있겠는가?",
  ui_story_5075_50750201_13_dialog_content = "과인이 듣기로는 바다 건너 대륙에는 싸움에 능한 철의 거인이 있다더군.",
  ui_story_5075_50750201_14_dialog_content = "전사가 그 안으로 들어가면 생각으로 조종할 수 있고, 그 눈은 뇌광처럼 빛나며,\n그 힘은 산천도 가른다 하였는데, 그것이 사실인가?",
  ui_story_5075_50750201_X14_option_content = "음... 그건 좀...",
  ui_story_5075_50750201_15_dialog_content = "아무래도 조금 과장된 것 같네요.",
  ui_story_5075_50750201_16_dialog_content = "아스트라 대륙의 기계도 아직은 그 정도 수준까지 발달하진 못했어요.",
  ui_story_5075_50750201_17_dialog_content = "콜로서스라는 존재가 있긴 하지만, 말씀하신 것처럼 강력한 병기는 아니에요.",
  ui_story_5075_50750201_18_dialog_content = "게다가 콜로서스는 수도 적고, 조종할 수 있는 사람도 아주 드물어요.",
  ui_story_5075_50750201_X18_option_content = "어쩌면 미래엔 가능할지도 몰라요.",
  ui_story_5075_50750201_X19_dialog_content = "아직까진 그런 강력한 힘은 없지만...",
  ui_story_5075_50750201_X20_dialog_content = "아스트라 대륙엔 군사 기술에 뛰어난 일루미나 연방이 있고,\n마술 의식에 뛰어난 백야성이 있거든요.",
  ui_story_5075_50750201_X21_dialog_content = "미래에는 실제로 전하께서 말씀하신 그런 거인을 만들어 낼 수 있을지도 몰라요.",
  ui_story_5075_50750201_X22_dialog_content = "흐음... 그렇다면 아직 그런 것은 없다는 말이로군.",
  ui_story_5075_50750201_19_dialog_content = "하면 병사들은 요마를 어찌 상대하고 있는가.",
  ui_story_5075_50750201_20_dialog_content = "군대가 각종 무기를 개발하고 있고, 몸을 보호하는 갑주도 있어요.",
  ui_story_5075_50750201_21_dialog_content = "거기에 루미나틱스, 그러니까 광력술을 조합하면 암귀... 즉, 요마와 싸울 수 있죠.",
  ui_story_5075_50750201_22_dialog_content = "육신으로써 투쟁하는 점은 변함이 없다는 말이로군.",
  ui_story_5075_50750201_23_dialog_content = "바다 건너 그 대륙도 자못 넓을 터인데, 불사의 술법이나 승천의 대법은 없는가?",
  ui_story_5075_50750201_24_dialog_content = "그런 건... 아마 존재하지 않을 거예요.",
  ui_story_5075_50750201_25_dialog_content = "각지에 소수이긴 해도 장수하는 사람이 있긴 해요.\n북방의 여왕은 늘 젊음을 유지하는 것으로 유명하고요...",
  ui_story_5075_50750201_26_dialog_content = "하지만 절대적인 불로불사라면... 적어도 전 들어본 적 없어요.",
  ui_story_5075_50750201_27_dialog_content = "허어, 보아하니 대해 너머도 이 용주와 별반 다를 바가 없는 모양이로군.",
  ui_story_5075_50750201_28_dialog_content = "꼭 그렇다고 단언할 수는...",
  ui_story_5075_50750201_29_dialog_content = "크흠.",
  ui_story_5075_50750201_30_dialog_content = "<size=28>경거망동하지 말거라.</size>",
  ui_story_5075_50750201_31_dialog_content = "......",
  ui_story_5075_50750201_32_dialog_content = "참, 과인은 그대가 기이한 능력을 지니고 있다고 들었다.",
  ui_story_5075_50750201_33_dialog_content = "술법의 힘을 몇 곱절로 강하게 만들 수 있다지?",
  ui_story_5075_50750201_34_dialog_content = "과인이 작은 벼슬을 하나 내릴 터이니, 제나라에 머무르는 것은 어떠한가?",
  ui_story_5075_50750201_35_dialog_content = "며칠간 그대도 호진의 모습을 보았을 터.",
  ui_story_5075_50750201_36_dialog_content = "우리 제나라는 하천이 많고 토지가 비옥하며, 바다와 육지가 어우러져 만사가 번영하니,\n그야말로 지상의 천궁이라 일컬어도 과함이 없을 것이다.",
  ui_story_5075_50750201_37_dialog_content = "요마가 횡행하는 그쪽 대륙보다 못할 것이 무어가 있겠는가.",
  ui_story_5075_50750201_38_dialog_content = "아... 말씀은 감사하지만 아스트라 대륙은 제 고향이고, 결국엔 돌아가야 해요.",
  ui_story_5075_50750201_39_dialog_content = "그리고 전 사절 신분으로 여기 온 거예요.\n제 즐거움을 위해서가 아니라 두 대륙의 교류 촉진을 위해서요.",
  ui_story_5075_50750201_40_dialog_content = "아스트라 대륙엔 요마에 효과적인 과학 기술이 많이 있어요. 일루미나와 백야성뿐만 아니라...",
  ui_story_5075_50750201_41_dialog_content = "흐음, 그대의 말에 일리는 있으나, 그러한 작은 일은 시박사에 맡기면 된다.",
  ui_story_5075_50750201_42_dialog_content = "지금 그 이야기를 꺼내는 것은 이 멋진 연회 자리의 흥을 깨는 일이 아니겠는가.",
  ui_story_5075_50750201_43_dialog_content = "이제 곧 춘삭절이 돌아오니, 제나라의 번영과 발전을 모두 함께 축하함이 마땅하지.",
  ui_story_5075_50750201_44_dialog_content = "경들은 술잔을 들으시오──",
  ui_story_5075_50750201_45_dialog_content = "하지만...",
  ui_story_5075_50750201_46_dialog_content = "대왕님의 만수를 기원하옵니다!",
  ui_story_5075_50750201_47_dialog_content = "제나라의 무궁한 번영을 위하여!",
  ui_story_5075_50750201_48_dialog_content = "<color=#e8d9bb>쿠구구──!</color>",
  ui_story_5075_50750201_49_dialog_content = "지진이다!",
  ui_story_5075_50750201_50_dialog_content = "어, 어서 대왕님을 지켜라!",
  ui_story_5075_50750201_51_dialog_content = "<color=#e8d9bb>탁자와 의자가 흔들리고 식기가 바닥에 떨어졌다.\n진동은 한참을 지속된 후에야 비로소 진정되었다.</color>",
  ui_story_5075_50750201_52_dialog_content = "<color=#e8d9bb>가무로 한껏 들떠 있던 대전의 분위기도 낭패가 되었고,\n그저 사람들이 뛰어다니며 명을 전하는 소리만 들릴 뿐이었다.</color>",
  ui_story_5075_50750201_53_dialog_content = "<color=#e8d9bb>조금 전까지 의기양양하던 관리들도 지금은 당황한 모습이었다.</color>",
  ui_story_5075_50750201_54_dialog_content = "휴... 소식이 잘 전해진 덕에 백성들도 무사할 수 있었다.",
  ui_story_5075_50750201_55_dialog_content = "비록 아쉬움이 없지는 않으나, 오늘 연회는 여기서 마칠 수밖에 없겠구나.",
  ui_story_5075_50750201_56_dialog_content = "단당 씨?",
  ui_story_5075_50750201_57_dialog_content = "자, PlayerName 공자, 조용한 곳으로 자리를 옮기자꾸나.",
  ui_story_5075_50750201_58_dialog_content = "잠깐만요. 머리띠가 어디 걸린 것 같아요...",
  ui_story_5075_50750201_59_dialog_content = "단당 씨, 미안한데 좀 도와주실 수 있나요?",
  ui_story_5075_50750201_60_dialog_content = "이 나무의 꽃봉오리, 진짜 예쁘네요. 분명 귀한 꽃이겠죠?\n제가 세게 당기면 꽃이 망가질 것 같아요.",
  ui_story_5075_50750201_61_dialog_content = "후후, 그리 귀한 것도 아니니라... 매화꽃은 어디에나 피어 있으니 말이다.\n허나 매화꽃을 그토록 세심히 돌보는 자는 아마 공자가 처음인 성싶구나.",
  ui_story_5075_50750201_62_dialog_content = "일단 가만히 있거라. 내가 풀어주마.",
  ui_story_5075_50750201_63_dialog_content = "......",
  ui_story_5075_50750201_64_dialog_content = "후훗, 다 되었다.",
  ui_story_5075_50750201_65_dialog_content = "며칠간 못 보았는데, 영빈관에서 지내는 것은 익숙해졌느냐.",
  ui_story_5075_50750201_66_dialog_content = "네, 너무 대접이 과하다는 생각이 들긴 하지만요.",
  ui_story_5075_50750201_67_dialog_content = "물을 마시는 것까지도 제가 직접 못 하게 해서, 꼭 제가 엄청 귀한 인물이 된 것 같았어요.",
  ui_story_5075_50750201_68_dialog_content = "하면 아니란 말이냐?",
  ui_story_5075_50750201_69_dialog_content = "놀리지 마세요.",
  ui_story_5075_50750201_70_dialog_content = "뭐, 그런 정신 없는 대접을 받으면서도 창피한 꼴을 안 보인 건 그나마 다행이지만요.",
  ui_story_5075_50750201_71_dialog_content = "하지만 사절 임무도 잘 수행하지 못했잖아요.",
  ui_story_5075_50750201_72_dialog_content = "겨우 궁에 들어가나 했더니 교류 이야기는커녕 아스트라를 제대로 소개하지도 못했어요.",
  ui_story_5075_50750201_73_dialog_content = "...미안하구나, PlayerName 공자.",
  ui_story_5075_50750201_74_dialog_content = "내 사려가 깊지 못했던 탓이다.",
  ui_story_5075_50750201_75_dialog_content = "그대를 다른 대륙에서 데려왔음에도 제대로 발언할 무대도 마련해 주지 못했구나.",
  ui_story_5075_50750201_76_dialog_content = "단당 씨 때문이 아니에요. 제가 미리 더 준비했으면 이렇게 허둥댈 일도 없었을 거예요.",
  ui_story_5075_50750201_77_dialog_content = "아니다, 역시 내가...",
  ui_story_5075_50750201_78_dialog_content = "푸훗...",
  ui_story_5075_50750201_79_dialog_content = "아하하... 둘이서 서로 자기 탓을 하니까 왠지 이상하네요.",
  ui_story_5075_50750201_80_dialog_content = "뭐, 어쩔 수 없죠. 어차피 지난 일이니까요.\n그럼 돌아가서 잘 준비하고, 다음에 궁에 들어갈 때 더 노력할게요.",
  ui_story_5075_50750201_81_dialog_content = "...그리고 하나 더 궁금한 게 있어요.",
  ui_story_5075_50750201_82_dialog_content = "으음?",
  ui_story_5075_50750201_83_dialog_content = "여기 오기 전에 영빈관 시녀 얘길 들었어요... 단당 씨, 제나라 세자랑 약혼하신 건가요?",
  ui_story_5075_50750201_84_dialog_content = "시녀들 말하는 분위기가 그리 좋진 않았어요... 단당 씨가 빚 때문에 온 거라고도 했고요...",
  ui_story_5075_50750201_85_dialog_content = "그래서 혹시 단당 씨가 여기서 괴롭힘을 당하고 있진 않을까 해서요...",
  ui_story_5075_50750201_86_dialog_content = "PlayerName 공자...",
  ui_story_5075_50750201_87_dialog_content = "나는... 괜찮다.",
  ui_story_5075_50750201_88_dialog_content = "그 소문은 나도 들은 바 있다. 다만 그대의 귀에까지 들어갈 줄은 몰랐구나.",
  ui_story_5075_50750201_89_dialog_content = "국군께서는 확실히 그러한 뜻이 있으신 듯하나,\n내가 사양의 뜻을 명백히 전했으니 강요하실 수는 없을 게다.",
  ui_story_5075_50750201_X89_dialog_content = "빚 이야기라면... 업나라가 빌린 차관 때문에 내가 볼모로 온 것은 사실이다.",
  ui_story_5075_50750201_X90_dialog_content = "허나 그것은 아랫사람들이 함부로 논할 수 있는 일이 아니다.\n함부로 입을 놀린 자들은 내 조만간 합당한 처분을 내릴 것이야.",
  ui_story_5075_50750201_X91_dialog_content = "단당 씨...",
  ui_story_5075_50750201_90_dialog_content = "걱정할 필요 없다. 내 이곳에 자리를 잡은 지도 이미 오래니, 고립무원의 신세도 아니니라.",
  ui_story_5075_50750201_91_dialog_content = "이 큰 궁에서 감히 나를 공공연히 모욕할 이는 없느니라.",
  ui_story_5075_50750201_92_dialog_content = "그럼 세자도요?",
  ui_story_5075_50750201_93_dialog_content = "후훗, 물론이지! 게다가 세자는 아직...",
  ui_story_5075_50750201_94_dialog_content = "단당! 단당! 무사한 거야?!",
  ui_story_5075_50750201_95_dialog_content = "...세자?! 밤이 깊었습니다. 돌아가서 쉬어야지요.",
  ui_story_5075_50750201_96_dialog_content = "단당이 걱정되어 와 봤어.",
  ui_story_5075_50750201_97_dialog_content = "방금 지진이 무척 심했는데, 괜찮아? 다친 곳은 없어? 무섭진 않았어?",
  ui_story_5075_50750201_98_dialog_content = "휴, 걱정 마세요. 내 어디도 다치지 않았습니다.",
  ui_story_5075_50750201_99_dialog_content = "그보다 세자가 호위도 없이 돌아다닌 것을 대왕님께서 아시면 또 손바닥을 맞을 것입니다.",
  ui_story_5075_50750201_100_dialog_content = "나, 난... 이미 어른이야! 손바닥 맞는 것 정도는... 무섭지 않아!",
  ui_story_5075_50750201_101_dialog_content = "게다가 사나이 대장부가 위기의 순간에 정혼자 곁에 없으면 안 되지!",
  ui_story_5075_50750201_102_dialog_content = "푸훕──",
  ui_story_5075_50750201_103_dialog_content = "어찌 또 함부로 그런 말을──",
  ui_story_5075_50750201_104_dialog_content = "호오, 대장부라, 아무래도 근래 들어 노부가 세자에게 소홀했던 모양입니다.",
  ui_story_5075_50750201_105_dialog_content = "세자의 학업은 지금까지 학동의 기준으로 진행해 왔습니다만, 세자가 이미 대장부가 되었다면...",
  ui_story_5075_50750201_106_dialog_content = "학사들에게 고하여 세자의 학업량을 배로 늘리도록 하지요!",
  ui_story_5075_50750201_107_dialog_content = "시...싫어요! 대장부 안 할래요!",
  ui_story_5075_50750201_108_dialog_content = "이, 이 세자 비록 웅대한 뜻을 품고 있으나, 심신은 아직 강건함이 부족하니,\n그런 대임을 짊어지는 것은 힘들 것 같습니다!",
  ui_story_5075_50750201_109_dialog_content = "...휴, 피곤하네. 이제 돌아가서 쉴래요~",
  ui_story_5075_50750201_110_dialog_content = "단당, 그럼 내일 또 놀자!",
  ui_story_5075_50750201_111_dialog_content = "궁에 업나라 요리를 잘하는 요리사가 새로 들어왔어.\n아바마마께서 단당을 내일 식사에 초대하시겠대.",
  ui_story_5075_50750201_112_dialog_content = "꼭 와야 돼!",
  ui_story_5075_50750201_113_dialog_content = "하아...",
  ui_story_5075_50750201_114_dialog_content = "감사드립니다. 스승님이 아니었으면 세자도 얌전히 돌아가지 않았을 것입니다.",
  ui_story_5075_50750201_115_dialog_content = "PlayerName 공자, 이분은 국군 곁에서 정무를 보좌하는 제나라의 국사님이시다.",
  ui_story_5075_50750201_116_dialog_content = "그리고 나의 스승님이시지.",
  ui_story_5075_50750201_117_dialog_content = "내 다년간 스승님의 가르침과 보살핌이 있었던 덕분에, 제나라에서 무탈하게 자랄 수 있었다.",
  ui_story_5075_50750201_118_dialog_content = "(그렇게 대단한 사람이란 말이야? 잠깐만... 용주에선 어떻게 예를 갖춰서 인사를 한다고 했더라?!)",
  ui_story_5075_50750201_119_dialog_content = "국사님을 뵙습니다!",
  ui_story_5075_50750201_120_dialog_content = "스승님, 이쪽은 아스트라에서 온 PlayerName 공자입니다. 아까 잔치에서 뵀었지요.",
  ui_story_5075_50750201_121_dialog_content = "으음, 인상이 깊더군요.",
  ui_story_5075_50750201_122_dialog_content = "(역시 단당 씨의 스승님인가... 이 시선, 아까 잔치에서 주목받았을 때보다 더 긴장되네...)",
  ui_story_5075_50750201_123_dialog_content = "어머? 스승님께서 들고 계신 그 서신의 표식은...",
  ui_story_5075_50750201_124_dialog_content = "「순검사」에서 나온 급보입니다.",
  ui_story_5075_50750201_125_dialog_content = "혹시... 일전에 요마가 늘어난 탓에 임시로 성밖 해안 방어에 투입된 부대 말씀이신지요.",
  ui_story_5075_50750201_126_dialog_content = "아무래도 저들의 상대는 이제 요마뿐만이 아닌 듯합니다.",
  ui_story_5075_50750201_127_dialog_content = "급보에 따르면 조금 전 지진 뒤로 갑자기 근해에 광폭한 수요령이 나타나\n사람을 해치려 했다고 합니다.",
  ui_story_5075_50750201_128_dialog_content = "순찰대가 즉시 제지했습니다만, 다른 곳에서도 같은 일이 벌어지고 있을지도 모릅니다.",
  ui_story_5075_50750201_129_dialog_content = "수요령이 광폭해졌다니 어찌 그런 일이...\n설마 아까 그 지진이 천재가 아니라 다른 원인이 있는 것은 아닐지요.",
  ui_story_5075_50750202_1_dialog_content = "때문에 노부도 이 건의 조사를 부탁하고자 온 것입니다.",
  ui_story_5075_50750202_2_dialog_content = "알겠습니다. 그럼 내일 당장──",
  ui_story_5075_50750202_3_dialog_content = "내일은 대왕님과 더불어 세자를 돌봐야 하지 않았습니까?",
  ui_story_5075_50750202_4_dialog_content = "아...",
  ui_story_5075_50750202_5_dialog_content = "제가 도와드려도 될까요?",
  ui_story_5075_50750202_6_dialog_content = "단당 씨는 바쁘지만 전 한가하니까요. 조사 정도라면 저도 할 수 있을 거예요.",
  ui_story_5075_50750202_7_dialog_content = "그럴 수는 없다.\n내 갑자기 PlayerName 공자에게 사절이 되어 달라 한 것도 애초에 무리한 청이었다.",
  ui_story_5075_50750202_8_dialog_content = "헌데 어찌 제나라 일로도 그대를 거듭 곤란하게 만들 수 있겠느냐.",
  ui_story_5075_50750202_9_dialog_content = "노부가 보기에는 가당한 일입니다만.",
  ui_story_5075_50750202_10_dialog_content = "스승님...?",
  ui_story_5075_50750202_11_dialog_content = "군주께서 쓰신 교류 계획은 잘 보았습니다.",
  ui_story_5075_50750202_12_dialog_content = "허나 연회 때 모습을 보아, 대왕님께서는 당장 추진하실 뜻은 없으심이 분명합니다.",
  ui_story_5075_50750202_13_dialog_content = "참으로 유감입니다.",
  ui_story_5075_50750202_14_dialog_content = "PlayerName 공도 사절로서 대왕님 앞에 나아가 뜻을 더 전하고 싶으시겠지요.",
  ui_story_5075_50750202_15_dialog_content = "맞아요.",
  ui_story_5075_50750202_16_dialog_content = "전 많은 사람들의 기대와 도움에 힘입어 여기까지 왔어요. 절대 빈손으로 돌아갈 순 없어요.",
  ui_story_5075_50750202_17_dialog_content = "그렇다면 좋은 기회가 되겠군요.",
  ui_story_5075_50750202_18_dialog_content = "춘삭절을 눈앞에 둔 지금은 성안 사람들의 왕래도 늘어났고, 다양한 행사도 펼쳐지고 있습니다.",
  ui_story_5075_50750202_19_dialog_content = "이러한 시기에 요마와 수요령이 활개 친다면 백성들에게 큰 해악을 끼치고 말 것입니다.",
  ui_story_5075_50750202_20_dialog_content = "만약 누군가 한시라도 빨리 이 일을 해결한다면, 그 공이 크다 말할 수 있겠지요.",
  ui_story_5075_50750202_21_dialog_content = "하면 대왕님께서도 필시 논공행상을 하실 것입니다.",
  ui_story_5075_50750202_22_dialog_content = "상이라면 괜찮아요. 영빈관엔 이미 어떻게 쓰는지도 모르는 물건들이 잔뜩 쌓여 있어서요...",
  ui_story_5075_50750202_23_dialog_content = "그래도 전 이 기회를 빌려서 국왕님이 꼭 저희 계획을 들어주셨으면 해요!",
  ui_story_5075_50750202_24_dialog_content = "국사님, 그 임무, 저한테 맡겨 주세요.",
  ui_story_5075_50750202_25_dialog_content = "단, 노부도 부탁이 하나 있습니다. 공이 승낙해 준다면 이 일을 맡기도록 하지요.",
  ui_story_5075_50750202_26_dialog_content = "어떤 부탁인가요?",
  ui_story_5075_50750202_27_dialog_content = "...되도록 은밀하게 일을 진행해야 합니다.\n이 일이 조정 사람들에게 누설되어서는 아니 될 것입니다.",
  ui_story_5075_50750202_28_dialog_content = "스승님, PlayerName 공자는 이역에서 건너와 제나라에서 운신이 편치 못한 몸인데,\n어찌 홀로 행동하라 할 수 있겠습니까.",
  ui_story_5075_50750202_29_dialog_content = "PlayerName 공에게 홀로 행동하라 하지는 않았습니다.",
  ui_story_5075_50750202_30_dialog_content = "말을 들을 때는 그 뜻을 살펴야 합니다. 군주께서는 조급해하고 계십니다.",
  ui_story_5075_50750202_31_dialog_content = "......",
  ui_story_5075_50750202_32_dialog_content = "단당 씨, 걱정 마세요.",
  ui_story_5075_50750202_33_dialog_content = "전 아스트라 대륙에 있을 때도 낯선 곳에서 의뢰를 받곤 했어요. 나름대로 경험이 많은걸요.",
  ui_story_5075_50750202_34_dialog_content = "좋습니다.",
  ui_story_5075_50750202_35_dialog_content = "군주, PlayerName 공을 배웅해 주시지요.",
  ui_story_5075_50750202_36_dialog_content = "...예.",
  ui_story_5075_50750202_37_dialog_content = "PlayerName 공자──",
  ui_story_5075_50750202_38_dialog_content = "사과하거나 포기하라고 설득할 생각이신 거면, 말 안 들을 거예요.",
  ui_story_5075_50750202_39_dialog_content = "허나 또 PlayerName 공자를 분주히 다니게 하고, 나는 궁에만 있어서야...",
  ui_story_5075_50750202_40_dialog_content = "근데 말이죠. 연회에서 먹은 음식, 되게 맛있었어요.",
  ui_story_5075_50750202_41_dialog_content = "?",
  ui_story_5075_50750202_42_dialog_content = "단당 씨는요? 쌍사성에서 먹었던 것보다 훨씬 더 좋지 않았어요?",
  ui_story_5075_50750202_43_dialog_content = "그야 그렇지. 궁의 숙수가 직접 만든 것이니 말이야.",
  ui_story_5075_50750202_44_dialog_content = "그건 우리가 직접 만든 음식이 아니라는 뜻이죠. 그럼 쌀은 우리가 심었나요?",
  ui_story_5075_50750202_45_dialog_content = "물론 농민이 키운 것이지.",
  ui_story_5075_50750202_46_dialog_content = "그걸 우리가 성안까지 가져왔나요?",
  ui_story_5075_50750202_47_dialog_content = "아니지. 각지의 상인들이 옮긴 것이야.",
  ui_story_5075_50750202_48_dialog_content = "그럼 우리가 샀나요?",
  ui_story_5075_50750202_49_dialog_content = "그것도 아니지. 궁의 조달을 맡은 관원이 산 것이니까.",
  ui_story_5075_50750202_50_dialog_content = "그럼 단당 씨는 그 사람들을 곤란하게 만들었다고 생각하시나요?\n그리고 직접 그 일들을 전부 하실 건가요?",
  ui_story_5075_50750202_51_dialog_content = "...그것은 각자의 소임이다. 나도 그토록 거만한 생각을 하지는 않는다.",
  ui_story_5075_50750202_52_dialog_content = "그럼 이번 조사도 마찬가지예요.",
  ui_story_5075_50750202_53_dialog_content = "그 누구도 모든 일을 혼자서 다 할 순 없어요.\n단당 씨는 다른 일이 있고, 전 마침 그 일을 할 힘이 있어요. 그럼 제가 하는 거죠.",
  ui_story_5075_50750202_54_dialog_content = "누구나 남한테 신세를 지고, 의지하면서 살아가요. 세상은 그렇게 돌아가는 거니까요.",
  ui_story_5075_50750202_55_dialog_content = "아... 물론 제가 못 미더우신 거라면...",
  ui_story_5075_50750202_56_dialog_content = "그럴 리가 없지 않느냐!",
  ui_story_5075_50750202_57_dialog_content = "...참으로 난처한지고.\n내 이제 보니 PlayerName 공자는 사절보다 재담꾼이 더 잘 맞겠구나.",
  ui_story_5075_50750202_58_dialog_content = "그대가 그렇게까지 말하는데 내 어찌 더 거절할 수가 있겠느냐.",
  ui_story_5075_50750202_59_dialog_content = "아하하...",
  ui_story_5075_50750202_60_dialog_content = "다행이구나, 공자의 안색도 처음보다 자못 좋아졌어.",
  ui_story_5075_50750202_61_dialog_content = "크흠. 그렇게 티가 났나요?",
  ui_story_5075_50750202_62_dialog_content = "PlayerName 공자를 노심초사하게 만든 내 탓이다.\n사명의 부담도 모자라서 지진의 재앙까지 짐을 지워 주지 않았느냐...",
  ui_story_5075_50750202_63_dialog_content = "게다가 내가 억울한 일을 겪지는 않는지 염려까지 하였으니, 마음이 무거운 것이 당연하지.",
  ui_story_5075_50750202_64_dialog_content = "그럼 제가 괜한 걱정을 한 건가요?",
  ui_story_5075_50750202_65_dialog_content = "아니다, PlayerName 공자 덕분에 내 깨달은 바가 있으니 말이다.",
  ui_story_5075_50750202_66_dialog_content = "내 공자의 체면을 봐서라도 더 분발해야겠구나. 한시라도 빨리 이 일을 해결해야겠다.",
  ui_story_5075_50750202_67_dialog_content = "그래요. 그럼 같이 힘내요! 비록 같이 움직일 순 없지만요...",
  ui_story_5075_50750202_68_dialog_content = "그래도 마음은 하나이니, 목표를 향해 함께 나아갈 수 있을 게야.",
  ui_story_5075_50750202_69_dialog_content = "사절 나리, 모시러 나왔습니다.",
  ui_story_5075_50750202_70_dialog_content = "아, 주사관님, 저 데리러 오신 건가요?",
  ui_story_5075_50750202_71_dialog_content = "물론입니다. 제나라에 계시는 한 당신은 영빈관의 귀빈이십니다.\n어찌 대접에 소홀함이 있을 수 있겠습니까?",
  ui_story_5075_50750202_72_dialog_content = "그럼 저 먼저 가 볼게요. 무슨 일 있으면 다시 만나요.",
  ui_story_5075_50750202_73_dialog_content = "궁에서 좋은 소식을 기다리마.",
  ui_story_5075_50750202_74_dialog_content = "<color=#e8d9bb>잠시 후</color>",
  ui_story_5075_50750202_75_dialog_content = "전하? 어찌 홀로 이런 곳에 계십니까?",
  ui_story_5075_50750202_76_dialog_content = "구야, 돌아왔구나. 내 말했던 일은 순조롭게 되었느냐.",
  ui_story_5075_50750202_77_dialog_content = "죄송합니다. 아직 진상을 파악하지 못했습니다.",
  ui_story_5075_50750202_78_dialog_content = "허나 최근에도 여전히 다수의 밀정이 호진에서 활동하고 있었습니다.",
  ui_story_5075_50750202_79_dialog_content = "제가 전하 곁에 없을 때는 부디 조심해 주십시오.",
  ui_story_5075_50750202_80_dialog_content = "알겠다. 우리 구가 고생이 많구나.",
  ui_story_5075_50750202_81_dialog_content = "허나 내 당분간 궁에 머물 것이니, 아마 큰 위험은 없을 것이야.",
  ui_story_5075_50750202_82_dialog_content = "아, 침전에 돌아가면 내게 잊지 말고 편지를 쓰라고 일러 주겠느냐.",
  ui_story_5075_50750202_83_dialog_content = "월백 선장 쪽도 화물을 모두 보내고 호진으로 돌아왔거늘...",
  ui_story_5075_50750202_84_dialog_content = "우리 「선기경」 나리는 어찌 또 감감무소식인 게냐. 영문 모를 말만 남기고 말이다...",
  ui_story_5075_50750202_85_dialog_content = "아무래도 내 직접 붓을 들어 한바탕 추궁을 해야 쓰겠구나.",
  ui_story_5075_50750202_86_dialog_content = "...어머?",
  ui_story_5075_50750202_87_dialog_content = "전하, 왜 그러십니까?",
  ui_story_5075_50750202_88_dialog_content = "아무것도 아니니라. 조금 놀랐을 뿐이야.",
  ui_story_5075_50750202_89_dialog_content = "모르는 사이에 매화 꽃봉오리가 벌어졌구나...",
  ui_story_5075_50750202_90_dialog_content = "전하께서는 해당화만을 좋아하지 않으셨습니까?",
  ui_story_5075_50750202_91_dialog_content = "허나 오늘은 매화꽃은 유독 아름답게 피었지 않느냐.",
  ui_story_5075_50750301_1_dialog_content = "(자신만만하게 임무를 받아버렸지만...)",
  ui_story_5075_50750301_2_dialog_content = "(생각지도 못한 장애물이 있었다!)",
  ui_story_5075_50750301_3_dialog_content = "저기... 전 그냥 거리를 좀 걷고 싶을 뿐인데요. 이렇게까지 몰려다닐 필요는 없지 않나요?",
  ui_story_5075_50750301_4_dialog_content = "사절 나리께서는 존귀한 신분이십니다. 고작 여섯 명의 호위로는 최소한의 의전에 불과합니다.",
  ui_story_5075_50750301_5_dialog_content = "제가 이미 호위를 아홉 명 더 늘려달라는 청을 올렸습니다.\n그 정도면 안전을 보장할 수 있겠지요.",
  ui_story_5075_50750301_6_dialog_content = "더 늘린다고요?!",
  ui_story_5075_50750301_7_dialog_content = "뭐, 됐어요... 그것보다...",
  ui_story_5075_50750301_8_dialog_content = "왜 거리에 사람이 하나도 없죠?",
  ui_story_5075_50750301_9_dialog_content = "물론 사절 나리의 흥을 깨지 않도록 사람들을 물렸기 때문이지요.",
  ui_story_5075_50750301_10_dialog_content = "이래서야 전혀 둘러보는 맛이 안 나잖아요!",
  ui_story_5075_50750301_11_dialog_content = "(아무리 봐도 보호가 너무 과하잖아!)",
  ui_story_5075_50750301_12_dialog_content = "(이대로면 조사는커녕, 용주 사람이랑 이야기조차 나눌 수 없겠어.)",
  ui_story_5075_50750301_13_dialog_content = "...번거롭게 그럴 거 없습니다. 제가 전해 드리겠습니다.",
  ui_story_5075_50750301_14_dialog_content = "(음? 밖에서 무슨 얘길 하는 거지?)",
  ui_story_5075_50750301_15_dialog_content = "허나 궁에서 제게 친히 사절 나리에게 전하라고 분부하셨습니다.\n부디 소녀를 난처하게 만들지 마시지요.",
  ui_story_5075_50750301_16_dialog_content = "어찌 감히 그러겠습니까. 안으로 드시지요.",
  ui_story_5075_50750301_17_dialog_content = "사절 나리, 평안하시온지요.",
  ui_story_5075_50750301_18_dialog_content = "이것은 궁에 새로 들어온 숙수가 만든 간식이옵니다.\n귀인들 사이에서도 맛이 좋다 소문이 자자하지요.",
  ui_story_5075_50750301_19_dialog_content = "소녀 명을 받고 사절 나리께 드리러 왔사옵니다.",
  ui_story_5075_50750301_20_dialog_content = "고마워요. 어? 따뜻하네요?",
  ui_story_5075_50750301_21_dialog_content = "호진은 비록 기후가 온화한 땅이나, 지금은 겨울이옵니다.",
  ui_story_5075_50750301_22_dialog_content = "사절 나리께서 즐겁게 드실 수 있도록 그릇 바닥에 화로를 넣어 데웠사옵니다.",
  ui_story_5075_50750301_23_dialog_content = "이 화로는 업나라에서 전해진 새로운 공예 기술이옵니다.",
  ui_story_5075_50750301_24_dialog_content = "이는 궁에서 쓰이는 양식이고, 특별히 장인으로 하여금 안쪽 면에 꽃을 새겨넣어\n장식의 역할도 할 수 있지요.",
  ui_story_5075_50750301_25_dialog_content = "안쪽 면에요? 보이지도 않는 곳에 꽃을 조각했다는 건가요?",
  ui_story_5075_50750301_26_dialog_content = "어느 귀인께서 말씀하셨사옵니다... 「보이지 않는 곳이야말로 일을 꾀하기 좋다」고 말이지요.",
  ui_story_5075_50750301_27_dialog_content = "네?",
  ui_story_5075_50750301_28_dialog_content = "소녀의 혼잣말일 뿐이옵니다. 그럼 천천히 드시지요.\n소녀는 이만 궁으로 돌아가 보고드리겠습니다.",
  ui_story_5075_50750301_29_dialog_content = "사절 나리, 지금 바로 간식을 드시겠습니까? 다른 음식도 만들어 드릴까요?",
  ui_story_5075_50750301_30_dialog_content = "괜찮아요. 좀 졸려서 잠깐 자야겠어요. 일단 가셔도 돼요.",
  ui_story_5075_50750301_31_dialog_content = "아, 과자는 두고 가세요. 일어나면 먹을게요.",
  ui_story_5075_50750301_32_dialog_content = "예.",
  ui_story_5075_50750301_33_dialog_content = "<color=#e8d9bb>화로 안에서는 가느다란 연기가 솟아올랐고, 겹겹이 덮인 구리 조각의 틈새에서는\n흔들리는 불길을 엿볼 수 있었다.</color>",
  ui_story_5075_50750301_34_dialog_content = "<color=#e8d9bb>찰칵.</color>",
  ui_story_5075_50750301_35_dialog_content = "<color=#e8d9bb>불꽃이 꺼지는가 싶더니, 겹쳐 있던 구리 조각이 갑자기 서서히 벌어지기 시작했다.</color>",
  ui_story_5075_50750301_36_dialog_content = "<color=#e8d9bb>그리고 탁자 위에는 아름다운 해당화가 피어났다.</color>",
  ui_story_5075_50750301_37_dialog_content = "(안에 영패랑 쪽지가 있었잖아?)",
  ui_story_5075_50750301_38_dialog_content = "부디 사절 나리께서 제나라에 머무는 동안 건강하고 즐겁게 지내시어,\n<color=#FFB400>작화군주 전하</color>께 심려를 끼치는 일이 없기를 바라옵니다.",
  ui_story_5075_50750301_39_dialog_content = "(단당 씨의 말을 전하러 온 거였구나!)",
  ui_story_5075_50750301_40_dialog_content = "(영패의 표식은... 그 「순검사」라는 곳이었나? ...근데 이 영패는 뭐에 쓰는 거지?)",
  ui_story_5075_50750301_41_dialog_content = "(쪽지에... 지도가 있어! 주소도 나와 있고!)",
  ui_story_5075_50750301_42_dialog_content = "(마침 시녀들한테도 자리를 비켜달라 했으니까, 이 틈에 도망치자!)",
  ui_story_5075_50750301_43_option_content = "[감응한다]",
  ui_story_5075_50750301_44_dialog_content = "(가까이 있는 호위는... 동쪽에 2명, 남쪽에 3명... 서쪽으로 가자.)",
  ui_story_5075_50750301_45_dialog_content = "어이, 빨리 일어나 봐! 사절 나리가 사라지셨어!",
  ui_story_5075_50750301_46_dialog_content = "넌 여기 남아. 난 저쪽을 찾아볼게!",
  ui_story_5075_50750301_47_dialog_content = "(순식간에 들켜버렸잖아... 다행히 마당 끝까지 왔으니까, 이젠 담만 넘으면...)",
  ui_story_5075_50750301_48_dialog_content = "(...높잖아!)",
  ui_story_5075_50750301_49_dialog_content = "사절 나리! 사절 나리──",
  ui_story_5075_50750301_50_dialog_content = "(이러다 포위당하겠어... 방법을 찾아야 해...)",
  ui_story_5075_50750301_51_dialog_content = "숨바꼭질하는 게냐?",
  ui_story_5075_50750301_52_dialog_content = "누, 누구야?!",
  ui_story_5075_50750301_53_dialog_content = "여기, 이쪽이니라~",
  ui_story_5075_50750301_54_dialog_content = "고개를 들어 보거라.",
  ui_story_5075_50750301_55_dialog_content = "어? 꼬마애? 왜 담 위에 있어...? 위험하잖아!",
  ui_story_5075_50750301_56_dialog_content = "전혀 위험하지 않느니라. 이 몸은 밧줄 위조차도 걸을 수 있으니 말이다.",
  ui_story_5075_50750301_57_dialog_content = "그대는 아직 물음에 답하지 않았다. 숨바꼭질을 하고 있는 게냐? 이 몸도 시켜주거라.",
  ui_story_5075_50750301_58_dialog_content = "놀고 있는 거 아니거든...",
  ui_story_5075_50750301_59_dialog_content = "사절 나리? 거기 계십니까?",
  ui_story_5075_50750301_60_dialog_content = "이런! 미안, 난 급한 일이 있어서 먼저 가 볼게──",
  ui_story_5075_50750301_61_dialog_content = "!",
  ui_story_5075_50750301_62_dialog_content = "아, 저기, 전 그냥 잠깐 산책하러 나온 건데요...",
  ui_story_5075_50750301_63_dialog_content = "사절 나리? 여기 계십니까?",
  ui_story_5075_50750301_64_dialog_content = "?",
  ui_story_5075_50750301_65_dialog_content = "이쪽에도 안 계신다니, 대체 어디 가신 거지?",
  ui_story_5075_50750301_66_dialog_content = "사절 나리──",
  ui_story_5075_50750301_67_dialog_content = "역시 숨바꼭질을 하고 있지 않느냐.",
  ui_story_5075_50750301_68_dialog_content = "방금... 호위들이 날 전혀 못 본 것 같은 반응이던데... 설마 네가 한 거야?",
  ui_story_5075_50750301_69_dialog_content = "후후, 그냥 재주를 살짝 부려 보았을 뿐이니라.",
  ui_story_5075_50750301_70_dialog_content = "?",
  ui_story_5075_50750301_71_dialog_content = "?",
  ui_story_5075_50750301_72_dialog_content = "아니, 틀렸느니라.",
  ui_story_5075_50750301_73_dialog_content = "이런 상황에서는 이 진예 님의 위엄에 감격해 눈물을 흘리면서\n머리를 숙여 절을 해야 마땅하지 않느냐?",
  ui_story_5075_50750301_74_dialog_content = "위엄...?",
  ui_story_5075_50750301_75_dialog_content = "크흠, 내가 왜 그럴 거라 생각하는데?",
  ui_story_5075_50750301_76_dialog_content = "오는 길에 다리에서 이야기꾼에게 들었느니라~",
  ui_story_5075_50750301_77_dialog_content = "요즘은 이런 위엄 있는 인물이 유행한다던데, 아닌 게냐?",
  ui_story_5075_50750301_78_dialog_content = "그 유행이 지금 같은 상황을 말하는 건 아니지 싶은데...",
  ui_story_5075_50750301_79_dialog_content = "그나저나 너...",
  ui_story_5075_50750301_80_dialog_content = "분명히 이 근처에서 소리가 났어.",
  ui_story_5075_50750301_81_dialog_content = "하지만 방금 살펴봤는데... 혹시 모르니 한 번 더 찾아볼까.",
  ui_story_5075_50750301_82_dialog_content = "그, 그래! 우린 지금 숨바꼭질하고 있는 거야!",
  ui_story_5075_50750301_83_dialog_content = "위엄이 넘치는 진예 님... 부디 여길 벗어날 수 있게 좀 도와주세요!",
  ui_story_5075_50750301_84_dialog_content = "호오~ 꼬마가 그래도 꽤 말을 잘하는구나.",
  ui_story_5075_50750301_85_dialog_content = "안심하거라. 숨바꼭질이라면 이 몸의 장기이니 말이다.",
  ui_story_5075_50750301_86_dialog_content = "그 비결이라면, 바로 단숨에 도망치는 것이니라~",
  ui_story_5075_50750302_1_dialog_content = "후우... 하아... 하아...",
  ui_story_5075_50750302_2_dialog_content = "너... 아무래도... 숨바꼭질에 대해... 뭔가 오해가... 있는 것 같아...",
  ui_story_5075_50750302_3_dialog_content = "그럴 리 없느니라.",
  ui_story_5075_50750302_4_dialog_content = "보아라, 이렇게 무사히 밖으로 나오지 않았느냐.",
  ui_story_5075_50750302_5_dialog_content = "오는 동안 아무에게도 들키지 않았지.",
  ui_story_5075_50750302_6_dialog_content = "내 말은 그러니까 대놓고 뛰쳐나가는 건 숨바꼭질이라고 안 한다고...",
  ui_story_5075_50750302_7_dialog_content = "게다가 아무도 우릴 못 보다니, 이건 반칙이야.",
  ui_story_5075_50750302_8_dialog_content = "...아니지, 생각해 보니까 도움이 많이 됐잖아.",
  ui_story_5075_50750302_9_dialog_content = "고마워, 진예... 아니지... 진예 님?",
  ui_story_5075_50750302_10_dialog_content = "푸하하, 그대가 이 몸과 같이 놀아준 이상, 굳이 그렇게 부를 필요는 없느니라.",
  ui_story_5075_50750302_11_dialog_content = "알겠어, 진예. 난 PlayerName...",
  ui_story_5075_50750302_12_dialog_content = "아이테르겠지?",
  ui_story_5075_50750302_13_dialog_content = "알고 있느니라.",
  ui_story_5075_50750302_14_dialog_content = "어?",
  ui_story_5075_50750302_15_dialog_content = "사절 나리? 밖에 계신 건가요?",
  ui_story_5075_50750302_16_dialog_content = "빨리 여기서 벗어나야겠어...",
  ui_story_5075_50750302_17_dialog_content = "사절 나리! 역시 사절 나리셨군요!",
  ui_story_5075_50750302_18_dialog_content = "왜 호위도 없이 혼자 나오신 거죠? 위험하옵니다!",
  ui_story_5075_50750302_19_dialog_content = "여봐라!",
  ui_story_5075_50750302_20_dialog_content = "잠깐만요, 호위는 필요...",
  ui_story_5075_50750302_21_dialog_content = "찍찍찍!",
  ui_story_5075_50750302_22_dialog_content = "꺄앗──! 이, 이상한 쥐다! 사...살려줘!",
  ui_story_5075_50750302_23_dialog_content = "<color=#e8d9bb>스윽!</color>",
  ui_story_5075_50750302_24_dialog_content = "꺄아악! 수요령이... 수요령이 사람을 문다!",
  ui_story_5075_50750302_25_dialog_content = "...쉿, 조용히 하지 못할까.",
  ui_story_5075_50750302_26_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_5075_50750302_27_dialog_content = "뭐, 뭘 한 거야?",
  ui_story_5075_50750302_28_dialog_content = "그냥 잠깐 자게 만들었을 뿐이니라.",
  ui_story_5075_50750302_29_dialog_content = "다음은 네 녀석이다.",
  ui_story_5075_50750302_30_dialog_content = "찍...",
  ui_story_5075_50750302_31_dialog_content = "아무리 봐도 보통 쥐는 아니네...",
  ui_story_5075_50750302_32_dialog_content = "이게 리청이 전에 말한... 아직 사람의 모습이 안 된 수요령인 건가?",
  ui_story_5075_50750302_33_dialog_content = "게다가... 왠지 불편한 느낌이 들어... 설마 광폭해지고 있는 건가?",
  ui_story_5075_50750302_X33_dialog_content = "급보에 따르면 조금 전 지진 뒤로 갑자기 근해에 광폭한 수요령이 나타나\n사람을 해치려 했다고 합니다.",
  ui_story_5075_50750302_34_dialog_content = "그게 보인단 말이냐?",
  ui_story_5075_50750302_35_dialog_content = "하면 이것도 볼 수 있겠구나.",
  ui_story_5075_50750302_36_dialog_content = "<color=#e8d9bb>소녀의 손끝이 쓰러진 수요령의 몸을 스치자, 몸에서 검은 그림자가 빠져나왔다.</color>",
  ui_story_5075_50750302_37_dialog_content = "<color=#e8d9bb>그것은 마치 혼탁한 연기처럼 보였고, 희미한 악의가 모여 있었다.</color>",
  ui_story_5075_50750302_38_option_content = "[감응을 시도한다]",
  ui_story_5075_50750302_39_dialog_content = "...증오해...",
  ui_story_5075_50750302_40_dialog_content = "으윽...",
  ui_story_5075_50750302_41_dialog_content = "감응해 봤는데, 부식된 액체를 건드린 듯한 통증이 느껴졌어... 저게 대체 뭐야?",
  ui_story_5075_50750302_42_dialog_content = "망자의 넋이 얽혀서 생긴 나쁜 것이니라.",
  ui_story_5075_50750302_43_dialog_content = "조심해! 움직이기 시작했어! 도망치려는 것 같아!",
  ui_story_5075_50750302_44_dialog_content = "<color=#e8d9bb>그러나 눈앞의 소녀는 얼굴색 하나 변하지 않았다.</color>",
  ui_story_5075_50750302_45_dialog_content = "<color=#e8d9bb>그 후 가볍게 손가락을 비비자, 거칠게 날뛰던 검은 기운은\n마치 촛불이 꺼지듯 흔적도 없이 사라져 버렸다.</color>",
  ui_story_5075_50750302_46_dialog_content = "괘씸한지고, 내 이런 귀찮은 일을 처리하려고 잠도 못 자고 성안에 달려온 것이 아니거늘.",
  ui_story_5075_50750302_47_dialog_content = "PlayerName, 그대는 일단 혼자 숨바꼭질하고 있거라.\n이 몸은 다른 할 일이 있느니라.",
  ui_story_5075_50750302_48_dialog_content = "잠깐만!",
  ui_story_5075_50750302_49_dialog_content = "여기 쓰러진 둘은 어떡해...?",
  ui_story_5075_50750302_50_dialog_content = "이런, 내 현장 뒤처리를 잊었구나.",
  ui_story_5075_50750302_51_dialog_content = "읏챠.",
  ui_story_5075_50750302_52_dialog_content = "<color=#e8d9bb>소녀는 시녀의 어깨를 떠받히더니 그녀를 영빈관까지 「날려서」 돌려보냈다.</color>",
  ui_story_5075_50750302_53_dialog_content = "<color=#e8d9bb>그리고 수요령의 꼬리를 잡고 하늘 멀리 휙 던져버렸다.</color>",
  ui_story_5075_50750302_54_dialog_content = "이래도 되는 거야?!",
  ui_story_5075_50750302_55_dialog_content = "당연하지. 수요령은 그대가 생각하는 것만큼 약하지는 않느니라.",
  ui_story_5075_50750302_56_dialog_content = "이런 일조차 못 견뎌낸다면, 차라리 수행 같은 건 그만두고 평생 동물로 사는 게 나으니라.",
  ui_story_5075_50750302_57_dialog_content = "음... 아까 감응했을 때 약간 비슷하다고 생각했어. 게다가 그 특이한 모습...",
  ui_story_5075_50750302_58_dialog_content = "역시 너도 수요령이지?",
  ui_story_5075_50750302_59_dialog_content = "...어라? 어디 갔어?",
  ui_story_5075_50750302_60_dialog_content = "(검은 기운에 대해서도 물어보려고 했는데... 뭐, 어쩔 수 없지.)",
  ui_story_5075_50750302_61_dialog_content = "(조사를 계속하다 보면 다시 만날 수 있을지도 몰라.)",
  ui_story_5075_50750302_62_dialog_content = "(우선 종이에 적혀있던 주소로 가보자.)",
  ui_story_5075_50750302_63_dialog_content = "......",
  ui_story_5075_50750401_1_dialog_content = "춘삭절에 달콤한 귤이 빠질 수 없죠!",
  ui_story_5075_50750401_2_dialog_content = "무료로 시식해 보세요! 안 달면 돈은 안 받습니다!",
  ui_story_5075_50750401_3_dialog_content = "참깨강정, 탕과, 사탕 사세요! 할아버지표 원조 간식! 한번 보고 가세요!",
  ui_story_5075_50750401_4_dialog_content = "(진짜 시끌벅적하네. 역시 혼자 편하게 다니니까 좋잖아.)",
  ui_story_5075_50750401_5_dialog_content = "실례합니다, 「어림가」에 가려면 어떻게 가야 하죠?",
  ui_story_5075_50750401_6_dialog_content = "거긴 꽤 멉니다. 일단은 사람이 가장 많은 저 다리까지 간 다음에,\n길목을 지나서 주변에 다시 물어보세요.",
  ui_story_5075_50750401_7_dialog_content = "고마워요, 그나저나 사람이 진짜 많네요.",
  ui_story_5075_50750401_8_dialog_content = "호진에는 처음입니까? 여긴 매년 춘삭절이 되면 사당에 장이 섭니다.\n다들 무척이나 기다리는 날이지요.",
  ui_story_5075_50750401_9_dialog_content = "바로 저 거리가 장터입니다.",
  ui_story_5075_50750401_10_dialog_content = "조금 있으면 유명 예인이 공연도 한다는데, 괜찮으면 보고 가시지요.",
  ui_story_5075_50750401_11_dialog_content = "고마워요. 시간 나면 가 볼게요.",
  ui_story_5075_50750401_12_dialog_content = "휴, 그나저나 아깝게 됐군요. 예전엔 지금보다 더 시끌벅적했는데 말입니다.",
  ui_story_5075_50750401_13_dialog_content = "<color=#e8d9bb>퍼엉!</color>",
  ui_story_5075_50750401_14_dialog_content = "무슨 소리죠?",
  ui_story_5075_50750401_15_dialog_content = "아, 애들이 폭죽을 터트리며 놀고 있는 겁니다.",
  ui_story_5075_50750401_16_dialog_content = "이거 가지곤 부족해! 하나 더!",
  ui_story_5075_50750401_17_dialog_content = "폭죽아! 수요령도 몰아내고 악운도 날려줘!",
  ui_story_5075_50750401_18_dialog_content = "<color=#e8d9bb>펑! 퍼엉!</color>",
  ui_story_5075_50750401_19_dialog_content = "하하하하!",
  ui_story_5075_50750401_20_dialog_content = "찍...",
  ui_story_5075_50750401_21_dialog_content = "저게 지금 노는 건가요? 길에서 저러면 위험하잖아요!",
  ui_story_5075_50750401_22_dialog_content = "게다가 저 수요령은 날뛰지도 않았고... 사람을 해칠 생각은 없었다구요!",
  ui_story_5075_50750401_23_dialog_content = "괜찮습니다. 평소의 춘삭절에도 폭죽을 터트려 수요령을 쫓는 전통 의식이 있으니 말입니다.",
  ui_story_5075_50750401_24_dialog_content = "다만 예전엔 상인들이 고용한 수요령 연기자였고,\n지금 저 애들은 진짜 수요령을 쫓고 있다는 차이뿐이죠.",
  ui_story_5075_50750401_25_dialog_content = "지금까진 저도 그저 의식일 뿐이라 생각했지만, 요즘 세상이 갈수록 험해지고 있습니다.",
  ui_story_5075_50750401_26_dialog_content = "어쩌면 수요령이 정말로 불길한 존재인지도 모르지요.",
  ui_story_5075_50750401_27_dialog_content = "당신은 외지인이지만, 그래도 수요령과는 얽히지 않는 게 좋을 겁니다.\n휴, 그럼 전 이만 가 보죠.",
  ui_story_5075_50750401_28_dialog_content = "왜 안 움직여? 죽은 건 아니겠지...?",
  ui_story_5075_50750401_29_dialog_content = "한 번 더 폭죽을 써 볼까?",
  ui_story_5075_50750401_30_dialog_content = "...안 돼, 아무리 그래도 이건 너무하잖아.",
  ui_story_5075_50750401_31_dialog_content = "!",
  ui_story_5075_50750401_32_dialog_content = "(그 검은 기운이야! 또 나타났어... 게다가 수요령의 몸으로 모이고 있어!)",
  ui_story_5075_50750401_33_dialog_content = "너희들! 얼른 피해!",
  ui_story_5075_50750401_34_dialog_content = "아? 뭔데?",
  ui_story_5075_50750401_35_dialog_content = "......",
  ui_story_5075_50750401_36_dialog_content = "이 녀석... 뭔가 이상한데?",
  ui_story_5075_50750401_37_dialog_content = "찍찍찍!",
  ui_story_5075_50750401_38_dialog_content = "이런! 늦겠어──",
  ui_story_5075_50750401_39_dialog_content = "받아라! 박치기!",
  ui_story_5075_50750401_40_dialog_content = "찍──",
  ui_story_5075_50750401_41_dialog_content = "박치기라니... 진짜 머리로 수요령을 날려버린 거야?",
  ui_story_5075_50750401_42_dialog_content = "조심해! 녀석이 돌아온다!",
  ui_story_5075_50750402_1_dialog_content = "찍...",
  ui_story_5075_50750402_2_dialog_content = "좋아, 이제 괜찮아. 야, 얌전히 있어. 또 다치면 어쩌려고 그래.",
  ui_story_5075_50750402_3_dialog_content = "찍──",
  ui_story_5075_50750402_4_dialog_content = "방금 네가 도와준 거지? 대단하네! 고마워.",
  ui_story_5075_50750402_5_dialog_content = "다 봤거든. 너 이 수요령을 구해주려고 나섰잖아. 너 참 좋은 사람이구나!",
  ui_story_5075_50750402_6_dialog_content = "아하하... 난 아무것도 안 했는걸. 녀석은 네가 제압했고.",
  ui_story_5075_50750402_7_dialog_content = "그나저나 너 진짜 몸이 빠르네. 사람들은 아마 무슨 일이 있었는지도 모를걸.",
  ui_story_5075_50750402_8_dialog_content = "이게 내 생업이거든.",
  ui_story_5075_50750402_9_dialog_content = "아, 내 소개를 안 했구나. 난 나송이야. 떠돌이 도사라고나 할까.",
  ui_story_5075_50750402_10_dialog_content = "찍찍찍!",
  ui_story_5075_50750402_11_dialog_content = "평소엔 이곳저곳을 다니면서 요마 퇴치를 하고 있어.",
  ui_story_5075_50750402_12_dialog_content = "찍찍찍!",
  ui_story_5075_50750402_13_dialog_content = "요즘 근교의 수요령이 툭하면 이성을 잃고 날뛰어서 사람을 다치게 만들고 있거든.",
  ui_story_5075_50750402_14_dialog_content = "원인을 찾으려고 성에 와 봤는데, 경비가 삼엄한 호진도 마찬가지였을 줄은 몰랐네...",
  ui_story_5075_50750402_15_dialog_content = "끼익──!",
  ui_story_5075_50750402_16_dialog_content = "저기... 수요령 상태가 뭔가 이상하지 않아?",
  ui_story_5075_50750402_17_dialog_content = "아, 그렇네. 잡힌 뒤로 계속 날 물려고 하고 있어.",
  ui_story_5075_50750402_18_dialog_content = "조심해.",
  ui_story_5075_50750402_19_dialog_content = "괜찮아. 난 수요령 상대하는 일로 먹고살고 있으니까.",
  ui_story_5075_50750402_20_dialog_content = "이런 수요령은 말이지. 검지랑 엄지로 목덜미를 잡고, 손톱을 이렇게 한 다음에 요렇게 해서...",
  ui_story_5075_50750402_21_dialog_content = "꽉 잡으면 꼼짝도 못 해!",
  ui_story_5075_50750402_22_dialog_content = "그렇구나. 역시 전문가네!",
  ui_story_5075_50750402_23_dialog_content = "...아니, 지금 그게 문제가 아니잖아!",
  ui_story_5075_50750402_24_dialog_content = "좀 감응해 볼게...",
  ui_story_5075_50750402_25_dialog_content = "역시... 그 이상한 검은 기운이 아직도 이 수요령의 몸속에 남아 있어.",
  ui_story_5075_50750402_26_dialog_content = "이상한 검은 기운?",
  ui_story_5075_50750402_27_dialog_content = "응, 나한텐 보이거든! 왠지 수요령들은 그 검은 기운 때문에 광폭해지고 있는 것 같아.",
  ui_story_5075_50750402_28_dialog_content = "그런 거라면 내 전문 분야 밖이겠네. 아무래도 더 고명한 분을 불러야 할지도 모르겠어.",
  ui_story_5075_50750402_29_dialog_content = "아니면 세게 때리면 그 검은 기운이 나가려나?",
  ui_story_5075_50750402_30_dialog_content = "아마 힘들걸.",
  ui_story_5075_50750402_31_dialog_content = "근데 내가 방금 어떤 여자애를 만났는데...",
  ui_story_5075_50750402_32_dialog_content = "너희 누구야? 왜 갑자기 튀어나와서 뭘 계속 중얼거리고 있어?",
  ui_story_5075_50750402_33_dialog_content = "아, 깜빡할 뻔했네. 이 꼬맹이들도 있었지.",
  ui_story_5075_50750402_34_dialog_content = "참, 넌 이름이 뭐야?",
  ui_story_5075_50750402_35_dialog_content = "나? PlayerName.",
  ui_story_5075_50750402_36_dialog_content = "PlayerName, 그렇구나. 기억했어. 그럼 얘 좀 대신 잡고 있어줄래?",
  ui_story_5075_50750402_37_dialog_content = "어?",
  ui_story_5075_50750402_38_dialog_content = "찍찍찍!",
  ui_story_5075_50750402_39_dialog_content = "으악! 수요령을 던지면 어떡해... 큭, 엄청 날뛰잖아.",
  ui_story_5075_50750402_40_dialog_content = "(나송이 잡았을 땐 꼼짝도 안 하더니... 쟤 대체 얼마나 힘이 센 거야?\n으아아, 움직이지 마!)",
  ui_story_5075_50750402_41_option_content = "(강제 감응!)",
  ui_story_5075_50750402_42_dialog_content = "찍...",
  ui_story_5075_50750402_43_dialog_content = "휴... 이제야 얌전해졌네.",
  ui_story_5075_50750402_44_dialog_content = "<color=#e8d9bb>콩! 콩! 콩!</color>",
  ui_story_5075_50750402_45_dialog_content = "<color=#e8d9bb>나송은 벌로 아이들에게 가볍게 딱밤을 때려 주었다.</color>",
  ui_story_5075_50750402_46_dialog_content = "(근데 나송 쟤 힘으로 딱밤을 맞으면... 엄청 아플 것 같은데...)",
  ui_story_5075_50750402_47_dialog_content = "으아아앙──",
  ui_story_5075_50750402_48_dialog_content = "너 누구야?! 갑자기 왜 때려! 아프잖아!",
  ui_story_5075_50750402_49_dialog_content = "난 나송이야. 떳떳하니까 숨길 것도 없어.",
  ui_story_5075_50750402_50_dialog_content = "난 바른 일을 하며 살고 있으니까 어딜 가도 무서울 게 없거든.",
  ui_story_5075_50750402_51_dialog_content = "근데 너흰 이름을 말할 수 있겠어? 말해 봐. 너희 부모님한테 얘기하러 갈 테니까.",
  ui_story_5075_50750402_52_dialog_content = "왜 애들이 거리에서 폭죽을 터트려 약한 상대를 괴롭히는 걸 놔두냐고 따져야겠어.",
  ui_story_5075_50750402_53_dialog_content = "나, 난...",
  ui_story_5075_50750402_54_dialog_content = "아니, 내가 왜 이름을 말해야 되는데?",
  ui_story_5075_50750402_55_dialog_content = "엄마 아빠가 그랬어! 수요령들이 나쁜 기운을 가져와서 주변에 요마가 설치는 거라고!",
  ui_story_5075_50750402_56_dialog_content = "넌 수요령이랑 한패니까 나쁜 놈이 분명해!",
  ui_story_5075_50750402_57_dialog_content = "그건 그냥 미신이잖아.",
  ui_story_5075_50750402_58_dialog_content = "해서는 안 될 일은 하지 말아야지. 남이 뭐라 했다고 그게 너희 변명거리가 될 순 없어.",
  ui_story_5075_50750402_59_dialog_content = "너 수요령이 직접 요마를 데려온 거 봤어?",
  ui_story_5075_50750402_60_dialog_content = "그건... 못 봤지만, 대신 그 수요령이 우리 탕과를 훔쳤다구!",
  ui_story_5075_50750402_61_dialog_content = "우리가 같이 용돈을 모아서 산 건데, 잠깐 못 본 사이에 없어졌어.",
  ui_story_5075_50750402_62_dialog_content = "맞아, 맞아!",
  ui_story_5075_50750402_63_dialog_content = "물건을 훔치는 건 나쁜 녀석이야. 우린 나쁜 녀석을 정의롭게 혼내준 거라구!",
  ui_story_5075_50750402_64_dialog_content = "「잠깐 못 본 사이에」라면, 너희도 이 녀석이 훔친 걸 직접 본 건 아니겠네?",
  ui_story_5075_50750402_65_dialog_content = "그치만 그때 걔가 딱 도망갔다구. 걔가 아니면 또 누구겠어?",
  ui_story_5075_50750402_66_dialog_content = "PlayerName.",
  ui_story_5075_50750402_67_dialog_content = "그 수요령 입가에 뭐 묻은 거 있나 좀 봐 줄래? 꿀 같은 거 말이야.",
  ui_story_5075_50750402_68_dialog_content = "으음... 없어.",
  ui_story_5075_50750402_69_dialog_content = "몸에도 상처랑 진흙 말고 다른 건 아무것도 없어.",
  ui_story_5075_50750402_70_dialog_content = "그래도 그게 죄가 없다는 증거는 아니잖아!",
  ui_story_5075_50750402_71_dialog_content = "어쩌면 법술을 써서 휙 하고 탕과를 어디로 보내버렸을지도 몰라!",
  ui_story_5075_50750402_72_dialog_content = "어... 그런 대단한 능력을 음식 훔쳐먹는 데 쓴다고?",
  ui_story_5075_50750402_73_dialog_content = "너희가 말하는 탕과는 어떤 건데?",
  ui_story_5075_50750402_74_dialog_content = "탕과가 탕과지 뭐가 또 있어? 그 하얗고, 동그랗고, 꼭...",
  ui_story_5075_50750402_75_dialog_content = "껍질 벗긴 귤 같은 거?",
  ui_story_5075_50750402_76_dialog_content = "그래! 딱 봐도 맛있을 것 같은 탕과야! 수요령도 분명히 좋아할걸.",
  ui_story_5075_50750402_77_dialog_content = "그거 이 근처 할아버지네 가게에서 산 거지?",
  ui_story_5075_50750402_78_dialog_content = "너희 용돈을 다 모아서 산 거라면, 다른 간식은 아마 못 샀겠네.",
  ui_story_5075_50750402_79_dialog_content = "근데 어린애들은 먹성이 좋잖아? 마침 탕과 파는 가게 옆에서는 귤 시식도 할 수 있어.",
  ui_story_5075_50750402_80_dialog_content = "당연히 먹으러 갔겠지? 아니라고 하진 마.",
  ui_story_5075_50750402_81_dialog_content = "갔으면 간 거지! 그게 뭐 어쨌는데?",
  ui_story_5075_50750402_82_dialog_content = "그럼 너희 귤 먹을 때 탕과는 어디 뒀어?",
  ui_story_5075_50750402_83_dialog_content = "물론 과일가게 옆에... 아!",
  ui_story_5075_50750402_84_dialog_content = "진짜네! 우리 탕과야! 껍질 벗긴 귤 안에 있었어!",
  ui_story_5075_50750402_85_dialog_content = "......",
  ui_story_5075_50750402_86_dialog_content = "이걸로 진상이 밝혀졌네.",
  ui_story_5075_50750402_87_dialog_content = "너희, 뭐 할 말 없어?",
  ui_story_5075_50750402_88_dialog_content = "죄송합니다...",
  ui_story_5075_50750402_89_dialog_content = "다음에 또 이런 일이 있으면 먼저 자초지종을 잘 생각해 봐.",
  ui_story_5075_50750402_90_dialog_content = "뭐든 수요령 탓만 한다고 되는 게 아냐.",
  ui_story_5075_50750402_91_dialog_content = "수요령한테 폭죽을 쏜다고 없어진 탕과가 돌아와?",
  ui_story_5075_50750402_92_dialog_content = "미신과 편견은 잘 모르는 대상에게 악의를 품게 만들고, 자기 멋대로 적으로 만들어 버려...",
  ui_story_5075_50750402_93_dialog_content = "그렇게 화풀이나 해 봤자 아무 쓸모도 없다고.",
  ui_story_5075_50750402_94_dialog_content = "그런 건 정의가 아니라 비겁한 짓이야. 알겠어?",
  ui_story_5075_50750402_95_dialog_content = "네...",
  ui_story_5075_50750402_96_dialog_content = "알았으면 집에 가 봐. 부모님한테도 오늘 일 말해드리고.",
  ui_story_5075_50750402_97_dialog_content = "알겠어요...",
  ui_story_5075_50750402_98_dialog_content = "쟤네 진짜로 부모님한테 사실대로 말할까?",
  ui_story_5075_50750402_99_dialog_content = "아마 안 할걸.",
  ui_story_5075_50750402_100_dialog_content = "나도 알아. 이런 얘기를 늘어놔 봤자 근본적인 문제는 해결이 안 된다는 거.",
  ui_story_5075_50750402_101_dialog_content = "하지만 세 사람이 우기면 없는 호랑이도 만드는 법이야.\n「수요령은 재수가 없다」는 거짓말도 많이들 말하니까 사람들이 믿는 거지.",
  ui_story_5075_50750402_102_dialog_content = "어쨌든 내가 한 말은 사실이고, 계속 말하면 언젠가는 믿는 사람들이 있을 거야.",
  ui_story_5075_50750402_103_dialog_content = "사실은 끝내 사실이고, 거짓은 결국 거짓이니까.",
  ui_story_5075_50750402_104_dialog_content = "나송 넌 참 대단하구나.",
  ui_story_5075_50750402_105_dialog_content = "게다가 쟤들 탕과가 어디 있는지도 순식간에 맞혔잖아. 꼭 직접 현장을 본 것처럼 말이야.",
  ui_story_5075_50750402_106_dialog_content = "하하하, 그건...",
  ui_story_5075_50750402_107_dialog_content = "본 건 맞아. 근데 내가 본 게 아냐.",
  ui_story_5075_50750402_108_dialog_content = "참... 너 혹시 나랑 같이 요마 퇴치하는 친구 만나볼 생각 있어?",
  ui_story_5075_50750402_109_dialog_content = "크오오!",
  ui_story_5075_50750402_110_dialog_content = "아, 이 수요령이 네 친구야?",
  ui_story_5075_50750402_111_dialog_content = "얜 아정이라고 해.",
  ui_story_5075_50750402_112_dialog_content = "아까 애들이 탕과를 놔두고 간 걸 얘가 보고 알려줬어.",
  ui_story_5075_50750402_113_dialog_content = "처음엔 과자를 그대로 애들한테 갖다주고 사실을 알려주려고 했는데,\n어느 설탕 인형 장수가 날 말리더라고.",
  ui_story_5075_50750402_114_dialog_content = "지금 성안 사람들은 수요령을 안 좋게 보고 있으니까,\n아정을 데리고 가면 일이 커질지도 모른다고 말이야.",
  ui_story_5075_50750402_115_dialog_content = "그래서 아정한테 여기서 기다리라고 했던 거야.",
  ui_story_5075_50750402_116_dialog_content = "그리고 아까 그 추리도 그 설탕 인형 장수가 가르쳐 준 거거든.",
  ui_story_5075_50750402_117_dialog_content = "지금 생각해 보니까 확실히 일리가 있었네.",
  ui_story_5075_50750402_118_dialog_content = "고맙다고 인사하러 가야겠어. 겸사겸사 설탕 인형이라도 사서 숨어있는 아정 친구들한테 줘야지.",
  ui_story_5075_50750402_119_dialog_content = "왠지 아닐 것 같긴 하지만... 나송 네가 말하는 설탕 인형 장수가 혹시 저기 저 사람이야?",
  ui_story_5075_50750402_120_dialog_content = "아, 맞아!",
  ui_story_5075_50750402_121_dialog_content = "넌 잠깐 여기 있어. 난 아정이랑 애들한테 갔다 금방 올 테니까.",
  ui_story_5075_50750402_122_dialog_content = "......",
  ui_story_5075_50750402_123_dialog_content = "...설탕 인형 장수요?",
  ui_story_5075_50750402_124_dialog_content = "예, 바로 소생입니다~",
  ui_story_5075_50750500_1_dialog_content = "천간 씨 점쟁이 그만뒀어요?",
  ui_story_5075_50750500_2_dialog_content = "그럴 리가요. 그것보다 이 반짝반짝하고 투명한 사탕물 좀 보십시오.",
  ui_story_5075_50750500_3_dialog_content = "그리고 이 정교한 세공 솜씨도 말입니다.",
  ui_story_5075_50750500_4_dialog_content = "이건 제 조상 대대로 전해지는 기예이고, 저도 몇 년이나 수행해서 겨우 습득했지요.",
  ui_story_5075_50750500_5_dialog_content = "진짜배기 설탕 인형 장수입니다. 가짜라면 환불해 드립니다.",
  ui_story_5075_50750500_6_dialog_content = "참, 신풍호에서 헤어진 지도 벌써 시간이 꽤 됐군요.",
  ui_story_5075_50750500_7_dialog_content = "이렇게 만난 것도 인연인데, 소생이 설탕 인형을 하나 드리겠습니다.",
  ui_story_5075_50750500_8_dialog_content = "일부러 의심하는 건 아니지만...",
  ui_story_5075_50750500_9_dialog_content = "어째 천간 씨가 주는 선물은 받으면 안 될 것 같단 말이죠.",
  ui_story_5075_50750500_10_dialog_content = "허어, 이건 몰랐습니다...",
  ui_story_5075_50750500_11_dialog_content = "면식이 생긴 지 얼마 되지도 않았는데 벌써 소생을 그리도 잘 아시는군요.",
  ui_story_5075_50750500_12_dialog_content = "이미 간파된 이상 숨길 필요도 없겠군요. 이걸 받아 주시지요.",
  ui_story_5075_50750500_13_dialog_content = "이건... 몸에 차는 장신구죠? 여자애 것 같네요.",
  ui_story_5075_50750500_14_dialog_content = "당신이 오기 조금 전에 설탕 인형을 사 간 손님이 떨어트린 것입니다.",
  ui_story_5075_50750500_15_dialog_content = "다만 저는 장사가 너무 잘돼서 도저히 갖다 줄 시간이 없습니다.\n그래서 당신에게 부탁할 수밖에 없네요.",
  ui_story_5075_50750500_16_dialog_content = "하지만 저도 중요한 일이 있어요.",
  ui_story_5075_50750500_17_dialog_content = "걱정 마시지요. 소생이 점을 보니 두 분은 인연이 있더군요.",
  ui_story_5075_50750500_18_dialog_content = "당신은 당신 일만 하면 됩니다. 그리하면 도중에 자연히 만나게 될 것입니다.",
  ui_story_5075_50750500_19_dialog_content = "역시 점쟁이는 점쟁이네요.",
  ui_story_5075_50750500_20_dialog_content = "...어라? 잠깐만요. 이거... 저 용녀 사당에서도 똑같은 걸 주웠어요.",
  ui_story_5075_50750500_21_dialog_content = "게다가 누가 이걸 차고 있었던 것 같은데...",
  ui_story_5075_50750500_22_dialog_content = "설마...",
  ui_story_5075_50750500_23_dialog_content = "참, 천간 씨, <color=#FFB400>수요령</color>에 대해서도 좀 아세요?",
  ui_story_5075_50750500_24_dialog_content = "물론이지요. 전에 말씀드렸던 소생의 <color=#FFB400>「만류천두괘」</color>를 기억하시는지요?",
  ui_story_5075_50750500_25_dialog_content = "그 근원을 쫓아 올라가면 용주에서 가장 숭배받는 <color=#FFB400>13대수요령</color>과 관련이 있습니다.",
  ui_story_5075_50750500_26_dialog_content = "동물이 아니라요?",
  ui_story_5075_50750500_27_dialog_content = "동물, 수요령, 신령은... 그저 구현의 형태만 다를 뿐입니다.",
  ui_story_5075_50750500_28_dialog_content = "종서 대인께서도 말씀하지 않으셨습니까. 땅을 지킨 수요령이 신으로 받들어진 이야기 말입니다.",
  ui_story_5075_50750500_29_dialog_content = "그 대수요령 열셋은 용주에서 가장 특별한 13명의 신이기도 합니다.",
  ui_story_5075_50750500_30_dialog_content = "당신도 알고 있는 <color=#FFB400>「용녀진해」</color>의 그 <color=#FFB400>용녀</color>님도 그중 한 명이지요.",
  ui_story_5075_50750500_31_dialog_content = "다만 시대가 바뀌면서, 이제 사람들은 자신들이 모시던 신도\n수요령이었다는 것을 잊어버렸을 뿐입니다.",
  ui_story_5075_50750500_32_dialog_content = "이야기가 조금 딴길로 샜군요. 방금 전의 이야기로 돌아가도록 하지요.",
  ui_story_5075_50750500_33_dialog_content = "수요령은 다양한 법술을 쓸 수 있습니다만, 그 대수요령들, 바꿔 말하면 그 신령들은...",
  ui_story_5075_50750500_34_dialog_content = "다루는 법술이 무척이나 뛰어나 「신통력」이라고 불리지요.",
  ui_story_5075_50750500_35_dialog_content = "구름과 비를 조종하고, 안개나 바람을 일으키는 것뿐만 아니라,\n몸을 숨기거나 변신하는 것도 원하는 대로 할 수 있다고 합니다.",
  ui_story_5075_50750500_36_dialog_content = "참으로 부러운 일이지요.",
  ui_story_5075_50750500_37_dialog_content = "그럼 설마 그 여자애도... 어라? 잠깐만요, 제가 방금 수요령의 능력에 대해서 물어봤나요?",
  ui_story_5075_50750500_38_dialog_content = "그렇습니다~",
  ui_story_5075_50750500_39_dialog_content = "음... 그 신통력도 아마 강력한 루미나틱스의 일종인 거겠죠.\n과연 제가 그런 힘도 감응할 수 있을지 모르겠네요.",
  ui_story_5075_50750500_40_dialog_content = "그것은 당신이 직접 <color=#FFB400>신</color>에게 물어보는 수밖에 없습니다.",
  ui_story_5075_50750500_41_dialog_content = "뭐, 대신 신통력이라고까진 못 해도... 소생이 가르쳐 드릴 수 있는 주문이 하나 있긴 합니다.",
  ui_story_5075_50750500_42_dialog_content = "용주의 고대부터 전해지는 것이고, 바로 지금 이 시기에 딱 도움이 되는 주문이지요.",
  ui_story_5075_50750500_43_dialog_content = "자, 따라 해 보십시오.",
  ui_story_5075_50750500_44_dialog_content = "<color=#FFB400>새──해──잖──아──</color>",
  ui_story_5075_50750500_45_dialog_content = "새──해──잖──아──",
  ui_story_5075_50750500_46_dialog_content = "예, 바로 그것입니다. 이 며칠간 분명히 도움이 될 겁니다.",
  ui_story_5075_50750500_47_dialog_content = "무슨 일이 벌어지든 그 주문만 외우면 아무리 큰 싸움도 즉시 원만하게 해결할 수 있지요.",
  ui_story_5075_50750500_48_dialog_content = "이런 간단한 한마디가 그렇게 대단하다고요?",
  ui_story_5075_50750500_49_dialog_content = "고대 주문의 위력을 얕봐서는 안 됩니다.",
  ui_story_5075_50750500_50_dialog_content = "사실 이 주문은 총 네 개입니다만, 나머지 세 개는 지금의 당신이라면\n아직 그 깊은 의미를 깨닫기 힘들 것입니다.",
  ui_story_5075_50750500_51_dialog_content = "나중에 기회가 되면 그때 천천히 알려 드리도록 하지요.",
  ui_story_5075_50750500_52_dialog_content = "알겠어요! 고마워요!",
  ui_story_5075_50750500_53_dialog_content = "천만에요. 별일도 아니지 않습니까.",
  ui_story_5075_50750500_54_dialog_content = "당신의 다른 고민에 대해서는 소생도 점을 쳐 드리고 싶습니다만...",
  ui_story_5075_50750500_55_dialog_content = "많이 기다렸지? PlayerName, 다녀왔어.",
  ui_story_5075_50750500_56_dialog_content = "...시간이 없어서 말이지요.",
  ui_story_5075_50750500_57_dialog_content = "안 치겠다고요?",
  ui_story_5075_50750500_58_dialog_content = "무슨 얘기 하고 있어?",
  ui_story_5075_50750500_59_dialog_content = "아참! 나송 너도 도사라고 했잖아? 그럼 너도 점 칠 줄 알아?",
  ui_story_5075_50750500_60_dialog_content = "뭐야? PlayerName, 너 어디 가서 이상한 말에 속지 마.",
  ui_story_5075_50750500_61_dialog_content = "운명이니, 인연이니, 인과니, 그런 그럴싸해 보이는 얘기는 들을 필요 없어.",
  ui_story_5075_50750500_62_dialog_content = "실제로는 교묘한 화술에 잔재주를 좀 더한 것뿐이니까.",
  ui_story_5075_50750500_63_dialog_content = "아?",
  ui_story_5075_50750500_64_dialog_content = "그저 양심에 떳떳하기만 한다면, 뭘 해도 결과는 따라오게 돼 있어.",
  ui_story_5075_50750500_65_dialog_content = "아무리 교묘한 점괘라도 자기 실력보다 더 확실한 건 없으니까.",
  ui_story_5075_50750500_66_dialog_content = "<size=28>천간 씨...</size>",
  ui_story_5075_50750500_67_dialog_content = "<size=28>쳐다보지 마십시오. 전 그냥 설탕 인형 장수일 뿐입니다.</size>",
  ui_story_5075_50750500_68_dialog_content = "멍청한 도사.",
  ui_story_5075_50750500_69_dialog_content = "머리가 단단해.",
  ui_story_5075_50750500_70_dialog_content = "아무것도 몰라.",
  ui_story_5075_50750500_71_dialog_content = "귀찮아 귀찮아.",
  ui_story_5075_50750500_72_dialog_content = "둘이서 무슨 영문 모를 소릴 하는 겁니까? 하나도 모르겠습니다, 하하하.",
  ui_story_5075_50750500_73_dialog_content = "......",
  ui_story_5075_50750500_74_dialog_content = "자, 설탕 인형 나왔습니다.",
  ui_story_5075_50750500_75_dialog_content = "고마워요... 어라? 이건 매화꽃 아닌가요?! 인형은 어디 갔어요?",
  ui_story_5075_50750500_76_dialog_content = "미안하게 됐습니다. 설탕이 다 떨어져서 말이지요.",
  ui_story_5075_50750500_77_dialog_content = "하지만 조급해하실 필요 없습니다. 그런 시도 있지 않습니까.",
  ui_story_5075_50750500_78_dialog_content = "「미인이여, 미인이여, 저녁 비인지 아침 구름인지 알 수가 없구나.\n서로를 그리던 밤 매화가 피매, 홀연히 창가 앞에 이른 이 임인가 싶구나.」",
  ui_story_5075_50750500_79_dialog_content = "이 <color=#FFB400>매화꽃</color>을 어찌 <color=#FFB400>미인</color>이라 할 수 없겠습니까?",
  ui_story_5075_50750500_80_dialog_content = "아무리 봐도 억지잖아요.",
  ui_story_5075_50750500_81_dialog_content = "인간은 때로는 풍류도 필요한 법입니다.",
  ui_story_5075_50750500_82_dialog_content = "자, 아무튼 급한 일 보러 가십시오. 배웅은 안 나가겠습니다.",
  ui_story_5075_50750500_83_dialog_content = "기억하십시오. 일을 하다가 도저히 모르겠으면 <color=#FFB400>신을 향해 절해 보십시오</color>.",
  ui_story_5075_50750500_84_dialog_content = "사당 장터 무대에서 「용녀진해무」가 펼쳐질 예정이라고 들었습니다.",
  ui_story_5075_50750500_85_dialog_content = "무대 위의 신은 진짜 신도 아니잖아요.",
  ui_story_5075_50750500_86_dialog_content = "...어라? 저건... 검은 기운?!",
  ui_story_5075_50750500_87_dialog_content = "보러 가 봐야겠어요!",
  ui_story_5075_50750500_88_dialog_content = "PlayerName! 기다려! 나도 같이 가!",
  ui_story_5075_50750500_89_dialog_content = "(곤란한 녀석이 사라졌으니, 그럼 앞으로의 일을 점쳐 볼까요.)",
  ui_story_5075_50750500_90_dialog_content = "(이런.)",
  ui_story_5075_50750500_91_dialog_content = "(아무래도 무대 위의 신이 진짜 신이 아니라곤 단정할 순 없겠군요.)",
  ui_story_5075_50750601_1_dialog_content = "찍찍!",
  ui_story_5075_50750601_2_dialog_content = "조용히 해. 이러다 들킬 거야.",
  ui_story_5075_50750601_3_dialog_content = "어라, 깼구나?",
  ui_story_5075_50750601_4_dialog_content = "사당 장터에 가까이 갈수록 더 심하게 날뛰는 것 같아...",
  ui_story_5075_50750601_5_dialog_content = "아마 네가 말하는 검은 기운과 가까워져서 그런 거겠지.",
  ui_story_5075_50750601_6_dialog_content = "아무래도 그 검은 기운은 침식의 성질이 있는 것 같아.",
  ui_story_5075_50750601_7_dialog_content = "마치 독처럼 수요령이 이성을 잃게 만드는 거지.",
  ui_story_5075_50750601_8_dialog_content = "하지만 안타깝게도 난 그걸 쫓아낼 방법이 없어.",
  ui_story_5075_50750601_9_dialog_content = "밖에서 만난 비슷한 증상의 수요령들도 회복시킬 수 없었고,\n그저 사람들이 없는 곳에 숨겨줄 수밖에 없었어.",
  ui_story_5075_50750601_10_dialog_content = "이 수요령도 마찬가지고...",
  ui_story_5075_50750601_11_dialog_content = "너 검은 기운을 없애는 힘을 가진 여자애를 봤다고 했지? 찾아낼 수 있을까?",
  ui_story_5075_50750601_12_dialog_content = "사실 오늘 처음 알게 된 애야. 이름이 진예라는 것밖에 몰라.",
  ui_story_5075_50750601_13_dialog_content = "근데 왠지 엄청난 힘을 가진 수요령 같았어.",
  ui_story_5075_50750601_14_dialog_content = "그 외의 단서라면 그 애가 떨어트린 장신구밖에 없어.",
  ui_story_5075_50750601_15_dialog_content = "엄청 비쌀 것 같은 걸 두 개나 떨어트렸거든...",
  ui_story_5075_50750601_16_dialog_content = "혹시 금팔찌나 발찌 같은 거지?",
  ui_story_5075_50750601_17_dialog_content = "어떻게 알았어?",
  ui_story_5075_50750601_18_dialog_content = "나도 봤거든.",
  ui_story_5075_50750601_19_dialog_content = "자네도 받았나? 나도 아까 어린애가 와서 샤오룽바오를 하나 사 갔거든.",
  ui_story_5075_50750601_20_dialog_content = "근데 그거 하나 사는데 이런 걸 주고 갔지 뭐야.",
  ui_story_5075_50750601_21_dialog_content = "이거 금 맞지? 못 받겠다고 하려던 순간 애가 사라지고 없더라고.",
  ui_story_5075_50750601_22_dialog_content = "우리도 그랬네. 난 아예 모습도 못 봤다니까.",
  ui_story_5075_50750601_23_dialog_content = "고구마꿀절임 한 그릇이 없어진 자리에 이 금덩이가 있었지.",
  ui_story_5075_50750601_24_dialog_content = "설마 재물운의 신인 건 아니겠지?",
  ui_story_5075_50750601_25_dialog_content = "음... 내 생각엔 아마 재물운의 신은 아닐 거야.",
  ui_story_5075_50750601_26_dialog_content = "중요한 건 그게 아니잖아?!",
  ui_story_5075_50750601_27_dialog_content = "금덩이로 연근탕수 사간 애 말이지? 봤어. 안쪽으로 갔을 거야.",
  ui_story_5075_50750601_28_dialog_content = "세화 좀 보고 가실라우? 아주 정성껏 그린 거라고.",
  ui_story_5075_50750601_29_dialog_content = "금덩이를 내는 애? 아, 당연히 기억하지.",
  ui_story_5075_50750601_30_dialog_content = "내 세화를 무척 좋아하더라고. 특히 용녀진해무를 그린 세화는 몇 장이나 사 갔다니까.",
  ui_story_5075_50750601_31_dialog_content = "마침 그 애가 그림을 다 샀을 때 무대 쪽에서 뭐라고 소리를 쳤던 것 같아.",
  ui_story_5075_50750601_32_dialog_content = "아마 무대를 보러 갔을 거야.",
  ui_story_5075_50750601_33_dialog_content = "아까 헤어질 때 자긴 볼일이 있다고 했었는데, 이제 보니 사당 장터 구경이었구나.",
  ui_story_5075_50750601_34_dialog_content = "게다가 아주 착실하게 즐겼네.",
  ui_story_5075_50750601_35_dialog_content = "가게 음식들이 하나같이 맛있잖아!",
  ui_story_5075_50750601_36_dialog_content = "이 동미당이란 과자는 아스트라 쪽 간식처럼 달진 않은데, 이상하게 계속 손이 간단 말이야.",
  ui_story_5075_50750601_37_dialog_content = "그렇지, 그리고 연근탕수도 달고 새콤한 게 아주 일품이라니까!",
  ui_story_5075_50750601_38_dialog_content = "아정, 너도 좋아하지?",
  ui_story_5075_50750601_39_dialog_content = "캬오~",
  ui_story_5075_50750601_40_dialog_content = "그나저나... 우리 여기 뭐 하러 왔더라?",
  ui_story_5075_50750601_41_dialog_content = "......",
  ui_story_5075_50750601_42_dialog_content = "......",
  ui_story_5075_50750601_43_dialog_content = "사, 사당 장터... 역시 사람을 홀리는 곳이네.",
  ui_story_5075_50750601_44_dialog_content = "그러게, 하하...",
  ui_story_5075_50750601_45_dialog_content = "근데 못 느꼈어?",
  ui_story_5075_50750601_46_dialog_content = "우리가 데리고 있는 그 수요령, 아까부터 발버둥 치지도 않고, 한결 차분해졌잖아.",
  ui_story_5075_50750601_47_dialog_content = "감응해 볼게...",
  ui_story_5075_50750601_48_dialog_content = "...주위에 있던 검은 기운도 없어졌어! 소멸한 건가?",
  ui_story_5075_50750601_49_dialog_content = "하지만 어쩌면 더 나쁜 상황일 가능성도 있어.",
  ui_story_5075_50750601_50_dialog_content = "예를 들면 그 기운이 다른 어디에서 전부 모이고 있다든지 말이야.\n어쨌든 얼른 네가 말한 그 사람을 찾는 게 좋겠어.",
  ui_story_5075_50750601_51_dialog_content = "앗! PlayerName!",
  ui_story_5075_50750601_52_dialog_content = "아, 겨우 찾았네! 다행이다...",
  ui_story_5075_50750601_53_dialog_content = "다행이로구나, 친구도 데리고 온 게냐!",
  ui_story_5075_50750601_54_dialog_content = "마침 잘 왔느니라! 어서 무대에 오르거라!",
  ui_story_5075_50750601_55_dialog_content = "어, 어딜 올라?",
  ui_story_5075_50750601_56_dialog_content = "너... 아니, 다, 당신은... 참! 여기 이 수요령을 좀...",
  ui_story_5075_50750601_57_dialog_content = "어째 또 있는 게냐.",
  ui_story_5075_50750601_58_dialog_content = "<color=#e8d9bb>전과 마찬가지로 진예는 대수롭지 않다는 듯이 손을 휘저었다.</color>",
  ui_story_5075_50750601_59_dialog_content = "<color=#e8d9bb>수요령의 몸속에서는 검은 기운이 빠져나왔고,\n이내 찌그러져 애초에 존재하지 않았던 것처럼 사라져 버렸다.</color>",
  ui_story_5075_50750601_60_dialog_content = "찍찍찍!",
  ui_story_5075_50750601_61_dialog_content = "<color=#e8d9bb>수요령은 진예의 발밑으로 경쾌하게 달려갔고, 감사하다는 듯이 고개를 숙였다.</color>",
  ui_story_5075_50750601_62_dialog_content = "역시 당신은...!",
  ui_story_5075_50750601_63_dialog_content = "우리 차례니라, 서두르거라!",
  ui_story_5075_50750601_64_dialog_content = "사람들이 엄청 많네!",
  ui_story_5075_50750601_65_dialog_content = "영문도 모르고 올라와 버렸잖아... 이제 뭘 하려는 건데?",
  ui_story_5075_50750601_66_dialog_content = "그거야 물론 <color=#FFB400>용녀진해무</color>를 춰야지.",
  ui_story_5075_50750601_67_dialog_content = "여러분, 안녕하십니까! 오늘 다들 이렇게 모여주신 것은 유명 예인의 공연을 보기 위해서겠지요.",
  ui_story_5075_50750601_68_dialog_content = "허나 들으셨겠지만, 용녀의 춤을 가장 잘 추는 예인은 이번에 다리를 다쳐\n무대에 오를 수 없게 되었습니다.",
  ui_story_5075_50750601_69_dialog_content = "그렇다고 사당 장날 동안 무대를 비워 둘 수도 없는 노릇 아니겠습니까?\n하여 저희가 새로운 행사를 준비해 보았습니다.",
  ui_story_5075_50750601_70_dialog_content = "이제 여러 명의 용녀들이 차례로 무대에 올라 여러분께\n저마다의 「용녀진해무」를 선보일 것입니다.",
  ui_story_5075_50750601_71_dialog_content = "그것을 보시고 여러분께서 올해 춘삭절 최고의 용녀를 선택해 주시는 것이 어떻겠습니까?",
  ui_story_5075_50750601_72_dialog_content = "좋습니다!",
  ui_story_5075_50750601_73_dialog_content = "PlayerName 그대가 친구를 데려와서 다행이니라.\n아니었으면 머릿수가 부족할 뻔했지 무에냐.",
  ui_story_5075_50750601_74_dialog_content = "그대의 친구에게는 바다를 휩쓸고 사람을 해치는 흑룡을 연기해 달라 하거라.",
  ui_story_5075_50750601_75_dialog_content = "나는 용녀니라.",
  ui_story_5075_50750601_76_dialog_content = "그럼 난?",
  ui_story_5075_50750601_77_dialog_content = "PlayerName 그대는 제일 중요한 역할이니라. 만반의 준비를 하는 게 좋을 것이야.",
  ui_story_5075_50750601_78_dialog_content = "<size=50>그대는 대해이니라!</size>",
  ui_story_5075_50750601_79_dialog_content = "그게 필요한 배역이야?!",
  ui_story_5075_50750601_80_dialog_content = "무슨 소리를 하는 게냐? 대해가 얼마나 중요한지 모른단 말이더냐.",
  ui_story_5075_50750601_81_dialog_content = "음악이 시작됐구나, 어서 춤을 추거라.",
  ui_story_5075_50750601_82_dialog_content = "아아── 아──♪",
  ui_story_5075_50750601_83_dialog_content = "「용의 소녀 천명을 받아, 조의 대지에 강림했네.」",
  ui_story_5075_50750601_84_dialog_content = "「만 리의 바다는 넓디넓고, 연파는 한없이 자욱하구나.」",
  ui_story_5075_50750601_85_dialog_content = "(대해야, 어서 그대의 광대함과 안개가 자욱한 수면을 보여주어라!)",
  ui_story_5075_50750601_86_dialog_content = "(...눈빛으로 보채도 소용없다고! 아...아무튼 어떻게든 파도가 치는 걸 표현해 보자...)",
  ui_story_5075_50750601_87_dialog_content = "「하늘이 용녀를 도우사...」",
  ui_story_5075_50750601_88_dialog_content = "......",
  ui_story_5075_50750601_89_dialog_content = "(어...? 설마, 대사를 잊어버린 거야?!)",
  ui_story_5075_50750601_90_dialog_content = "<size=28>「만복이 끊이지 않으리니」!</size>",
  ui_story_5075_50750601_91_dialog_content = "(이런, 반주도 벌써 지나갔어... 그다음 가사도 기억 못 할 거 아냐...)",
  ui_story_5075_50750601_92_dialog_content = "「재앙의 교룡이 세상에 내려와, 해와 달이 빛을 잃으매.」",
  ui_story_5075_50750601_93_dialog_content = "(나송?!)",
  ui_story_5075_50750601_94_dialog_content = "「거대한 뇌성이 울리고, 번개가 요란히 몰아치네.」",
  ui_story_5075_50750601_95_dialog_content = "(동작이 딱딱하고 가사도 전혀 다르지만... 어떻게든 이어받았어! 다행이야!)",
  ui_story_5075_50750601_96_dialog_content = "(...왜 너까지 멈추는 건데?!)",
  ui_story_5075_50750601_97_dialog_content = "(자, 와라! 뇌성과 번개!)",
  ui_story_5075_50750601_98_dialog_content = "(내 차례라는 거야?!)",
  ui_story_5075_50750601_99_dialog_content = "(어, 어떻게든 흉내를 내 보자...)",
  ui_story_5075_50750601_100_dialog_content = "우르릉 쾅쾅──!",
  ui_story_5075_50750601_101_dialog_content = "「요마가 천지에 횡행하나, 창생에 그 무슨 죄 있으랴!」",
  ui_story_5075_50750601_102_dialog_content = "「천행으로 용녀가 있어, 백성을 위해 해를 없애니.」",
  ui_story_5075_50750601_103_dialog_content = "「그 품은 힘 강하고, 그 세운 뜻 굳건하도다.」",
  ui_story_5075_50750601_104_dialog_content = "「오직 그 주먹으로, 천하를 개벽하리!」",
  ui_story_5075_50750601_105_dialog_content = "(어느 용녀가 주먹으로 그런 짓을 하냐고오!)",
  ui_story_5075_50750601_106_dialog_content = "(게다가 넌 악룡이잖아! 벌써 배역이 엉망으로 섞였다고!)",
  ui_story_5075_50750601_107_dialog_content = "크오오!",
  ui_story_5075_50750601_108_dialog_content = "(이 재앙 같은 공연 와중에 왜 하필 암귀만 현실감이 넘치는 건데...)",
  ui_story_5075_50750601_109_dialog_content = "(아니지!)",
  ui_story_5075_50750601_110_dialog_content = "진짜 암귀잖아!",
  ui_story_5075_50750602_1_dialog_content = "정말 감사합니다...",
  ui_story_5075_50750602_2_dialog_content = "아주 개성적이고... 독특한... 용녀진해무였습니다.",
  ui_story_5075_50750602_3_dialog_content = "단장님 안색이 엄청 안 좋네... 우리 공연이 그렇게 충격이었나?",
  ui_story_5075_50750602_4_dialog_content = "아니, 요마 때문에 무대 절반이 부서진 충격이 더 크겠지.",
  ui_story_5075_50750602_5_dialog_content = "용주에서는 저놈들이 성안에 나타나는 일은 거의 없다고 했던 것 같은데...",
  ui_story_5075_50750602_6_dialog_content = "광폭해진 수요령, 성안에 나타난 암귀, 그리고 기묘한 검은 기운...",
  ui_story_5075_50750602_7_dialog_content = "호진성에서 대체 무슨 일이 벌어지고 있는 거야?",
  ui_story_5075_50750602_8_dialog_content = "둘이서 뭘 그리 수심에 차 있는 것이냐?",
  ui_story_5075_50750602_9_dialog_content = "그대들의 연기는 아주 좋았다. 게다가 요마도 퇴치하지 않았느냐.",
  ui_story_5075_50750602_10_dialog_content = "특히 PlayerName 네 연기는 참으로 마음에 드는지고!",
  ui_story_5075_50750602_11_dialog_content = "그걸 진짜 연기라고 할 수 있는 건가...",
  ui_story_5075_50750602_12_dialog_content = "게다가 중간부터 진해의 용녀랑은 전혀 상관없는 얘기가 돼버렸잖아.",
  ui_story_5075_50750602_13_dialog_content = "근데 내가 전에 들은 얘기는 그랬거든.",
  ui_story_5075_50750602_14_dialog_content = "800년 전, 검은 교룡이 나타나 악행을 일삼아서 백성들의 고통이 극심했어.",
  ui_story_5075_50750602_15_dialog_content = "그때 다행히 용녀가 강림했고, 바다에 서서 악룡을 향해 주먹을 치켜들었어.",
  ui_story_5075_50750602_16_dialog_content = "그 주먹은 천균의 힘이 있어서 악룡은 놀랄 틈도 없이 권압에 십여 리나 날아가 버렸대.",
  ui_story_5075_50750602_17_dialog_content = "그리고 용녀는 반응할 틈도 안 주고 날아가서 주먹 수십 방을 휘둘렀고,\n악룡을 묵사발로 만들었다는 거야!",
  ui_story_5075_50750602_18_dialog_content = "호오, 그 다음은 어찌 되었느냐?",
  ui_story_5075_50750602_19_dialog_content = "악룡은 머리가 핑 돌더니 분노에 가득 차서...",
  ui_story_5075_50750602_20_dialog_content = "아니지, 그때 상황은 저보다 더 잘 아시지 않으십니까? 당신은...",
  ui_story_5075_50750602_21_dialog_content = "선녀용왕 본인이시니 말입니다. 아니십니까?",
  ui_story_5075_50750602_22_dialog_content = "잠깐만... 천간 씨가 의미심장한 얘길 하긴 했지만...\n진예가 신이라니, 난 아직 마음의 준비가 안 됐다고...",
  ui_story_5075_50750602_23_dialog_content = "이 진예가... 진짜 그 용녀님이야?!",
  ui_story_5075_50750602_24_dialog_content = "확실히 이 몸을 그렇게들 부르고 있지.",
  ui_story_5075_50750602_25_dialog_content = "도사 나송, 선녀용왕님을 뵙습니다!",
  ui_story_5075_50750602_26_dialog_content = "곧바로 절하는 거야?!",
  ui_story_5075_50750602_27_dialog_content = "말 그대로 진짜 신령님인데, 당연히 절을 해야지.",
  ui_story_5075_50750602_28_dialog_content = "용왕님, 호진에는 무슨 일로 강림하셨습니까?",
  ui_story_5075_50750602_29_dialog_content = "진해의 봉인을 깨트려 이 몸의 잠을 방해한 자가 있기에 문제를 따지러 온 것이다.",
  ui_story_5075_50750602_30_dialog_content = "그, 그럼 엄청 큰일 아닌가요?!",
  ui_story_5075_50750602_31_dialog_content = "최근에 요마가 날뛰고, 수요령도 소란을 피운 게 전부 악룡의 봉인이 깨졌기 때문이었습니까?!",
  ui_story_5075_50750602_32_dialog_content = "검은 교룡도 진짜 있던 거였구나.",
  ui_story_5075_50750602_33_dialog_content = "맞아, 진해의 용녀 전설은 여러 판본이 있긴 하지만, 모두 실제 역사가 기본 바탕이야.",
  ui_story_5075_50750602_34_dialog_content = "그러니까 주된 내용은 큰 차이가 없다는 거지.",
  ui_story_5075_50750602_35_dialog_content = "악룡이 나타나는 데서 시작해서, 용녀님이 직접 녀석을 해저에 봉인해서\n백성들의 안녕을 되찾아 주는 걸로 끝나.",
  ui_story_5075_50750602_36_dialog_content = "근데 그 「진해의 진예」 얘기도 벌써 800년 일이라며?",
  ui_story_5075_50750602_37_dialog_content = "몇백 년이 지났는데 그 검은 교룡이 아직도 살아 있어?",
  ui_story_5075_50750602_38_dialog_content = "악룡의 몸은 이미 오래전에 소멸했다. 걱정할 것 없느니라.",
  ui_story_5075_50750602_39_dialog_content = "허나 당시의 일은 본디 내 동족이 저지른 죄가 아니었다.",
  ui_story_5075_50750602_40_dialog_content = "바다 속 한 깊은 동굴에는 한때 대요마의 유해가 묻혀 있었고,\n그 유해에는 깊은 원한이 깃들어 있었느니라.",
  ui_story_5075_50750602_41_dialog_content = "내 동족이 실수로 그 안에 들어가 원념에 사로잡힌 끝에 재앙을 일으키고 말았던 게지.",
  ui_story_5075_50750602_42_dialog_content = "지금은 봉인이 깨져버렸으나, 이 몸의 힘은 여전히 남아 있다.\n원념이 풀려났다 해도 그릇이 될 몸이 없다면, 천하에 재앙을 일으킬 힘은 없을 것이야.",
  ui_story_5075_50750602_43_dialog_content = "만약 그가 새 몸을 구한다 해도, 우선은 그 몸과 완전히 하나가 되지 않으면\n운신이 자유롭지 못할 터.",
  ui_story_5075_50750602_44_dialog_content = "(그럼 전에 감응했을 때 갑자기 지나갔던 게 그 대요마인가?)",
  ui_story_5075_50750602_45_dialog_content = "(느낌이 안 좋아... 자세히 볼 수 있었으면 좋았을 텐데.\n그래도 진예 말대로라면 아직 시간이 있겠어.)",
  ui_story_5075_50750602_46_dialog_content = "어쨌든 진예랑 우린 목적이 같은 모양이네.",
  ui_story_5075_50750602_47_dialog_content = "그럼 일단은 동료니까, 질문 좀 해도 될까?",
  ui_story_5075_50750602_48_dialog_content = "고하거라.",
  ui_story_5075_50750602_49_dialog_content = "우리가 처음 만난 건 용녀 사당이었지?",
  ui_story_5075_50750602_50_dialog_content = "근데 넌 용녀님 본인이잖아. 그럼... 그때 왜 자기 공물을 훔쳤어?",
  ui_story_5075_50750602_51_dialog_content = "...그건 훔친 게 아니니라.",
  ui_story_5075_50750602_52_dialog_content = "내게 바친 것을 가져가는 게 어찌 훔친 게 된단 말이냐.",
  ui_story_5075_50750602_53_dialog_content = "아하하, 그것도 그렇네. 내가 잘못 말했어. 훔친 게 아니라 받은 거지.",
  ui_story_5075_50750602_54_dialog_content = "이렇게 말하고 나니까 진예가 신이라곤 해도 이젠 좀 익숙해진 것 같아.",
  ui_story_5075_50750602_55_dialog_content = "참, 그리고 이 금 장신구들도 네 거지?",
  ui_story_5075_50750602_56_dialog_content = "하나는 용녀 사당에서 주운 거고, 다른 하나는 이천간...\n아니, 설탕 인형 장수가 주운 거야. 돌려줄게.",
  ui_story_5075_50750602_57_dialog_content = "그렇다면 하나만 받으마.",
  ui_story_5075_50750602_58_dialog_content = "남은 하나는 PlayerName 그대가 내 사당에서 주운 것이 아니더냐.\n그대가 주웠으니 그대의 것이니라.",
  ui_story_5075_50750602_59_dialog_content = "훗날 소원이 생기거든 그것을 가지고 이 몸에게 빌면 된다.",
  ui_story_5075_50750602_60_dialog_content = "소원이라...",
  ui_story_5075_50750602_61_dialog_content = "저기, 실례합니다.",
  ui_story_5075_50750602_62_dialog_content = "단장님? 어... 아깐 정말 죄송했어요.",
  ui_story_5075_50750602_63_dialog_content = "무슨 말씀이십니까. 오히려 여러분 덕분에 무대 외에는 다른 손실이 없었습니다.",
  ui_story_5075_50750602_64_dialog_content = "대회가 취소된 탓에 드릴 상품은 없게 되었습니다만, 대신 이걸 받아 주셨으면 합니다.",
  ui_story_5075_50750602_65_dialog_content = "저희 집에서 만든 간식입니다. 밖에서 파는 것처럼 정교하진 않습니다만...",
  ui_story_5075_50750602_66_dialog_content = "그래도 조상 대대로 내려오는 비법으로 만든 것이니, 다른 곳에서는 맛보실 수 없습니다.\n색다른 경험인 셈 치고 드셔 주시지요.",
  ui_story_5075_50750602_67_dialog_content = "바로 이것이야!",
  ui_story_5075_50750602_68_dialog_content = "이 몸은 바로 이 향기에 이끌려 대회에 나간 것이니라. 허나 이게 상품이 아니었을 줄이야.",
  ui_story_5075_50750602_69_dialog_content = "간식 때문에 나갔다고?!",
  ui_story_5075_50750602_70_dialog_content = "냠.",
  ui_story_5075_50750602_71_dialog_content = "으음! 바로 이 맛이다! 그대가 만든 간식은 그대의 할아버지가 만든 것과 맛이 똑같구나!",
  ui_story_5075_50750602_72_dialog_content = "헤헷, 이것으로 이번 장날도 만끽하였느니라.",
  ui_story_5075_50750602_73_dialog_content = "가자꾸나.",
  ui_story_5075_50750602_74_dialog_content = "(할아버지가 만든 것과 똑같다고...? 하지만 할아버지는 오래전에 돌아가셨고,\n그 뒤로 집에서 이 간식을 판 적도 없었는데...)",
  ui_story_5075_50750602_75_dialog_content = "(설마...!)",
  ui_story_5075_50750602_76_dialog_content = "PlayerName, 나송, 아정, 그대들도 먹어 보거라~",
  ui_story_5075_50750602_77_dialog_content = "이 간식은 아주 맛있느니라. 다만 유감스럽게도 저자의 일족만 만들 수 있지.",
  ui_story_5075_50750602_78_dialog_content = "캬오~",
  ui_story_5075_50750602_79_dialog_content = "감사합니다, 선녀용왕님!",
  ui_story_5075_50750602_80_dialog_content = "나송도 이 몸과 같이 놀아준 친구가 아니더냐, 진예라고 부르거라.",
  ui_story_5075_50750602_81_dialog_content = "예, 분부대로 하겠습니다!",
  ui_story_5075_50750602_82_dialog_content = "PlayerName, 그대는 왜 먹지 않는 것이냐?",
  ui_story_5075_50750602_83_dialog_content = "...이걸로 괜찮은 거야?",
  ui_story_5075_50750602_84_dialog_content = "무슨 뜻이냐.",
  ui_story_5075_50750602_85_dialog_content = "저 사람, 진예가 전에 알던 사람의 후손인 거지?",
  ui_story_5075_50750602_86_dialog_content = "가서 뭔가 더 이야기 안 해도 돼?",
  ui_story_5075_50750602_87_dialog_content = "으음...",
  ui_story_5075_50750602_88_dialog_content = "이 몸은 용이요, 대수요령이니라. 백성들에게 바다의 신으로 추앙받고,\n범인들과 달리 오래도록 살아왔지.",
  ui_story_5075_50750602_89_dialog_content = "하여 수많은 사람을 만나고, 알아 올 수 있었다.",
  ui_story_5075_50750602_90_dialog_content = "저 단장은 전에 이 몸에게 자주 간식을 주었던 자의 손자다.",
  ui_story_5075_50750602_91_dialog_content = "동쪽 거리에는 전에 나와 함께 뱃놀이를 했던 자의 손녀가 지금 혼례를 치르고 있다.",
  ui_story_5075_50750602_92_dialog_content = "남쪽 강 건너 골목에는 늘 귀뚜라미싸움에서 이 몸을 이겼던 자의 작은조카가\n명을 다하여 장례를 치르는 중이지.",
  ui_story_5075_50750602_93_dialog_content = "...저 아이는 그자의 마지막 혈연이었느니라.",
  ui_story_5075_50750602_94_dialog_content = "모두가 이토록 짧은 삶을 살아간다. 그러니 무엇을 하든 서두르고 있지.",
  ui_story_5075_50750602_95_dialog_content = "게다가 구태여 여러 의식으로 자신을 증명하려 든다.",
  ui_story_5075_50750602_96_dialog_content = "만약 이 몸이 전에 누군가를 알았다는 이유로, 그의 후손도 알아야 한다면...",
  ui_story_5075_50750602_97_dialog_content = "이 몸은 아마 매일 수많은 의식에 참여하느라 분주했을 것이야.",
  ui_story_5075_50750602_98_dialog_content = "그럼 넌 외롭지 않아?",
  ui_story_5075_50750602_99_dialog_content = "넌 오래 사니까, 늘 친구의 마지막을 배웅해 왔을 거잖아.",
  ui_story_5075_50750602_100_dialog_content = "외롭지 않느니라. 이 또한 나쁘지 않으니 말이다.",
  ui_story_5075_50750602_101_dialog_content = "PlayerName 그대도 자신이 행운아라 여겨야 마땅할 게야.",
  ui_story_5075_50750602_102_dialog_content = "오래도록 살아가는 이 몸을 알게 되어, 이 몸이 그대를 기억해 주게 되지 않았더냐.",
  ui_story_5075_50750602_103_dialog_content = "설령 그대에게 무슨 일이 있더라도, 이 몸의 마음속에는 여전히 그대가 있고,\n이 몸과 함께 오래도록 살아갈 것이니라.",
  ui_story_5075_50750602_104_dialog_content = "(진예가 하는 말 자체는 이해할 수 있다. 하지만 내가 진짜로 이해한 건지는 모르겠다.)",
  ui_story_5075_50750602_105_dialog_content = "(구름 한 점 없는 듯한 지금 저 미소도, 저 말들을 할 때 그녀의 기분도 전혀 알 수가 없다.)",
  ui_story_5075_50750602_106_dialog_content = "(그리고 이 순간, 정말로 깨달을 수 있었다... 우리는 전혀 다르다는 것을.)",
  ui_story_5075_50750701_1_dialog_content = "우리. 는. 달라.",
  ui_story_5075_50750701_2_dialog_content = "그. 래. 서.",
  ui_story_5075_50750701_3_dialog_content = "어울릴. 수. 없어.",
  ui_story_5075_50750701_4_dialog_content = "크윽...",
  ui_story_5075_50750701_5_dialog_content = "왜 그래? 괜찮아? 좀 쉴래?",
  ui_story_5075_50750701_6_dialog_content = "너 오는 동안 계속 그 검은 기운을 감응하고 있었잖아. 몸에 무리가 가는 거 아냐?",
  ui_story_5075_50750701_7_dialog_content = "괜찮아. 나도 그렇게까지 약하진 않으니까.",
  ui_story_5075_50750701_8_dialog_content = "게다가 계속 감응할수록 확실해지고 있어. 이 검은 기운의 본질은 암귀의 힘과 다를 게 없어.",
  ui_story_5075_50750701_9_dialog_content = "다만 감염력과 침식성이 있어서, 보통의 대응 수단으론 제거할 수 없어.",
  ui_story_5075_50750701_10_dialog_content = "만약 그런 특성이 진예가 말했던 원념에서 비롯된 거라면,\n그것도 일종의 의식체로 봐도 되지 않을까 싶어.",
  ui_story_5075_50750701_11_dialog_content = "그리고 의식이라면 감응 능력으로 간섭할 수 있어!",
  ui_story_5075_50750701_12_dialog_content = "게다가 몇 번 시도해 봤는데, 왠지 내 감응 능력을 그 침식성을 차단할 수 있는 것 같거든.",
  ui_story_5075_50750701_13_dialog_content = "조금만 더 연습하면 나도 침식된 수요령을 구할 수 있을지도 몰라.",
  ui_story_5075_50750701_14_dialog_content = "모두 이 몸에게 맡겨도 괜찮다만.",
  ui_story_5075_50750701_15_dialog_content = "안 돼. 우린 이제 동료잖아? 그럼 뭐든지 너 혼자 하게 둘 순 없어.",
  ui_story_5075_50750701_16_dialog_content = "세세한 일은 내 차례도 안 오겠는데? 그럼 주먹이 필요할 땐 언제든지 나한테 맡겨!",
  ui_story_5075_50750701_17_dialog_content = "캬오──",
  ui_story_5075_50750701_18_dialog_content = "그래, 아정도 있고!",
  ui_story_5075_50750701_19_dialog_content = "캬오!",
  ui_story_5075_50750701_20_dialog_content = "찍!",
  ui_story_5075_50750701_21_dialog_content = "어? 얜 아까 그 수요령이잖아? 왜 얘도 여기 있어?",
  ui_story_5075_50750701_22_dialog_content = "아정, 쟤한테 네 친구들한테 가 보라고 말 안 했어?",
  ui_story_5075_50750701_23_dialog_content = "캬오...",
  ui_story_5075_50750701_24_dialog_content = "싫다고 했다고?",
  ui_story_5075_50750701_25_dialog_content = "내가 감응 연습할 때도 걘 계속 거리를 두고 따라오고 있었어.",
  ui_story_5075_50750701_26_dialog_content = "검은 기운에 침식당해서 겁먹었던 거 아닐까? 우리랑 있으면 안심이라고 생각하는 거지.",
  ui_story_5075_50750701_27_dialog_content = "근데 이젠 우리랑 있는 게 더 위험할 거잖아. 우린 이제부터...",
  ui_story_5075_50750701_28_dialog_content = "...어디 가야 되는지 내가 물어봤었나?",
  ui_story_5075_50750701_29_dialog_content = "「어림가」로 갈 거야.",
  ui_story_5075_50750701_30_dialog_content = "기분 나쁜 기운이 있는 곳으로 갈 것이니라.",
  ui_story_5075_50750701_31_dialog_content = "어?",
  ui_story_5075_50750701_32_dialog_content = "목적지가 달라?!",
  ui_story_5075_50750701_33_dialog_content = "?",
  ui_story_5075_50750701_34_dialog_content = "아니, 만약 진짜 달랐으면 진작에 알았겠지.",
  ui_story_5075_50750701_35_dialog_content = "무방하다.",
  ui_story_5075_50750701_36_dialog_content = "어차피 이미 PlayerName 네 목적지에 도착했으니 말이야.",
  ui_story_5075_50750701_37_dialog_content = "여긴 다 뭐야? 어느 가게나 전부 고급스러워 보이는데?",
  ui_story_5075_50750701_38_dialog_content = "여기가 어림가구나... 사당 장터만큼 시끌벅적하진 않지만, 확실히 호화로운 느낌의 거리네.",
  ui_story_5075_50750701_39_dialog_content = "이곳은 이 몸도 알고 있다. 여기 사는 자들은 모두 부유한 자들이니라.",
  ui_story_5075_50750701_40_dialog_content = "<color=#e8d9bb>맑은 강이 거리를 관통하고, 양안에는 고층 누각이 솟아 있다.\n아직 겨울임에도 거리는 오색찬란한 모습으로 꾸며져 있었다.</color>",
  ui_story_5075_50750701_41_dialog_content = "<color=#e8d9bb>건물 사이 형형색색의 천은 바람에 흩날리며 춤을 추었고, 은방울 소리가 울려 퍼졌다.</color>",
  ui_story_5075_50750701_42_dialog_content = "<color=#e8d9bb>건물 안팎으로는 화려한 옷차림의 사람들이 즐비했고,\n오가는 금빛 상선이 수로를 가득 메우고 있었다.</color>",
  ui_story_5075_50750701_43_dialog_content = "길가에 저건 무슨 조각상이지?",
  ui_story_5075_50750701_44_dialog_content = "물고기들이 배를 둘러싸고 있어. 저 배랑 물고기 꼬리... 왠지 낯이 익은데...",
  ui_story_5075_50750701_45_dialog_content = "어디서 봤더라?",
  ui_story_5075_50750701_46_dialog_content = "교룡어다. 저들은 헤엄을 잘 치고, 늘 무리 지어 물속을 오가고 있느니라.",
  ui_story_5075_50750701_47_dialog_content = "허나 아무리 멀리 가더라도, 겨울이 되면 반드시 용주 근해로 돌아와 산란하지.",
  ui_story_5075_50750701_48_dialog_content = "하여 많은 이들이 교룡어에게 항해 안내를 부탁하곤 하느니라.",
  ui_story_5075_50750701_49_dialog_content = "물고기한테 부탁을 한다고?",
  ui_story_5075_50750701_50_dialog_content = "그렇다. 인간은 늘 못 할 일이 있으면 동물이나 수요령에게 선물을 주고 도움을 청하곤 했느니라.",
  ui_story_5075_50750701_51_dialog_content = "자고이래로 늘 그리하지 않았더냐.",
  ui_story_5075_50750701_52_dialog_content = "적어도 지금은 딱히 그래 보이진 않는데...",
  ui_story_5075_50750701_53_dialog_content = "이 조각상은 꽤 오래된 것 같아. 더러워진 데다가 흠집도 많고,\n한참 동안 관리하는 사람이 없었나 봐.",
  ui_story_5075_50750701_54_dialog_content = "아무래도 옛날엔 좋은 사이었지만, 지금은...",
  ui_story_5075_50750701_55_dialog_content = "끝이 났지.",
  ui_story_5075_50750701_56_dialog_content = "월백 씨! 벌써 돌아왔었네요?",
  ui_story_5075_50750701_57_dialog_content = "며칠 전에 왔어. 단지 린 가문에 또 여러 가지 일이 있어서 못 왔을 뿐이야.",
  ui_story_5075_50750701_58_dialog_content = "그래도 이젠 이렇게 왔잖아요.",
  ui_story_5075_50750701_59_dialog_content = "린 가문에 또 무슨 곤란한 일이라도 생긴 건가요?",
  ui_story_5075_50750701_60_dialog_content = "곤란한 일이라 말할 순 없겠네.",
  ui_story_5075_50750701_61_dialog_content = "잘못이 있었어.",
  ui_story_5075_50750701_62_dialog_content = "린 가문이 교룡어에게 저지른 잘못.",
  ui_story_5075_50750701_63_dialog_content = "...그래서 방금 「끝이 났다」고 하신 건가요?",
  ui_story_5075_50750701_64_dialog_content = "맞아.",
  ui_story_5075_50750701_65_dialog_content = "제 꼬리 만지지 말아 주세요.",
  ui_story_5075_50750701_66_dialog_content = "아, 안 만졌어요!",
  ui_story_5075_50750701_67_dialog_content = "PlayerName 당신 말하는 게 아냐.",
  ui_story_5075_50750701_68_dialog_content = "이런, 들켰구나.",
  ui_story_5075_50750701_69_dialog_content = "교룡어의 혈통을 지닌 광령은 드물기에 무심코 손이 가 버리고 말았느니라.",
  ui_story_5075_50750701_70_dialog_content = "참, 교룡어는 용의 먼 친척인 셈이라 하니, 그대와 이 몸도 먼 친척 아니더냐.",
  ui_story_5075_50750701_71_dialog_content = "그렇게 생각해 주신다면 영광이네요.",
  ui_story_5075_50750701_72_dialog_content = "어쩐지, 이 물고기 어디서 본 것 같더라니. 월백 씨가 생각 났던 거였네요.",
  ui_story_5075_50750701_73_dialog_content = "게다가 자세히 보니까 이 배도 신풍호랑 많이 닮았어요!",
  ui_story_5075_50750701_74_dialog_content = "그건 신풍호의 원형이거든.",
  ui_story_5075_50750701_75_dialog_content = "오래전 대해를 넘어 아스트라 대륙으로 건너가는 데 성공한 린 가문의 첫 번째 상선이기도 해.",
  ui_story_5075_50750701_76_dialog_content = "그랬군요. 근데 왜 린 가문의 상선 모형이 여기 있는데요?",
  ui_story_5075_50750701_77_dialog_content = "몰랐어?",
  ui_story_5075_50750701_78_dialog_content = "이 거리, 전에는 린 가문 거였어.",
  ui_story_5075_50750701_79_dialog_content = "거, 거리 전체가요?!",
  ui_story_5075_50750701_80_dialog_content = "최근엔 거래나 저당으로 잃은 것도 있었고, 최근 일련의 사건도 겪으면서\n거리의 소유권은 이미 분할됐어.",
  ui_story_5075_50750701_81_dialog_content = "지금도 린 가문 명의인 건 절반뿐이야.",
  ui_story_5075_50750701_82_dialog_content = "남은 그 절반의 최종 귀속자가 누가 될지도 앞으로의 동향에 달려 있고.",
  ui_story_5075_50750701_83_dialog_content = "절반만 해도 엄청난데요...",
  ui_story_5075_50750701_84_dialog_content = "찍──!",
  ui_story_5075_50750701_85_dialog_content = "으앗!",
  ui_story_5075_50750701_86_dialog_content = "<color=#e8d9bb>갑자기 달려든 꼬마 수요령에게 밀려 넘어지는 순간,\n칠흑 같은 한 줄기 다크매터가 서 있던 지면을 내리쳤다.</color>",
  ui_story_5075_50750701_87_dialog_content = "<color=#e8d9bb>쿠구구──!</color>",
  ui_story_5075_50750701_88_dialog_content = "PlayerName! 괜찮아?",
  ui_story_5075_50750701_89_dialog_content = "응, 얘 덕분에 살았어!",
  ui_story_5075_50750701_90_dialog_content = "찍찍찍...",
  ui_story_5075_50750701_91_dialog_content = "왜 이러지? 갑자기 괴로워하고 있는데?",
  ui_story_5075_50750701_92_dialog_content = "...이 녀석, 어느새 또 검은 기운에 감염돼 버렸어!",
  ui_story_5075_50750701_93_dialog_content = "아정?!",
  ui_story_5075_50750701_94_dialog_content = "캬오...",
  ui_story_5075_50750701_95_dialog_content = "<color=#e8d9bb>아정이 괴로운 듯 울부짖었고, 안정적이던 루미나가 흐트러지기 시작했다.</color>",
  ui_story_5075_50750701_96_dialog_content = "이 증상... 설마...",
  ui_story_5075_50750701_97_dialog_content = "(강제 감응!)",
  ui_story_5075_50750701_98_dialog_content = "일단 검은 기운의 침식은 차단했어. 그래도 빨리 근원을 찾아야 해!",
  ui_story_5075_50750701_99_dialog_content = "주위에도 갑자기 검은 기운이 엄청나게 생겨났어... 대체 어디서...",
  ui_story_5075_50750701_100_dialog_content = "침착하거라. 이 몸이 찾는 것은 그대가 아니라 봉인을 깨트린 자이니라.\n남의 손에 그리 끌려다녀서야 되겠느냐.",
  ui_story_5075_50750701_101_dialog_content = "진예? 너 누구랑 얘기하는 거야?",
  ui_story_5075_50750701_102_dialog_content = "물고기다.",
  ui_story_5075_50750701_103_dialog_content = "물고기...? 저 조각상 말하는 거야?",
  ui_story_5075_50750701_104_dialog_content = "[감응한다]",
  ui_story_5075_50750701_105_dialog_content = "여긴... 바닷속인가?",
  ui_story_5075_50750701_106_dialog_content = "누. 구. 냐.",
  ui_story_5075_50750701_107_dialog_content = "너... 그거 교룡어 꼬리야?",
  ui_story_5075_50750701_108_dialog_content = "린 가문이랑 관계가 있는 거야?",
  ui_story_5075_50750701_109_dialog_content = "린, 가문.",
  ui_story_5075_50750701_110_dialog_content = "비, 열, 해.",
  ui_story_5075_50750701_111_dialog_content = "증, 오, 해!",
  ui_story_5075_50750701_112_dialog_content = "!",
  ui_story_5075_50750701_113_dialog_content = "으윽...",
  ui_story_5075_50750701_114_dialog_content = "PlayerName, 괜찮아?",
  ui_story_5075_50750701_115_dialog_content = "괜찮아요. 다만 방금 감응한 곳은 그 어느 곳보다 검은 기운의 침식이 심했어요.",
  ui_story_5075_50750701_116_dialog_content = "그리고 누가 있었어요. 왠지... 린 가문과 관계가 있는 사람 같았어요.",
  ui_story_5075_50750701_117_dialog_content = "우룡이야.",
  ui_story_5075_50750701_118_dialog_content = "아는 사이인가요?",
  ui_story_5075_50750701_119_dialog_content = "우룡은 전에 린 가문과 협력했던 수요령이야.",
  ui_story_5075_50750701_120_dialog_content = "얼마 전 가주님께선 우룡에게 바다에 가서 요마 사건의 원인을 조사해 달라고 부탁하셨어.\n그런데 우룡은 그 뒤로 다시 돌아오지 않았어.",
  ui_story_5075_50750701_121_dialog_content = "...설마... 진예가 말했던... 그릇?! 이거 아무래도 최악의 상황이 벌어진 것 같은데요...",
  ui_story_5075_50750701_122_dialog_content = "봉인되어 있던 힘이 그릇으로 삼을 새로운 몸을 찾아버린 건지도 몰라요.",
  ui_story_5075_50750701_123_dialog_content = "찍!",
  ui_story_5075_50750701_124_dialog_content = "<color=#e8d9bb>꼬마 수요령이 갑자기 뛰쳐나가 길 구석에 서 있던 사람의 팔을 힘껏 물었다.</color>",
  ui_story_5075_50750701_125_dialog_content = "으악... 이 빌어먹을 짐승이!",
  ui_story_5075_50750701_126_dialog_content = "저리 꺼져!",
  ui_story_5075_50750701_127_dialog_content = "<color=#e8d9bb>힘껏 뿌리쳐진 수요령은 땅을 한참 구르더니 움직임을 멈췄다.</color>",
  ui_story_5075_50750701_128_dialog_content = "꼬맹아!",
  ui_story_5075_50750701_129_dialog_content = "흥...",
  ui_story_5075_50750701_130_dialog_content = "저 사람... 저 사람 몸에 검은 기운이 있어! 뭘 가지고 있는 거지?",
  ui_story_5075_50750701_131_dialog_content = "당신 뭐야?!",
  ui_story_5075_50750701_132_dialog_content = "네놈들이 알 필요는 없다.",
  ui_story_5075_50750701_133_dialog_content = "이런! 빨리 막아!",
  ui_story_5075_50750701_134_dialog_content = "늦었어!",
  ui_story_5075_50750701_135_dialog_content = "<color=#e8d9bb>수상한 사람은 품에 지니고 있던 물건을 힘껏 깨트렸고, 대량의 검은 기운을 방출했다.</color>",
  ui_story_5075_50750701_136_dialog_content = "(아까 감응했을 때 느꼈던 바닷속의 힘이랑 똑같아...!)",
  ui_story_5075_50750701_137_dialog_content = "<color=#e8d9bb>이제는 감응 능력을 쓰지 않고도 볼 수 있었다.</color>",
  ui_story_5075_50750701_138_dialog_content = "<color=#e8d9bb>이제는 감응 능력을 쓰지 않고도 볼 수 있었다.</color>",
  ui_story_5075_50750701_139_dialog_content = "<color=#e8d9bb>검은 기운이 짙은 다크매터를 두르고 끓는 물처럼 넘실거리며 끝없이 분출되고 있었다.</color>",
  ui_story_5075_50750701_140_dialog_content = "<color=#e8d9bb>모든 불안정한 에너지는 하나가 되었고, 끝내...</color>",
  ui_story_5075_50750701_141_dialog_content = "<color=#e8d9bb>맹렬하게 폭발했다.</color>",
  ui_story_5075_50750701_142_dialog_content = "무엄하다!",
  ui_story_5075_50750701_143_dialog_content = "<color=#e8d9bb>콰아앙──</color>",
  ui_story_5075_50750701_144_dialog_content = "<color=#e8d9bb>한 줄기 금빛 그림자가 천뢰와 함께 튀어나와 검은 기운의 파도를 막아냈지만,\n흩어진 잔해는 여전히 퍼져나갔다.</color>",
  ui_story_5075_50750701_145_dialog_content = "흥... 봉인을 깨트린 것이 너희들이더냐? 순순히 죄를 인정해라!",
  ui_story_5075_50750701_146_dialog_content = "콜록콜록...",
  ui_story_5075_50750701_147_dialog_content = "어떻게 된 거야? 진예는?",
  ui_story_5075_50750701_148_dialog_content = "검은 안개를 막고 나서 방금 그 남자를 쫓아가 버렸어.",
  ui_story_5075_50750701_149_dialog_content = "너무 막무가내잖아!",
  ui_story_5075_50750701_150_dialog_content = "뭐... 진예라면 괜찮을 것 같긴 하지만.",
  ui_story_5075_50750701_151_dialog_content = "이쪽은? 아무도 안 다쳤어?",
  ui_story_5075_50750701_152_dialog_content = "사람은 안 다쳤지만... 아정! 꼬맹아!",
  ui_story_5075_50750701_153_dialog_content = "캬오...",
  ui_story_5075_50750701_154_dialog_content = "아까 폭발로 검은 기운이 흩어지면서 이 녀석들 침식도 심해졌어.",
  ui_story_5075_50750701_155_dialog_content = "그뿐만이 아니야. 요마들도 이끌려 왔어.",
  ui_story_5075_50750701_156_dialog_content = "다들 싸울 준비해!",
  ui_story_5075_50750701_157_dialog_content = "캬아악!",
  ui_story_5075_50750702_1_dialog_content = "린 가문이 일군 터전을 너희가 짓밟게 놔둘 것 같아?",
  ui_story_5075_50750702_2_dialog_content = "크에엑──",
  ui_story_5075_50750702_3_dialog_content = "월백 씨 덕분에 여기 모여 있던 암귀는 다 해결했네요.",
  ui_story_5075_50750702_4_dialog_content = "다만 아까 그 검은 기운은 벌써 성안까지 퍼졌어요... 불길한 예감이 들어요.",
  ui_story_5075_50750702_5_dialog_content = "뭔가 좋은 방법이 없을까요...?",
  ui_story_5075_50750702_6_dialog_content = "있어.",
  ui_story_5075_50750702_7_dialog_content = "왕년 수준엔 미치지 못해도, 호진에서 린 가문의 힘은 아직 건재해.",
  ui_story_5075_50750702_8_dialog_content = "당신들을 린 가문 저택으로 데려다줄게.",
  ui_story_5075_50750702_9_dialog_content = "가주님께 상황을 전하고 린 가문의 힘을 동원해 이 문제를 해결하는 거야.",
  ui_story_5075_50750702_10_dialog_content = "정말요? 고마워요! 근데... 왜 아무것도 안 물어보고 우릴 도와주는 거죠?",
  ui_story_5075_50750702_11_dialog_content = "애초에 이 일은 린 가문과도 관계가 있어.",
  ui_story_5075_50750702_12_dialog_content = "게다가 당신을 돕는 데 이유가 필요할까?",
  ui_story_5075_50750702_13_dialog_content = "PlayerName, 잠깐만.",
  ui_story_5075_50750702_14_dialog_content = "나송, 왜 그래?",
  ui_story_5075_50750702_15_dialog_content = "이 꼬맹이 좀 부탁해도 될까?",
  ui_story_5075_50750702_16_dialog_content = "당연하지. 깜빡할 뻔했네. 아정 너도 이리 와.",
  ui_story_5075_50750702_17_dialog_content = "지금은 진예도 없으니까, 일단 내가 검은 기운의 침식을 막아볼게.",
  ui_story_5075_50750702_18_dialog_content = "캬오...",
  ui_story_5075_50750702_19_dialog_content = "아정?",
  ui_story_5075_50750702_20_dialog_content = "그리고 지금부터는 따로 움직이자.",
  ui_story_5075_50750702_21_dialog_content = "어? 나송 너까지 왜?",
  ui_story_5075_50750702_22_dialog_content = "검은 기운이 호진에 번졌다면, 다른 수요령도 분명히 감염됐을 거야.",
  ui_story_5075_50750702_23_dialog_content = "수요령은 나쁜 녀석들이 아냐. 그저 야생에서 자라온 탓에 본능적으로\n짐승의 습성대로 행동하고 있을 뿐이야.",
  ui_story_5075_50750702_24_dialog_content = "지금 사람들이 수요령을 대하는 태도는 점점 더 과격해지고 있어.",
  ui_story_5075_50750702_25_dialog_content = "검은 기운에 감염돼서 수요령들이 또 광폭해지고, 사람들을 해친다면...\n아마 인간과 수요령의 관계는 다시 회복할 수 없게 될지도 몰라.",
  ui_story_5075_50750702_26_dialog_content = "그래서 난 사태가 돌이킬 수 없게 되기 전에 감염된 수요령들을 붙잡고 싶어.",
  ui_story_5075_50750702_27_dialog_content = "게다가 정말로 인간에게 원한을 품은 수요령도 분명히 있을 거야.",
  ui_story_5075_50750702_28_dialog_content = "하지만 그 누구도 이런 식으로 녀석들의 입장을 강제로 결정할 자격은 없어.",
  ui_story_5075_50750702_29_dialog_content = "그렇지? 아정.",
  ui_story_5075_50750702_30_dialog_content = "난 네가 잘못하면 혼을 냈고, 잘하면 칭찬해 줬어.",
  ui_story_5075_50750702_31_dialog_content = "하지만 네가 뭘 할지 결정할 수 있는 건 영원히 너 자신뿐이야.",
  ui_story_5075_50750702_32_dialog_content = "나랑 같이 갈래?",
  ui_story_5075_50750702_33_dialog_content = "<color=#e8d9bb>나송은 몸을 숙여 아정을 가만히 바라보았다.</color>",
  ui_story_5075_50750702_34_dialog_content = "<color=#e8d9bb>땅에 쓰러져 있던 아정은 휘청거리면서도 몸을 일으켰다.</color>",
  ui_story_5075_50750702_35_dialog_content = "캬오!",
  ui_story_5075_50750702_36_dialog_content = "역시 내 단짝이라니까.",
  ui_story_5075_50750702_37_dialog_content = "그치만 지금 아정의 상태로는...",
  ui_story_5075_50750702_38_dialog_content = "진예만 있으면 괜찮았을 텐데.",
  ui_story_5075_50750702_39_dialog_content = "휴, 그거 너무 사치스러운 기대 아냐?",
  ui_story_5075_50750702_40_dialog_content = "부탁한다고 신령이 꼭 나타날 거라 생각하면 곤란해.",
  ui_story_5075_50750702_41_dialog_content = "자기 부모나 형제라도 뭐든지 부탁하면 싫은 소리를 들을 텐데, 신이라면 말할 것도 없잖아?",
  ui_story_5075_50750702_42_dialog_content = "뭐... 그것도 그렇네.",
  ui_story_5075_50750702_43_dialog_content = "인간들은 신령들한테 제사도 지내고 향도 피우고 하지만, 그건 대부분 일방적인 기대일 뿐이야.",
  ui_story_5075_50750702_44_dialog_content = "신령도 우릴 도울지 말지 선택할 자유가 있어.",
  ui_story_5075_50750702_45_dialog_content = "그러니까 인생에서 가장 의지가 되는 건 결국 자기 힘뿐인 거야!",
  ui_story_5075_50750702_46_dialog_content = "그 어떤 장벽이 막아서든, 내 주먹에 힘이 있다면 깨부술 수 있는 거지.",
  ui_story_5075_50750702_47_dialog_content = "캬오오!",
  ui_story_5075_50750702_48_dialog_content = "그럼 갈게.",
  ui_story_5075_50750702_49_dialog_content = "응, 순조롭길 바랄게.",
  ui_story_5075_50750702_50_dialog_content = "우리도 가자.",
  ui_story_5075_50750702_51_dialog_content = "린 가문 저택으로 데려다줄게.",
  ui_story_5075_50750801_1_dialog_content = "<color=#e8d9bb>제나라 왕궁</color>",
  ui_story_5075_50750801_2_dialog_content = "전하, 업나라에서 또 소식이 들어왔사옵니다.",
  ui_story_5075_50750801_3_dialog_content = "업나라에 주문했던 <color=#FFB400>해안포</color>가 도착했느냐?",
  ui_story_5075_50750801_4_dialog_content = "아, 아니옵니다...",
  ui_story_5075_50750801_5_dialog_content = "아니라? 전번에 값을 높인 후로 호송을 시작한 것이 아니었더냐?",
  ui_story_5075_50750801_6_dialog_content = "업나라의 서신에서는 그리 말했던 것이 맞사옵니다.",
  ui_story_5075_50750801_7_dialog_content = "허나 벌써 보름이 지났는데 화물이 오질 않기에 저희도 서신을 보내 재촉하였으나...",
  ui_story_5075_50750801_8_dialog_content = "과인이 맞혀 보마. 또 값을 높였더냐?",
  ui_story_5075_50750801_9_dialog_content = "...예.",
  ui_story_5075_50750801_10_dialog_content = "서신에 따르면, 화물을 운반하던 부대가 산에서 연락이 끊겼다고 하옵니다.",
  ui_story_5075_50750801_11_dialog_content = "제나라가 급히 필요로 하는 물품이니, 인원을 차출해 수색을 돕겠다고는 하나...",
  ui_story_5075_50750801_12_dialog_content = "그에 따른 비용을 우리 제나라에서 부담하라는 것이 저들의 요구이옵니다.",
  ui_story_5075_50750801_13_dialog_content = "아니면 5년 전 업나라가 제나라에 빌린 차관으로 상계하는 것도 가능하다 하옵니다.",
  ui_story_5075_50750801_14_dialog_content = "신의 생각에는 모두 값을 높이기 위한 허울로 보이옵니다.",
  ui_story_5075_50750801_15_dialog_content = "허나 우리가 지급을 거부한다면, 해안포는 계속 수색 중인 채로 남겠지요.",
  ui_story_5075_50750801_16_dialog_content = "어쩌면... 영영 찾을 수 없을 것이옵니다.",
  ui_story_5075_50750801_17_dialog_content = "황당하기 짝이 없구나!",
  ui_story_5075_50750801_18_dialog_content = "요마의 이변이 막 시작되었을 무렵에 주문한 일을 지금까지 끌어온 것도 모자라서...",
  ui_story_5075_50750801_19_dialog_content = "이번엔 호송 부대가 실종되었다니, 다음엔 해안포가 제 발로 사라졌다 하지 않겠느냐?",
  ui_story_5075_50750801_20_dialog_content = "서신을 보내 고하라. 계속 이와 같이 진화타겁을 꾀하려 든다면,\n양국의 모든 거래는 전면 취소다!",
  ui_story_5075_50750801_21_dialog_content = "허나 전하... 근래 들어 요마는 사방에서 더 심하게 날뛰고 있사옵니다.",
  ui_story_5075_50750801_22_dialog_content = "특히 연해 지역 일대에서는 궁의 지원을 바라는 목소리가 높아지고 있사옵니다.",
  ui_story_5075_50750801_23_dialog_content = "업나라 해안포의 도착이 더 지연된다면, 방어선을 지키기 어려울까 우려되옵니다.",
  ui_story_5075_50750801_24_dialog_content = "지키기 어렵다?",
  ui_story_5075_50750801_25_dialog_content = "용주에 어디 업나라만 있다더냐?",
  ui_story_5075_50750801_26_dialog_content = "우리 제나라는 물산이 풍부하고, 상업이 융성하여 나날이 수많은 부를 거두고 있다.",
  ui_story_5075_50750801_27_dialog_content = "해운이 여의치 않아도 하천 수운이 있지 않느냐.\n업나라와 교역이 틀어지면 다른 나라와 교역하면 그만이다.",
  ui_story_5075_50750801_28_dialog_content = "만물은 금전에서 나는 것이 아니더냐.\n제값만 치른다면 저 앙경의 강병조차 우리 제나라를 위해 쓸 수 있다.",
  ui_story_5075_50750801_29_dialog_content = "하면 업나라의 요구는...",
  ui_story_5075_50750801_30_dialog_content = "전부 거절하라.",
  ui_story_5075_50750801_31_dialog_content = "예, 전하.",
  ui_story_5075_50750801_32_dialog_content = "흥. 이제는 업나라조차 과인을 희롱하려 든단 말인가.",
  ui_story_5075_50750801_33_dialog_content = "당초 우리에게 차관을 빌릴 때의 곤궁함은 잊어버린 모양이지.",
  ui_story_5075_50750801_34_dialog_content = "그러고 보면 작화가 제나라에 온 것도 그해가 아니던가.",
  ui_story_5075_50750801_35_dialog_content = "국사는 어찌 생각하는가? 작화가 정말로 세자빈이 된다면, 그 차관도 논의의 여지는 있지 않겠나.",
  ui_story_5075_50750801_36_dialog_content = "전하, 임금의 말에는 희언이 있어서는 아니 되는 법입니다.\n작화는 큰 뜻을 품은 여인입니다. 이 일은 농담으로 하실 일이 아닙니다.",
  ui_story_5075_50750801_37_dialog_content = "흥, 과인도 알고 있네.",
  ui_story_5075_50750801_38_dialog_content = "허나 세자를 고분고분하게 만들 수 있는 이가 어디 흔하던가...",
  ui_story_5075_50750801_39_dialog_content = "전하, 지금 중요한 것은 세자의 일이 아닙니다.\n이 극심한 풍파를 두고 전하께서는 계책을 생각해 보셨습니까?",
  ui_story_5075_50750801_40_dialog_content = "제나라는 오랫동안 상업에 힘써 왔고, 군량과 기교술 등은 모두 타국과의 교역에 의존해 왔습니다.",
  ui_story_5075_50750801_41_dialog_content = "이번 업나라와 같은 일이 다시 벌어진다면...",
  ui_story_5075_50750801_42_dialog_content = "제나라는 수백 년간 상업을 근본으로 삼아 왔소. 국사가 말하는 계책이 어디 쉬운 일이겠나.",
  ui_story_5075_50750801_43_dialog_content = "또한 요마의 재앙이 오래 지속되지는 않을 것이오.",
  ui_story_5075_50750801_44_dialog_content = "차후에 다시 논의하도록 하세.",
  ui_story_5075_50750801_45_dialog_content = "과인은 고단하니 국사는 먼저 돌아가 쉬시오.",
  ui_story_5075_50750801_46_dialog_content = "...예, 전하.",
  ui_story_5075_50750801_47_dialog_content = "스승님? 여기 계셨군요.",
  ui_story_5075_50750801_48_dialog_content = "성밖 해안에서는 요마의 힘이 더 늘어났다 들었습니다.\n수요령의 일도 아직 원인을 규명하지 못했고 말이지요.",
  ui_story_5075_50750801_49_dialog_content = "게다가 그날 궁에서 작별한 이후, PlayerName 공자의 연락도 받지 못했습니다!",
  ui_story_5075_50750801_50_dialog_content = "스승님께서는 뭔가 알고 계시는지요.",
  ui_story_5075_50750801_51_dialog_content = "안심하세요. 그 소년은 무사합니다. 그에게 맡긴 일도 순조롭게 진행되고 있습니다.",
  ui_story_5075_50750801_52_dialog_content = "묻고 싶은 것은 그것뿐만이 아니겠지요.",
  ui_story_5075_50750801_53_dialog_content = "역시 스승님께선 뭐든지 알아채시네요. 그럼 단도직입적으로 여쭤볼게요.",
  ui_story_5075_50750801_54_dialog_content = "스승님은 그때 PlayerName 공자에게 조정 사람들 모르게 은밀히 행동하라 하셨습니다.",
  ui_story_5075_50750801_55_dialog_content = "조정에 불순한 일을 꾸미는 자가 있다고 의심하시는 것인지요.",
  ui_story_5075_50750801_56_dialog_content = "그 일은 노부가 아니라 군주의 호위에게 물어보는 게 좋을 성싶군요.",
  ui_story_5075_50750801_57_dialog_content = "<color=#FFB400>구</color> 말씀이신가요? 허나 구는 지금...",
  ui_story_5075_50750801_58_dialog_content = "말씀하지 않으셔도 됩니다. 노부는 나이가 들어 젊은 낭자들의 일에 대해서는 잘 모릅니다.",
  ui_story_5075_50750801_59_dialog_content = "스스로 판단하시지요.",
  ui_story_5075_50750801_60_dialog_content = "...알겠습니다. 스승님의 가르침에 감사드립니다.",
  ui_story_5075_50750801_61_dialog_content = "참, 노부가 군주에게 사과할 일이 하나 있습니다.",
  ui_story_5075_50750801_62_dialog_content = "다음에 그 소년을 만나거든, 이 노부의 사의를 대신 전해 주시지요.",
  ui_story_5075_50750801_63_dialog_content = "일전에 노부가 그 소년에게 물건을 하나 보내면서 군주의 이름을 빌렸습니다.",
  ui_story_5075_50750801_64_dialog_content = "부디 도움이 되었으면 좋겠는데 말이지요.",
  ui_story_5075_50750801_65_dialog_content = "(스승님은 역시 조정의 사람을 경계하고 계시는구나.)",
  ui_story_5075_50750801_66_dialog_content = "(허나 대체 누구건대 스승님께서 이토록 신중을 기한단 말인가.)",
  ui_story_5075_50750801_67_dialog_content = "(만약 구가 지금 조사하는 일과 관계가 있는 것이라면...)",
  ui_story_5075_50750801_68_dialog_content = "(그것보다 성안에 수상한 밀정의 움직임이 있거늘, 궁에서는 어찌 아무 소식도 없는 것인가.)",
  ui_story_5075_50750801_69_dialog_content = "(오직 구만 눈치챘다는 것인가? 아니면... 누군가가 고의로 구에게 발각된 것이란 말인가.)",
  ui_story_5075_50750801_70_dialog_content = "(허나 구는 그저 볼모인 군주의 호위에 지나지 않고, 나를 위해서만 움직인다.)",
  ui_story_5075_50750801_71_dialog_content = "(조정에 나쁜 뜻을 품은 자가 있더라도, 그리할 필요는 없었을 것이다. 아니면...)",
  ui_story_5075_50750801_72_dialog_content = "(배후가 제나라 사람이 아니라...)",
  ui_story_5075_50750801_73_dialog_content = "삑삑──",
  ui_story_5075_50750801_74_dialog_content = "(음? <color=#FFB400>선기경</color>의 전서조가 아닌가.)",
  ui_story_5075_50750801_75_dialog_content = "(전에 분명히 무슨 성능이 나빠서 호위의 눈을 피할 수 없으니,\n전서를 보내지 않겠다고 하더니...)",
  ui_story_5075_50750801_76_dialog_content = "(역시 날 겁주려고 해본 소리로구나.)",
  ui_story_5075_50750801_77_dialog_content = "......",
  ui_story_5075_50750801_78_dialog_content = "(...선극, 이게 대체 어떻게 된 간덩이인 게냐!)",
  ui_story_5075_50750801_79_dialog_content = "(당장 출궁해야겠구나.)",
  ui_story_5075_50750801_80_dialog_content = "국사님, 분부대로 주변의 호위를 물렸습니다.",
  ui_story_5075_50750801_81_dialog_content = "작화군주께도 전언을 전했습니다.",
  ui_story_5075_50750801_82_dialog_content = "알겠네.",
  ui_story_5075_50750902_1_dialog_content = "다 왔어. 여기가 어림가의 린 가문 저택이야.",
  ui_story_5075_50750902_2_dialog_content = "어? 여긴... 쪽지에 쓰여 있던 주소인데요?",
  ui_story_5075_50750902_3_dialog_content = "쪽지?",
  ui_story_5075_50750902_4_dialog_content = "오기 전에 궁에서 간식 선물을 받았거든요.\n근데 그릇 안에 쪽지가 있었고, 거기 나온 주소가 여기였어요.",
  ui_story_5075_50750902_5_dialog_content = "그리고 어디 쓰는지 알 수 없는 이 영패도 있었고요.",
  ui_story_5075_50750902_6_dialog_content = "...「순검사」의 영패가 아닌가.",
  ui_story_5075_50750902_7_dialog_content = "젊은이, 제나라에는 수군만 있을 뿐, 육지의 상비군이 없는 것은 알고 있는가?",
  ui_story_5075_50750902_8_dialog_content = "요충지를 지키고, 간적과 요마를 없애는 일은 모두 순검사가 맡고 있네.",
  ui_story_5075_50750902_9_dialog_content = "그리고 자네가 가진 그 영패로 순검사의 부대를 동원할 수 있네.",
  ui_story_5075_50750902_10_dialog_content = "왕궁 금위군을 제외하면 호진에서 가장 강하다고 할 수 있는 힘이 자네 손에 있다는 뜻일세.",
  ui_story_5075_50750902_11_dialog_content = "그런 중요한 물건을 제가 들고 돌아다녔다고요?!",
  ui_story_5075_50750902_12_dialog_content = "어라? 어르신은...!",
  ui_story_5075_50750902_13_dialog_content = "가주님, 어찌 나오셨습니까.",
  ui_story_5075_50750902_14_dialog_content = "밖에서 소리가 들리기에 보러 나와 보았다.",
  ui_story_5075_50750902_15_dialog_content = "헌데 네가 손님을 데리고 올 줄은 몰랐구나.",
  ui_story_5075_50750902_16_dialog_content = "이 젊은이가 바로 그 PlayerName인 모양이로군.",
  ui_story_5075_50750902_17_dialog_content = "종 형과 리청, 월백에게서 늘 얘기는 들었다만, 드디어 직접 보게 되는구려.",
  ui_story_5075_50750902_18_dialog_content = "허나 지금은 한담을 나눌 때가 아닐세.",
  ui_story_5075_50750902_19_dialog_content = "먼저 왜 날 보고 그리 놀라는지 말해줄 수 있겠는가.",
  ui_story_5075_50750902_20_dialog_content = "아, 죄송해요. 왠지 전에 뵌 것 같았거든요.",
  ui_story_5075_50750902_21_dialog_content = "바다 속... 검은 기운에 조종당하던 수요령의 기억 속에서요.",
  ui_story_5075_50750902_22_dialog_content = "우룡 말인가.",
  ui_story_5075_50750902_23_dialog_content = "아마 그럴 겁니다.",
  ui_story_5075_50750902_24_dialog_content = "가주님도 우룡을 아시고, 우룡은 린 가문을 미워하고 있어요... 대체 무슨 일이 있었던 거죠?",
  ui_story_5075_50750902_25_dialog_content = "이야기가 길어지겠군.",
  ui_story_5075_50750902_26_dialog_content = "일단 안으로 들어가세.",
  ui_story_5075_50750902_27_dialog_content = "내 아직 처리해야 할 일이 있으니, 손님은 월백 네가 먼저 모시도록 해라.",
  ui_story_5075_50750902_28_dialog_content = "네.",
  ui_story_5075_50750902_29_dialog_content = "차 마실래?",
  ui_story_5075_50750902_30_dialog_content = "아, 괜찮아요.",
  ui_story_5075_50750902_31_dialog_content = "그래, 그럼 마시지 마.",
  ui_story_5075_50750902_32_dialog_content = "아하하... 깜빡 잊고 있었네요. 월백 씨는 그런 성격이었죠.",
  ui_story_5075_50750902_33_dialog_content = "?",
  ui_story_5075_50750902_34_dialog_content = "아니에요. 확실히 지금은 허례허식 따질 때가 아니니까요.",
  ui_story_5075_50750902_35_dialog_content = "본론으로 들어가죠... 우룡과 린 가문 사이에 대체 무슨 일이 있었던 거죠?",
  ui_story_5075_50750902_36_dialog_content = "으음, 린 가문과 수요령의 관계는 아주 오래전에 시작됐어.",
  ui_story_5075_50750902_37_dialog_content = "그 무렵 린 가문은 아직 작은 상회에 불과했고, 경영도 잘 안돼서 연년 적자로 폐업 직전이었어.",
  ui_story_5075_50750902_38_dialog_content = "린 가문의 선조들은 가업의 위기를 구하고자, 남은 자산으로 상선 한 척을 샀고,\n바다 밖 세계에서 활로를 찾고자 했어.",
  ui_story_5075_50750902_39_dialog_content = "그리고 성공했지.",
  ui_story_5075_50750902_40_dialog_content = "그게 린 가문의 아스트라 대륙 교역의 시작이야.",
  ui_story_5075_50750902_41_dialog_content = "그 이야기는 카렌한테 들은 적 있어요. 쌍사성의 번영도 그 무렵부터 시작됐죠.",
  ui_story_5075_50750902_42_dialog_content = "그럼 다른 이야기는 생략할게.",
  ui_story_5075_50750902_43_dialog_content = "중요한 건 조상님이 탄 배가 귀항할 때 실수로 죽음의 바다라고 불리던 해역에 들어가 버렸던 거야.",
  ui_story_5075_50750902_44_dialog_content = "그때 린 가문엔 아직 혼천의도 없었고, 선극처럼 궁지를 벗어나는 재주를 가진\n기교사도 동행하지 않았어.",
  ui_story_5075_50750902_45_dialog_content = "조상님은 짙은 안개 속에서 보름 동안 표류했고, 물자도 거의 바닥 나 버리고 말았어.",
  ui_story_5075_50750902_46_dialog_content = "바로 그때 교룡어 떼를 만났던 거야.",
  ui_story_5075_50750902_47_dialog_content = "교룡어는 매년 겨울에 무리 지어 용주로 돌아와서 산란을 한다고 진예한테 들었어요.",
  ui_story_5075_50750902_48_dialog_content = "그럼 그 조상님은 교룡어의 도움을 받은 건가요?",
  ui_story_5075_50750902_49_dialog_content = "맞아.",
  ui_story_5075_50750902_50_dialog_content = "조상님은 바다의 길조로 여겨지는 교룡어를 따라 마침내\n죽음의 바다를 벗어나 고향으로 돌아오셨지.",
  ui_story_5075_50750902_51_dialog_content = "그 뒤로 아스트라와의 교역은 반드시 겨울에만 귀항하도록 했어.",
  ui_story_5075_50750902_52_dialog_content = "린 가문은 교룡어에게 많은 먹이를 줬고, 교룡어는 바다에서 린 가문의 상선을 이끌었지.",
  ui_story_5075_50750902_53_dialog_content = "그렇게 해서 교룡어는 린 가문의 상징이 됐어.",
  ui_story_5075_50750902_54_dialog_content = "이 어림가의 이름도 이 관계에서 유래한 거야.",
  ui_story_5075_50750902_55_dialog_content = "하지만 그 조상님이 돌아가시고, 후대를 거치면서 린 가문 상회는 점점 커져갔어.",
  ui_story_5075_50750902_56_dialog_content = "매년 한 번의 항해로는 이미 상회의 무역 수요를 감당할 수 없게 됐지.",
  ui_story_5075_50750902_57_dialog_content = "그래서 후대의 가주는 교룡어에게 항해 횟수를 늘려달라고 요구했어.",
  ui_story_5075_50750902_58_dialog_content = "잠깐만요, 물고기랑 논의를 한다고요?",
  ui_story_5075_50750902_59_dialog_content = "날 보고 있으면서 뭔가 느낀 게 없어?",
  ui_story_5075_50750902_60_dialog_content = "당시 교룡어의 우두머리는 <color=#FFB400>수요령</color>이었어.",
  ui_story_5075_50750902_61_dialog_content = "린 가문의 교룡어 혈통은 그때부터 시작됐던 거야.",
  ui_story_5075_50750902_62_dialog_content = "하지만 그러다가 린 가문은 당초의 약속을 어기고,\n교룡어의 습성을 무시한 항해를 강행하기 시작했어.",
  ui_story_5075_50750902_63_dialog_content = "결국 둘의 관계는 서서히 악화됐지.",
  ui_story_5075_50750902_64_dialog_content = "심지어 한 번은 린 가문의 배가 교룡어의 서식지를 파괴해 버렸어.",
  ui_story_5075_50750902_65_dialog_content = "그 일로 지금의 교룡어 우두머리를 완전히 화나게 해 버렸고,\n우두머리는 린 가문과의 협력을 끝내기로 결정한 거야.",
  ui_story_5075_50750902_66_dialog_content = "이제 막 인간의 모습으로 변할 수 있게 된 우룡이 저택에 들이쳐\n날 비열하다고 욕하던 모습이 지금도 기억 나는군.",
  ui_story_5075_50750902_67_dialog_content = "가주님, 돌아오셨군요.",
  ui_story_5075_50750902_68_dialog_content = "가주님...",
  ui_story_5075_50750902_69_dialog_content = "허허, 방금 대화가 들려서 말이지.",
  ui_story_5075_50750902_70_dialog_content = "이런 일은 아직 젊은 자네가 이해하긴 어려울 것이네.",
  ui_story_5075_50750902_71_dialog_content = "나도 변명할 생각은 없네. 선대께서 신의를 저버린 것은 사실이니 말이야.",
  ui_story_5075_50750902_72_dialog_content = "허나 나는 상인일세. 린 가문이 막대한 이익을 거두어 호진 상계의 정점에 섰던 것도\n그 결정 덕분임을 잘 알고 있네.",
  ui_story_5075_50750902_73_dialog_content = "만약 내가 당시의 가주였더라도 같은 결단을 내렸을 걸세.",
  ui_story_5075_50750902_74_dialog_content = "만약 혼천의에 관한 소식을 이미 입수한 상황이 아니었다면,\n심지어 린 가문은 그리 쉽사리 우룡을 놓아주지 않았을지도 모르네.",
  ui_story_5075_50750902_75_dialog_content = "그를 감금하여 길을 안내하는 도구로 삼았을 수도 있겠지.",
  ui_story_5075_50750902_76_dialog_content = "우룡이 나와 린 가문을 증오하는 것은 당연한 일일세.",
  ui_story_5075_50750902_77_dialog_content = "일찍이 린 가문은 신의를 저버리고 은혜를 원수로 갚았네.",
  ui_story_5075_50750902_78_dialog_content = "작금의 처지는 어쩌면 그에 대한 응보일지도 모르지.",
  ui_story_5075_50750902_79_dialog_content = "연안에 요마가 출몰했으나, 제나라는 안정된 방어선을 꾸릴 힘이 없었네.",
  ui_story_5075_50750902_80_dialog_content = "업나라에서 사들였다는 해안포는 도착할 기색조차 보이지 않고 있지.",
  ui_story_5075_50750902_81_dialog_content = "린 가문의 상선은 이미 오랫동안 바다에 나가지 못했고, 연안의 사업도 정체된 상태일세.\n그야말로 설상가상이지.",
  ui_story_5075_50750902_82_dialog_content = "시박사에서 풀려난 뒤로, 나는 종 형의 충고도 듣지 않고 염치없이 우룡을 찾아갔네.",
  ui_story_5075_50750902_83_dialog_content = "다시 한번 린 가문이 항로를 열 수 있도록 상선을 지켜달라 부탁했으나,\n당연히 쫓겨나고 말았지.",
  ui_story_5075_50750902_84_dialog_content = "허나 PlayerName 그대의 말로 보건대, 우룡은 결국 바다로 가서\n사정을 조사해 주었던 모양이군...",
  ui_story_5075_50750902_85_dialog_content = "하지만 악룡의 원념에 침식당해 점차 광폭해지고, 주변의 수요령들의 원념에도 불을 지펴버렸죠.",
  ui_story_5075_50750902_86_dialog_content = "...그것은 린 가문의 죄업이니까, 응당 린 가문이 해결하야 해.",
  ui_story_5075_50750902_87_dialog_content = "<color=#e8d9bb>콰앙──!</color>",
  ui_story_5075_50750902_88_dialog_content = "수요령을 쫓아내자!",
  ui_story_5075_50750902_89_dialog_content = "밖에 무슨 일이 생겼나?",
  ui_story_5075_50751001_1_dialog_content = "<color=#e8d9bb>길 한복판에 선 나송은 정신을 잃고 쓰러진 수요령들을 분노한 사람들로부터 지키고 있었다.</color>",
  ui_story_5075_50751001_2_dialog_content = "다들 진정해! 이 녀석들은 지금 자기가 원해서 이러는 게 아니야!",
  ui_story_5075_50751001_3_dialog_content = "내가 이미 얌전하게 만들었다고! 이제 녀석들을 홀린 힘을 없애기만 하면...",
  ui_story_5075_50751001_4_dialog_content = "<color=#e8d9bb>퍽!</color>",
  ui_story_5075_50751001_5_dialog_content = "<color=#e8d9bb>인파 속에서 누군가가 나송을 향해 돌을 던졌다.</color>",
  ui_story_5075_50751001_6_dialog_content = "캬오!",
  ui_story_5075_50751001_7_dialog_content = "아정! 너도 진정해!",
  ui_story_5075_50751001_8_dialog_content = "난 괜찮아. 지금은 저 사람들이랑 부딪히면 안 돼.",
  ui_story_5075_50751001_9_dialog_content = "사람이 다쳤는데 원하고 자시고가 어딨어?!",
  ui_story_5075_50751001_10_dialog_content = "그러니까 말했잖아! 수요령은 재수가 없다고!\n평소에 도둑질하는 것도 모자라서, 이젠 사람까지 죽이려 들었잖아!",
  ui_story_5075_50751001_11_dialog_content = "호진성은 수백 년 동안 늘 평화로웠어. 그런데 지금은 요마까지 나타나고 있어!",
  ui_story_5075_50751001_12_dialog_content = "이러고도 수요령 탓이 아니라고?! 똑같이 사악한 놈들이잖아!",
  ui_story_5075_50751001_13_dialog_content = "당신 같은 사람들은 법술을 다룰 줄 아니까 자기 일 아니라고 쉽게 말하는데...",
  ui_story_5075_50751001_14_dialog_content = "당신들은 안 무섭겠지만 우린 무섭다고!",
  ui_story_5075_50751001_15_dialog_content = "그런 재수 없는 놈들을 성안에 둘 순 없어! 전부 쫓아내!",
  ui_story_5075_50751001_16_dialog_content = "쫓아내! 쫓아내!",
  ui_story_5075_50751001_17_dialog_content = "가서 도와줘야겠어요!",
  ui_story_5075_50751001_18_dialog_content = "기다려. 아무 준비도 없이 가 봤자 소용없어.",
  ui_story_5075_50751001_19_dialog_content = "저 사람들은 지금 이성을 잃었어. 무슨 말을 해도 들리지 않아.",
  ui_story_5075_50751001_20_dialog_content = "더 강한 힘을 보여주거나, 모두가 진심으로 승복할 수 있는 보장을 한다면 모를까.",
  ui_story_5075_50751001_21_dialog_content = "전 그 영패가 있잖아요! 그걸 쓰면 순검사를 움직일 수 있다면서요.",
  ui_story_5075_50751001_22_dialog_content = "지금 순검사 병력은 아마 성안 곳곳에서 요마를 퇴치하고 있을 거야.",
  ui_story_5075_50751001_23_dialog_content = "게다가 순검사가 개입한다면... 백성들과의 골은 더 깊어질 뿐이야.",
  ui_story_5075_50751001_24_dialog_content = "그치만 지금 다른 방법도 없잖아요...",
  ui_story_5075_50751001_25_dialog_content = "말했잖아. 나한테 있다고. 아니면 린 가문한테 있다고 해야겠지.",
  ui_story_5075_50751001_26_dialog_content = "가주님도 들으셨겠죠.",
  ui_story_5075_50751001_27_dialog_content = "그럼 가주님께 정식으로 요청하겠습니다. 제게 호진성 <color=#FFB400>린 가문 가주대행</color>의 자격을 주세요.",
  ui_story_5075_50751001_28_dialog_content = "제가 이번 일을 해결하겠어요. 그러려면 린 가문의 물자와 인원을 동원할 권한이 필요해요.",
  ui_story_5075_50751001_29_dialog_content = "어찌 해결할 생각이냐.",
  ui_story_5075_50751001_30_dialog_content = "지금의 린 가문 상회엔 몇 년 전만큼의 권세는 없지만,\n몇 대를 거친 경영으로 백성들 사이의 명망은 작지 않아요.",
  ui_story_5075_50751001_31_dialog_content = "린 가문의 이름으로 이 일을 해결하겠다고 약조하고,\n의원과 일꾼을 보내 해를 입은 백성들을 돕겠습니다.",
  ui_story_5075_50751001_32_dialog_content = "그 말의 무게와, 거기에 잡히는 저당이 무엇인지 아느냐?",
  ui_story_5075_50751001_33_dialog_content = "린 가문의 가업은 작지 않으나, 한 성의 백성을 쉬이 책임질 수 있는 지경은 아니다.",
  ui_story_5075_50751001_34_dialog_content = "게다가 밀수 누명을 겨우 벗은 것도 얼마 전 일이다.",
  ui_story_5075_50751001_35_dialog_content = "장사는 전쟁이다. 사적으로 수완을 부려 환심을 살 수는 있어도,\n명성은 오히려 깨끗해야 하는 법이다.",
  ui_story_5075_50751001_36_dialog_content = "린 가문의 이름으로 수요령의 보증인이 된다면, 무슨 일이 생겼을 때\n만인의 과녁이 되는 것 또한 린 가문이란 말이다.",
  ui_story_5075_50751001_37_dialog_content = "알고 있습니다.",
  ui_story_5075_50751001_38_dialog_content = "하지만 수요령이 사람을 해치는 것은 우룡이 조종하고 있기 때문입니다.\n그리고 인간에 대한 우룡의 원한은 린 가문으로 인한 것입니다.",
  ui_story_5075_50751001_39_dialog_content = "린 가문은 마땅히 그 책임을 져야 합니다.",
  ui_story_5075_50751001_40_dialog_content = "참으로 세상이 변했구나.",
  ui_story_5075_50751001_41_dialog_content = "제나라는 장사를 중히 여기고, 상인은 이익을 추구한다.",
  ui_story_5075_50751001_42_dialog_content = "내가 젊을 때는 미미한 이익을 두고도 싸움을 벌이는 이들이 있었고,\n거지 손의 쌀 한 움큼조차 탐을 내던 시대였다.",
  ui_story_5075_50751001_43_dialog_content = "하물며 린 가문은 대대로 모시던 교룡어조차 포기했다.",
  ui_story_5075_50751001_44_dialog_content = "헌데 너는 내게 지금 「책임」이라는 허울 좋은 명목을 위해,\n오랜 세월 고생해 쌓아 올린 모든 것을 걸라는 말이냐.",
  ui_story_5075_50751001_45_dialog_content = "해낸다면 허울 좋은 명목이 아니게 되겠지요.",
  ui_story_5075_50751001_46_dialog_content = "잠깐만요. 지금 집안싸움 할 때가 아니잖아요...",
  ui_story_5075_50751001_47_dialog_content = "소생이 가르쳐 드릴 수 있는 주문이 하나 있긴 합니다.",
  ui_story_5075_50751001_48_dialog_content = "무슨 일이 벌어지든 그 주문만 외우면 아무리 큰 싸움도 즉시 원만하게 해결할 수 있지요.",
  ui_story_5075_50751001_49_dialog_content = "(아무리 생각해도 영 못 믿겠지만... 그래도 시도해 봐서 손해는 없겠지!)",
  ui_story_5075_50751001_50_dialog_content = "<color=#FFB400>새, <size=45>새해잖아요!</size></color>",
  ui_story_5075_50751001_51_dialog_content = "......",
  ui_story_5075_50751001_52_dialog_content = "......",
  ui_story_5075_50751001_53_dialog_content = "허허허... 새해라.",
  ui_story_5075_50751001_54_dialog_content = "송구영신, 새로운 모습을 갖출 시기이지.",
  ui_story_5075_50751001_55_dialog_content = "한참을 준비했는데, 이제 하루만 더 있으면 새해 정초인가.",
  ui_story_5075_50751001_56_dialog_content = "네.",
  ui_story_5075_50751001_57_dialog_content = "제야 만찬 준비는 다 되었느냐.",
  ui_story_5075_50751001_58_dialog_content = "식재료 대부분은 빙실에 두었습니다. 채소 주문도 마쳤으니 당일 도착할 겁니다.",
  ui_story_5075_50751001_59_dialog_content = "상회 장부도 며칠 전에 검토를 끝냈습니다. 결산서는 가주님 서재에 두었습니다.",
  ui_story_5075_50751001_60_dialog_content = "비록 올해 린 가문의 사업이 어렵긴 했지만, 호위와 일꾼들에게는\n2개월 치 봉급을 더 주기로 제 단독으로 결정했습니다.",
  ui_story_5075_50751001_61_dialog_content = "그래도 주관 하나는 뚜렷하구나.",
  ui_story_5075_50751001_62_dialog_content = "순식간에 변하는 바다의 상황 앞에서 선장은 가장 빠르게 판단을 내려야 하니까요.",
  ui_story_5075_50751001_63_dialog_content = "순풍인가 싶다가도 어느덧 풍랑이 밀려올 때, 변화의 순간을 잡지 못한다면\n돌이킬 수 없게 됩니다.",
  ui_story_5075_50751001_64_dialog_content = "하면 너는 지금의 상황이 린 가문을 밀어줄 「순풍」이라 보느냐.",
  ui_story_5075_50751001_65_dialog_content = "네게 그 확신이 있다면, 그 요청을 들어주마.",
  ui_story_5075_50751001_66_dialog_content = "<size=28>다행이다...</size>",
  ui_story_5075_50751001_67_dialog_content = "<size=45>확신은 없습니다.</size>",
  ui_story_5075_50751001_68_dialog_content = "푸웁── 콜록콜록콜록...",
  ui_story_5075_50751001_69_dialog_content = "하지만 한 가지는 압니다. 진정 큰 파도가 몰아치기 시작하면,\n배를 모는 자의 그 어떤 계책도 소용이 없는 법입니다.",
  ui_story_5075_50751001_70_dialog_content = "마지막까지 배를 지탱하는 것은 결국 흔들림 없이 바르게 뻗은 용골일 뿐이죠.",
  ui_story_5075_50751001_71_dialog_content = "배의 중추는 결코 굽어선 안 됩니다.",
  ui_story_5075_50751001_72_dialog_content = "......",
  ui_story_5075_50751001_73_dialog_content = "작금의 형세에 대해서는 네 판단이 옳을지도 모르지. 결국 나는 구시대의 늙은이일 뿐이니 말이야.",
  ui_story_5075_50751001_74_dialog_content = "허나 내가 보기에 네 행동은 지나치게 무모하다.",
  ui_story_5075_50751001_75_dialog_content = "가주님──",
  ui_story_5075_50751001_76_dialog_content = "그럼에도 불구하고, 신풍호의 선장은 너다.\n린 가문의 명줄이라 할 수 있는 항로를 손에 쥐고 있지.",
  ui_story_5075_50751001_77_dialog_content = "타인들의 눈에 네가 하는 말은 곧 린 가문을 대표하는 것이나 다름없다.",
  ui_story_5075_50751001_78_dialog_content = "그 말씀은...",
  ui_story_5075_50751001_79_dialog_content = "내 비록 늙었으나, 그래도 상인이다. 여러 측면에서 헤아리고 이해득실을 잴 것이다.",
  ui_story_5075_50751001_80_dialog_content = "너는 새로운 시대의 큰 배를 이끌 수 있는 선장이다. 이번 일은 네 마음껏 해 보거라.",
  ui_story_5075_50751001_81_dialog_content = "네가 해낸다면 넌 린 가문의 공신이다. 앞으로는 용주 근해의 항로도 네게 맡기마.",
  ui_story_5075_50751001_82_dialog_content = "허나 해내지 못한다면, 넌 가주의 명을 어기고 독단을 저지른 죄인이다.",
  ui_story_5075_50751001_83_dialog_content = "그때가 되면 린 가문은 널 철저히 추방할지도 모른다.\n어쩌면 네 지금 성조차 쓸 수 없게 될지도 모르지.",
  ui_story_5075_50751001_84_dialog_content = "이 조건을 받아들일 수 있느냐.",
  ui_story_5075_50751001_85_dialog_content = "<size=45>받아들이겠습니다.</size>",
  ui_story_5075_50751001_86_dialog_content = "PlayerName, 가자.",
  ui_story_5075_50751001_87_dialog_content = "네... 아, 잠시만요.",
  ui_story_5075_50751001_88_dialog_content = "가주님, 이 영패를 맡아 주실 수 있을까요?",
  ui_story_5075_50751001_89_dialog_content = "이런 중요한 물건을 내게 안심하고 맡길 수 있는가?",
  ui_story_5075_50751001_91_dialog_content = "내가 신의를 저버린 소인배란 사실을 잊은 것은 아니겠지.",
  ui_story_5075_50751001_92_dialog_content = "하하... 전혀 불안하지 않다고 하면 거짓말이겠죠.",
  ui_story_5075_50751001_93_dialog_content = "하지만 지금은 제가 이 영패를 쓸 기회도 없을 것 같고,\n영패랑 같이 있던 지도에도 가주님 저택이 표시돼 있었거든요.",
  ui_story_5075_50751001_94_dialog_content = "그리고 가주님은 계속 자신을 믿으면 안 된다고 하시지만,\n월백 씨나 종서 씨도 가주님을 신뢰하고 있잖아요.",
  ui_story_5075_50751001_95_dialog_content = "전 두 사람의 판단을 믿어요.",
  ui_story_5075_50751001_96_dialog_content = "제 감응 능력이 말해주고 있어요. 만에 하나 가주님이 정말로 뭔가 나쁜 일을 하려고 해도,\n여기라면 분명히 누군가 가주님을 막아설 거예요.",
  ui_story_5075_50751001_97_dialog_content = "하면 내 받아두겠네.",
  ui_story_5075_50751001_98_dialog_content = "잘 부탁드릴게요.",
  ui_story_5075_50751001_99_dialog_content = "월백 씨, 이제 가죠.",
  ui_story_5075_50751001_100_dialog_content = "휴, 요즘 젊은이들이란.",
  ui_story_5075_50751001_101_dialog_content = "위험을 향해 달릴 줄만 알고, 진중함이라고는 찾아볼 수가 없군.\n이래서야 린 가문의 앞날을 어찌 염려치 않을 수 있겠나.",
  ui_story_5075_50751001_102_dialog_content = "정작 린 형 표정은 그리 말하지 않으시는 것 같소이다.",
  ui_story_5075_50751001_103_dialog_content = "「린 가문의 훗날을 맡길 수 있겠구나」라고 거의 얼굴에 써 두신 것만 같소.",
  ui_story_5075_50751001_104_dialog_content = "허허허, 역시 종 형의 눈은 속일 수가 없구려.",
  ui_story_5075_50751001_105_dialog_content = "내 본디 과거의 갈등을 짊어지고, 후인들에게 더 깨끗한 린 가문을 전하고 싶었네.",
  ui_story_5075_50751001_106_dialog_content = "헌데 내 미처 손을 쓰기도 전에 월백 저 아이가 그 짐을 먼저 짊어져 버렸지 않은가.",
  ui_story_5075_50751001_107_dialog_content = "그것보다 종 형은 가서 돕지 않고 계속 지켜만 볼 생각인가?",
  ui_story_5075_50751001_108_dialog_content = "PlayerName 저 소년은 종 형이 있는 것도 알았던데 말이오.",
  ui_story_5075_50751001_109_dialog_content = "린 형도 매한가지 아니시오?",
  ui_story_5075_50751001_110_dialog_content = "순검사의 영패까지 가지고 왔건만, 린 형도 국사와의 거래에 대해서는 일절 거론하지 않았잖소.",
  ui_story_5075_50751001_111_dialog_content = "국사를 돕기로 약조하고, 젊은이가 오자마자 다급히 내게 린 가문 호위를\n움직일 준비를 하라던 린 형 아니신가.",
  ui_story_5075_50751001_112_dialog_content = "그런데도 짐짓 방금 같은 연기까지 하시고 말이오.",
  ui_story_5075_50751001_113_dialog_content = "우리 같은 늙은이들의 복잡한 수작을 젊은이들에게 해명하기가 여간 어려운 게 아니지 않은가.",
  ui_story_5075_50751001_114_dialog_content = "춘삭절을 맞이해 준비한 송구영신의 의식인 셈 치세.",
  ui_story_5075_50751001_115_dialog_content = "정초도 안 됐는데 온갖 허울 좋은 소리는 다 듣지 않았는가.",
  ui_story_5075_50751001_116_dialog_content = "좋은 징조가 아니겠나.",
  ui_story_5075_50751001_117_dialog_content = "헛소리 집어치워! 수요령을 감싸는 놈은 누가 봐도 못 믿을 놈이라고!",
  ui_story_5075_50751001_118_dialog_content = "그 재수 없는 놈들 쫓아내야 하니까 지금이라도 비켜!",
  ui_story_5075_50751001_119_dialog_content = "안 비킨다면 그쪽이 법술을 쓴다고 우리도 피할 생각은 없으니까!",
  ui_story_5075_50751001_120_dialog_content = "다들 불안한 건 알겠는데, 아무리 그래도 이건 이치에 안 맞잖아!",
  ui_story_5075_50751001_121_dialog_content = "전부 쫓아내!",
  ui_story_5075_50751001_122_dialog_content = "쫓아내라──!",
  ui_story_5075_50751001_123_dialog_content = "캬오!",
  ui_story_5075_50751001_124_dialog_content = "이런... 아직 손을 못 쓴 수요령이...",
  ui_story_5075_50751001_125_dialog_content = "「이룡의 선풍!」",
  ui_story_5075_50751002_1_dialog_content = "<color=#e8d9bb>마치 한 자루의 예리한 비수처럼 목월백은 수요령 무리 속으로 뛰어들었다.</color>",
  ui_story_5075_50751002_2_dialog_content = "<color=#e8d9bb>보는 사람들이 미처 반응할 틈도 없이, 방금 전까지 날뛰던 수요령은 의식을 잃고 길가에 쓰러졌다.</color>",
  ui_story_5075_50751002_3_dialog_content = "누...누구야? 솜씨가 대단한데?",
  ui_story_5075_50751002_4_dialog_content = "저 사람 알아... 린 가문 상회의 목월백 선장이야.",
  ui_story_5075_50751002_5_dialog_content = "근데 저 꼬리... 수요령의 혈통을 지닌 건가? 그럼 설마...",
  ui_story_5075_50751002_6_dialog_content = "저 사람이 방금 우릴 구해줬잖아! 무슨 말을 하려는 거야?",
  ui_story_5075_50751002_7_dialog_content = "여러분, 제 이야기를 좀 들어주세요.",
  ui_story_5075_50751002_8_dialog_content = "오늘 일로 놀라거나 다치신 분도, 손실을 입은 분도 있다는 건 알고 있어요.",
  ui_story_5075_50751002_9_dialog_content = "저도 여러분과 마찬가지로 화가 난 사람이에요.",
  ui_story_5075_50751002_10_dialog_content = "하지만 이 일의 원흉은 여기 있는 수요령들이 아니라, 이들을 이용해 사람을 해치려는 자예요.",
  ui_story_5075_50751002_11_dialog_content = "우리가 수요령을 적대한다면, 그건 놈이 노리는 함정에 빠지게 되는 꼴이에요.",
  ui_story_5075_50751002_12_dialog_content = "당신도 수요령의 피가 흐르니까 그렇게 말하는 거겠지!",
  ui_story_5075_50751002_13_dialog_content = "하지만 제 몸에는 여러분과 같은 광령의 피도 흐르고 있어요.\n린 가문의 사업 상대도 수요령이 아니라 사람이죠.",
  ui_story_5075_50751002_14_dialog_content = "제가 해로운 일을 할 이유가 있을까요?",
  ui_story_5075_50751002_15_dialog_content = "......",
  ui_story_5075_50751002_16_dialog_content = "말로만 해서 여러분의 신뢰를 구할 자격이 없다는 건 물론 알고 있어요.",
  ui_story_5075_50751002_17_dialog_content = "하지만 제가 린 가문 상회의 이름으로 보증하죠. 반드시 증거를 찾고 진상을 밝혀내겠어요.",
  ui_story_5075_50751002_18_dialog_content = "여러분도 악인에게 이용당하고, 그 원흉이 배후에서 활개 치는 걸 원하진 않겠죠?",
  ui_story_5075_50751002_19_dialog_content = "아무리 그렇게 말해도...",
  ui_story_5075_50751002_20_dialog_content = "(여전히 의심하고 있어. 하지만 우리도 당장 내세울 증거는... 아, 맞아!)",
  ui_story_5075_50751002_21_dialog_content = "(강제 감응!)",
  ui_story_5075_50751002_22_dialog_content = "(제발... 아주 조금이라도 좋으니까, 내가 본 걸 다른 사람들한테도 전해주는 거야...!)",
  ui_story_5075_50751002_23_dialog_content = "여러분, 이 수요령들을 보세요!",
  ui_story_5075_50751002_24_dialog_content = "저...저게 뭐지?!",
  ui_story_5075_50751002_25_dialog_content = "이게 바로 배후의 원흉이 수요령을 조종하는 힘이에요!",
  ui_story_5075_50751002_26_dialog_content = "이 힘이 사라지지 않는 한, 수요령들을 쫓아내 봤자 아무 소용도 없어요!",
  ui_story_5075_50751002_27_dialog_content = "왠지 거짓말하고 있는 건 아닌 것 같아...",
  ui_story_5075_50751002_28_dialog_content = "린 가문도 그동안 확실히 사람들한테 많은 도움을 줘 왔고 말이야. 하지만...",
  ui_story_5075_50751002_29_dialog_content = "<color=#e8d9bb>사람들은 모여서 의논하기 시작했고, 얼마 후 대표로 한 사람이 나섰다.</color>",
  ui_story_5075_50751002_30_dialog_content = "일단은 당신들을 믿겠습니다.",
  ui_story_5075_50751002_31_dialog_content = "오늘은 날도 늦었고 우리도 여기 계속 머물 생각은 없습니다.",
  ui_story_5075_50751002_32_dialog_content = "하지만 성안엔 아직도 수요령이 잔뜩 돌아다니고 있습니다.\n당신들이 조사하는 동안 무슨 일이 생길지 또 누가 압니까?",
  ui_story_5075_50751002_33_dialog_content = "그러니까 우리도 조건을 걸어야겠습니다.",
  ui_story_5075_50751002_34_dialog_content = "춘삭절 전까지 이번 사건을 꼭 해결해서, 사람들이 무사히 새해를 맞게 해 주는 겁니다.",
  ui_story_5075_50751002_35_dialog_content = "좋아요.",
  ui_story_5075_50751002_36_dialog_content = "그래야죠! 새해인데 누군들 빨리 안 끝내고 싶겠어요?",
  ui_story_5075_50751002_37_dialog_content = "<color=#e8d9bb>그 후 목월백이 일꾼들을 불러 사람들을 달래자, 모여 있던 사람들도 하나둘씩 돌아갔다.</color>",
  ui_story_5075_50751002_38_dialog_content = "도와줘서 고마워.",
  ui_story_5075_50751002_39_dialog_content = "아니었으면 나 혼자 저 사람들을 상대하긴 힘들었을 거야.",
  ui_story_5075_50751002_40_dialog_content = "상대한다는 게 진짜로 싸우려던 건 아니겠지...",
  ui_story_5075_50751002_41_dialog_content = "그나저나 내일이면 춘삭절이잖아? 그럼 시간이 없어.",
  ui_story_5075_50751002_42_dialog_content = "다행히 지금 우린 꽤 많은 단서를 갖고 있어.",
  ui_story_5075_50751002_43_dialog_content = "이 일의 처음은 진예가 만든 봉인을 누군가 깨트린 데서 시작됐어.\n그래서 검은 교룡을 조종하던 바닷속 힘이 흘러나오기 시작했고.",
  ui_story_5075_50751002_44_dialog_content = "그 힘은 특별한 성질이 있지만, 본질적으로는 암귀의 힘이라고 할 수 있어.",
  ui_story_5075_50751002_45_dialog_content = "그 힘이 암귀를 해변으로 유인하는 바람에 린 가문은 출항할 수가 없어서 사업을 멈췄지.",
  ui_story_5075_50751002_46_dialog_content = "그래서 가주님은 어쩔 수 없이 전에 린 가문과 협력하던 수요령 우룡을 찾아가서,\n암귀가 모여드는 이유를 알아봐 달라고 부탁하신 거고.",
  ui_story_5075_50751002_47_dialog_content = "근데 조사하던 우룡이 검은 기운에 침식돼서, 지금은 린 가문에 대한 증오만 남아버렸어.",
  ui_story_5075_50751002_48_dialog_content = "그리고 그릇이 될 몸을 찾은 검은 기운은 더 강력해졌고,\n주변의 수요령한테도 영향을 주기 시작한 거야.",
  ui_story_5075_50751002_49_dialog_content = "심지어 호진성 안까지 퍼져버렸지.",
  ui_story_5075_50751002_50_dialog_content = "그럼 우린 어떻게든 우룡을 찾아서 그 검은 기운을 없애야 해.",
  ui_story_5075_50751002_51_dialog_content = "그리고 진예가 옛날에 했던 것처럼 검은 기운의 힘을 봉인하면 되는 거야.",
  ui_story_5075_50751002_52_dialog_content = "그럼 얼른 가야지!",
  ui_story_5075_50751002_53_dialog_content = "찍찍찍!",
  ui_story_5075_50751002_54_dialog_content = "수요의 불꽃!",
  ui_story_5075_50751002_55_dialog_content = "젠장! 성안에 검은 기운이 너무 많이 퍼졌어! 수요령들이 하나둘씩 영향을 받고 있어!",
  ui_story_5075_50751002_56_dialog_content = "나송, 넌 여기 남아 줘.",
  ui_story_5075_50751002_57_dialog_content = "수요령들은 네 도움이 필요해.",
  ui_story_5075_50751002_58_dialog_content = "알겠어. 그럼 그 전에──",
  ui_story_5075_50751002_59_dialog_content = "뭔데...?",
  ui_story_5075_50751002_60_dialog_content = "주먹인사를 하자.",
  ui_story_5075_50751002_61_dialog_content = "이걸로 우린 고난을 함께한 친구인 거야.",
  ui_story_5075_50751002_62_dialog_content = "돌아오면 내가 신선한 마름 열매를 대접할게.",
  ui_story_5075_50751002_63_dialog_content = "응!",
  ui_story_5075_50751002_64_dialog_content = "그럼 난 침식된 수요령들을 찾으러 갈 테니까, 두 사람도 힘내!",
  ui_story_5075_50751002_65_dialog_content = "그럼 나도 월백 씨한테... 어라?",
  ui_story_5075_50751002_66_dialog_content = "사절 나리, 드디어 찾았군요.",
  ui_story_5075_50751002_67_dialog_content = "참... 잘도 도망치시는군요.",
  ui_story_5075_50751002_68_dialog_content = "주사관님...? 왜, 왜 여기 계세요?",
  ui_story_5075_50751002_69_dialog_content = "지금 성안에는 요마가 활개 치고 있습니다. 저희가 응당 사절 나리의 안전을 지켜야지요.",
  ui_story_5075_50751002_70_dialog_content = "함께 영빈관으로 돌아가시지요.",
  ui_story_5075_50751002_71_dialog_content = "전 중요한 일이 있어서 못 가요.",
  ui_story_5075_50751002_72_dialog_content = "저흴 난처하게 만들지 마시지요. 사절 나리께서는 먼바다를 건너 제나라에 온 귀빈이십니다.",
  ui_story_5075_50751002_73_dialog_content = "혹여 사절 나리에게 무슨 일이 생겼다간 저희 목이 날아간단 말입니다. 부디 헤아려 주시지요.",
  ui_story_5075_50751002_74_dialog_content = "여봐라, 사절 나리를 영빈관으로 모셔라!",
  ui_story_5075_50751002_75_dialog_content = "자, 잠깐만요! 이거 놓...으읍!",
  ui_story_5075_50751002_76_dialog_content = "PlayerName, 다녀왔어.",
  ui_story_5075_50751002_77_dialog_content = "...PlayerName?",
  ui_story_5075_50751101_1_dialog_content = "「꽃이여, 흐드러지게 피어라!」",
  ui_story_5075_50751101_2_dialog_content = "으윽...",
  ui_story_5075_50751101_3_dialog_content = "자객의 행색을 하고서 끈질기게 공격하는 것에 비해, 살의는 담겨 있지 않구나.",
  ui_story_5075_50751101_4_dialog_content = "너희 목적은 나를 이곳에 잡아 두는 것이더냐?",
  ui_story_5075_50751101_5_dialog_content = "......",
  ui_story_5075_50751101_6_dialog_content = "조금 전 내가 급소를 공격하려는 시늉을 하였을 때도, 너희는 반격하려 들지 않았지.",
  ui_story_5075_50751101_7_dialog_content = "지금까지 너희는 몇 명이고 상처를 입었건만, 나는 털끝 하나 다치지 않았다.",
  ui_story_5075_50751101_8_dialog_content = "후후, 내 이제서야 PlayerName 공자가 했던 말이 이해가 되는지고.",
  ui_story_5075_50751101_9_dialog_content = "이런 상황에서 이상하리만치 신중히 다뤄지는 것은 기묘한 일이지.",
  ui_story_5075_50751101_10_dialog_content = "허나 세상의 기묘한 일이란 모두 그 이유를 가지고 있는 법.",
  ui_story_5075_50751101_11_dialog_content = "선기경의 서신, 구의 당부, 그리고 스승님의 가르침까지...",
  ui_story_5075_50751101_12_dialog_content = "이토록 단서가 많은데 진상을 알아채지 못한다면, 그야말로 아둔한 자가 아니겠느냐.",
  ui_story_5075_50751101_13_dialog_content = "너희는 업나라의 밀정들이렷다.",
  ui_story_5075_50751101_14_dialog_content = "!",
  ui_story_5075_50751101_15_dialog_content = "전하께서는 총명하고 지혜로우시니 역시 간파하셨군요.\n그렇다면 소인들이 전하를 해치지 않으리란 것도 확실히 아시겠지요.",
  ui_story_5075_50751101_16_dialog_content = "지금 호진성은 옥석을 가릴 수 없는 판국입니다. 부디 궁으로 돌아가 잠시 피해 주십시오.",
  ui_story_5075_50751101_17_dialog_content = "내 지금 출궁한다면 너희 계획에 방해가 되는 모양이로구나.",
  ui_story_5075_50751101_18_dialog_content = "업과 제 두 나라가 갖은 수단과 방법으로 싸우는 것도 예삿일에 지나지 않습니다.",
  ui_story_5075_50751101_19_dialog_content = "전하께선 마음이 여리시고, <color=#FFB400>저희 대인</color>께서는 전하를 곤란하게 만들길 원치 않으십니다.\n그러니 돌아가 주시지요.",
  ui_story_5075_50751101_20_dialog_content = "...<color=#FFB400>대인</color>이라.",
  ui_story_5075_50751101_21_dialog_content = "전하께서 충언을 따르지 않으신다면 소인들도 무례를 범하는 수밖에 없습니다.",
  ui_story_5075_50751101_22_dialog_content = "모셔라!",
  ui_story_5075_50751101_23_dialog_content = "「바람이여...」",
  ui_story_5075_50751101_24_dialog_content = "<color=#e8d9bb>스윽──</color>",
  ui_story_5075_50751101_25_dialog_content = "전하, 다치신 곳은 없으십니까.",
  ui_story_5075_50751101_26_dialog_content = "구? 녀석들 때문에 쉬이 오진 못할 줄 알았거늘.",
  ui_story_5075_50751101_27_dialog_content = "제 사명은 전하를 지키는 것입니다.",
  ui_story_5075_50751101_28_dialog_content = "전하가 저를 필요로 하시는 한, 이 구는 어디에 있건 전하의 곁으로 돌아올 것입니다.",
  ui_story_5075_50751101_29_dialog_content = "<color=#e8d9bb>그 순간, 쓰러진 자의 손이 구의 발목을 움켜쥐었다.</color>",
  ui_story_5075_50751101_30_dialog_content = "상...인... 님... 이러시면... 안...",
  ui_story_5075_50751101_31_dialog_content = "<color=#e8d9bb>스윽──</color>",
  ui_story_5075_50751101_32_dialog_content = "아무래도 앞으로 너와 해야 할 이야기가 많을 성싶구나.",
  ui_story_5075_50751101_33_dialog_content = "허나 지금은 촌각을 다투는 일이 있다.\n우선 나와 함께 PlayerName 공자를 찾자꾸나.",
  ui_story_5075_50751101_34_dialog_content = "전하, PlayerName 님이 어디 계시는지 아십니까?",
  ui_story_5075_50751101_35_dialog_content = "나 역시 서둘러 나온 터라 아직은 모르겠구나...",
  ui_story_5075_50751101_36_dialog_content = "앞날의 풍수, 건곤과 음양... 답을 원하신다면 점을 한 번 쳐 보시는 것은 어떠신지요?",
  ui_story_5075_50751101_37_dialog_content = "...이천간.",
  ui_story_5075_50751101_38_dialog_content = "계속 거기서 지켜보고 있던 것이냐?",
  ui_story_5075_50751101_39_dialog_content = "무슨 말씀이십니까? 소생은 방금 막 설탕 인형을 다 판 참이었는데, 불현듯 느낌이 딱 오더군요.",
  ui_story_5075_50751101_40_dialog_content = "이쪽 방향으로 가면 귀인을 만날 수 있다고 말입니다.\n하여 운에 맡겨 보자는 생각으로 와 본 것입니다.",
  ui_story_5075_50751101_41_dialog_content = "보아서는 아니 될 것은 아무것도 보지 못했습니다.",
  ui_story_5075_50751101_42_dialog_content = "되었다, 구야, 저자는 신경 쓰지 말자꾸나.",
  ui_story_5075_50751101_43_dialog_content = "휴, 손님 늘리기가 어찌 이리도 힘든 것인지.\n역시 뭐든지 믿어 주는 PlayerName 공이 좋군요.",
  ui_story_5075_50751101_44_dialog_content = "...PlayerName 공자를 봤다는 말이더냐?",
  ui_story_5075_50751101_45_dialog_content = "그렇다마다요. 게다가 매화 사탕도 하나 선물하고, 시도 한 수 지어 드렸지요.",
  ui_story_5075_50751101_46_dialog_content = "뭐, 소생에게 감사하실 필요는 없습니다.",
  ui_story_5075_50751101_47_dialog_content = "내 어찌 그대에게 감사해야 한다는 것인지 당최 이해가 되지 않는구나.",
  ui_story_5075_50751101_48_dialog_content = "허나 PlayerName 공자가 어디 있는지 알려 준다면, 내 감사해야 마땅하겠지.",
  ui_story_5075_50751101_49_dialog_content = "좋습니다. 저쪽에 있는 어림가에 계십니다만, 서두르시는 편이 좋을 것입니다.",
  ui_story_5075_50751101_50_dialog_content = "그렇지 않으면 금방 다른 이에게 뺏길 테니 말입니다.",
  ui_story_5075_50751101_51_dialog_content = "...구야, 가자꾸나.",
  ui_story_5075_50751101_52_dialog_content = "잠깐, 잠깐 기다려 주십시오.\n소생은 오늘 하루 종일 설탕 인형만 팔아서 손이 간지럽던 참입니다.",
  ui_story_5075_50751101_53_dialog_content = "개업 특별 할인인 셈 치고, 무료로 점을 한 번 봐 드리겠습니다.",
  ui_story_5075_50751101_54_dialog_content = "소생이 점을 쳐 보니, 전하께서는 지금부터 반드시 동남쪽으로 가셔야 귀인을 만나실 수 있습니다.",
  ui_story_5075_50751101_55_dialog_content = "어림가는 동남쪽에 있다. 조금 전에 그대의 입으로 가라고 하지 않았느냐.",
  ui_story_5075_50751101_56_dialog_content = "하지만 전하께서 지금부터 그쪽으로 가실지 말지는 모르는 일 아니겠습니까.",
  ui_story_5075_50751101_57_dialog_content = "내 그런 허튼소리를 들어 줄 시간은 없느니라.",
  ui_story_5075_50751101_58_dialog_content = "이게 바로 소생이 점친 「운명」입니다.",
  ui_story_5075_50751101_59_dialog_content = "전하, 소위 점이라는 것은 대부분 답을 얻고자 하늘과 땅, 신령에게 묻는 것이지요.",
  ui_story_5075_50751101_60_dialog_content = "하지만 가장 정확한 방법은 바로 「자신에게 묻는 것」입니다.",
  ui_story_5075_50751101_61_dialog_content = "스스로 생각하고, 바라고, 행하는 모든 것이 곧 「운명」이니 말입니다.",
  ui_story_5075_50751101_62_dialog_content = "아이고, 아차 했더니 또 전하의 시간을 빼앗아 버렸군요.\n이만 말을 줄이겠으니, 뜻대로 하십시오.",
  ui_story_5075_50751101_63_dialog_content = "......",
  ui_story_5075_50751101_64_dialog_content = "고맙다.",
  ui_story_5075_50751101_65_dialog_content = "별말씀을 다 하십니다. 하면 앞으로도 절 자주 찾아 주시면 됩니다.",
  ui_story_5075_50751101_66_dialog_content = "걱정 말거라, 그럴 일은 없을 테니.",
  ui_story_5075_50751102_1_dialog_content = "으음...",
  ui_story_5075_50751102_2_dialog_content = "여긴... 영빈관이 아니잖아.",
  ui_story_5075_50751102_3_dialog_content = "말끝마다 귀빈 귀빈 해놓고, 귀빈을 기절시키고 묶어서 끌고 가는 경우는 또 처음 보네.",
  ui_story_5075_50751102_4_dialog_content = "순순히 말을 들어 주신다면, 아무 일도 일어나지 않을 것입니다.",
  ui_story_5075_50751102_5_dialog_content = "이 영빈관 주사관이라는 신분은 참으로 편리하여, 아직 바꾸고 싶지 않으니 말입니다.",
  ui_story_5075_50751102_6_dialog_content = "허나 수완이 그리 좋으실 줄은 몰랐습니다. 린 가문까지 나서게 만들다니요.",
  ui_story_5075_50751102_7_dialog_content = "자칫하면 저희가 어렵사리 흔들어 놓은 국면을 당신이 해결해 버리게 생겼지 않습니까.",
  ui_story_5075_50751102_8_dialog_content = "그럼 이게 전부 당신들이 한 짓이야?",
  ui_story_5075_50751102_9_dialog_content = "진해의 봉인을 파괴하고, 성안에 검은 기운을 퍼트리고,\n사람들이랑 수요령 사이를 이간질하고...",
  ui_story_5075_50751102_10_dialog_content = "대체 뭘 꾸미고 있는 거야?",
  ui_story_5075_50751102_11_dialog_content = "그건 당신이 신경 쓸 바가 아닙니다.",
  ui_story_5075_50751102_12_dialog_content = "당신은 그저 이 은신처에서 조금 쉬고 있으며 됩니다.\n일이 일단락되고 나면 <color=#FFB400>저희</color>가 풀어드릴 테니 말입니다.",
  ui_story_5075_50751102_13_dialog_content = "<color=#FFB400>「저희」</color>라는 건, 제나라 조정의 한패 말하는 거지?",
  ui_story_5075_50751102_14_dialog_content = "국사가 알려 드린 모양이로군요.",
  ui_story_5075_50751102_15_dialog_content = "그 늙은이는 저희의 존재를 알아채지 못했을 때조차,\n이미 몇 번이고 저희의 행동을 방해해 왔습니다.",
  ui_story_5075_50751102_16_dialog_content = "허나 그 발악도 이제 얼마 가지 못할 것입니다.",
  ui_story_5075_50751102_17_dialog_content = "그것도 모두 당신 덕분이지요.",
  ui_story_5075_50751102_18_dialog_content = "뭐?",
  ui_story_5075_50751102_19_dialog_content = "당신이 궁에 온 날, 저는 당신과 국사가 작화군주와 이야기를 나누는 것을 들었습니다.",
  ui_story_5075_50751102_20_dialog_content = "왕궁이 비밀스럽고 안전하게 보일지라도, 그 안은 세상에서 가장 비밀이 없는 곳입니다.",
  ui_story_5075_50751102_21_dialog_content = "그 늙은이는 저희 사람이 점차 조정에 침투하고 있다는 것을 눈치챘겠지만,\n그게 누구인지는 알아내지 못했을 것입니다.",
  ui_story_5075_50751102_22_dialog_content = "하여 당신이라는 외부인을 이용하고자 한 것이겠지요.",
  ui_story_5075_50751102_23_dialog_content = "허나 덕분에 오히려 제게 기회가 생겼습니다.",
  ui_story_5075_50751102_24_dialog_content = "저는 그 늙은이가 그릇을 통해 당신에게 순검사의 영패를 전한 것을 알고 있습니다.",
  ui_story_5075_50751102_25_dialog_content = "만약 당신이 정말 순검사를 동원해 이 곤경을 해결했다면,\n그 늙은이의 행동은 임기응변이라 할 수 있겠지요.",
  ui_story_5075_50751102_26_dialog_content = "누군가 추궁한다 하더라도 변명의 여지가 있습니다.",
  ui_story_5075_50751102_27_dialog_content = "그러나 당신이 아무런 행동도 취하지 못한 상태에서, 누군가 영패의 존재를 발견해 버린다면...",
  ui_story_5075_50751102_28_dialog_content = "국사로서 그런 중요한 물건을 다른 나라의, 심지어 다른 대륙의 사람에게 건넸고...",
  ui_story_5075_50751102_29_dialog_content = "그 사람은 호진이 가장 혼란스러울 때 행방이 묘연해졌다고 생각해 보십시오.",
  ui_story_5075_50751102_30_dialog_content = "당신과 그 늙은이가 결탁하지 않았고, 제나라에 해를 끼칠 뜻이 없었다고 누가 믿겠습니까?",
  ui_story_5075_50751102_31_dialog_content = "그 늙은이를 반역죄로 다스리지 않는다면, 온 조정이 용납하지 않을 것입니다.",
  ui_story_5075_50751102_32_dialog_content = "자, 그럼 어디 봅시다. 영패를 어디에 숨겼습니까? 주머니? 옷소매?",
  ui_story_5075_50751102_33_dialog_content = "찾아봐야 소용없어. 내가 안 가지고 있으니까.",
  ui_story_5075_50751102_34_dialog_content = "난 국사님이 은밀하게 행동하라고 당부하셨을 때부터\n내 주변 사람들 중에 문제가 있을 거라 생각했어.",
  ui_story_5075_50751102_35_dialog_content = "그리고 그 그릇을 받고 나서 확신했어. 믿을 수 없는 사람은 영빈관에 있다는 걸 말이야.",
  ui_story_5075_50751102_36_dialog_content = "하지만 그게 사실이라면, 그릇 안에 든 물건이 당신들 눈을 피하는 건 힘들겠지.",
  ui_story_5075_50751102_37_dialog_content = "그래서 최대한 빨리 거기서 벗어나야겠다고 생각했어.",
  ui_story_5075_50751102_38_dialog_content = "어차피 순검사를 동원할 기회도 찾지 못했는데, 그게 무슨 의미가 있습니까?",
  ui_story_5075_50751102_39_dialog_content = "더군다나 당신은 이방인에 불과합니다. 이 용주에서 아는 이도 손에 꼽지 않습니까.",
  ui_story_5075_50751102_40_dialog_content = "아무리 작화군주와 안면이 있다 해도, 군주는 계속 궁 안에 있었고,\n밀정들에게 감시하라 명해 두었으니 당신이 군주와 말을 나눌 기회는 없었습니다.",
  ui_story_5075_50751102_41_dialog_content = "당신이 누구에게 영패를 넘겼는지는 조금만 조사해 봐도 알 수 있습니다.",
  ui_story_5075_50751102_42_dialog_content = "아, 바로 알겠군요. 린 가문이겠지요.",
  ui_story_5075_50751102_43_dialog_content = "린 가문의 가주는 이익만 있다면 얼마나 큰 위험이든 무릅쓰는 자이니 말입니다.",
  ui_story_5075_50751102_44_dialog_content = "하지만 순검사를 동원할 권한을 허물이 있는 일개 상인에게 맡기다니... 하하하!",
  ui_story_5075_50751102_45_dialog_content = "아무리 제나라가 상업을 중요시한다 해도, 이처럼 유례없이 터무니없는\n행동은 정죄를 피할 수 없을 것입니다.",
  ui_story_5075_50751102_46_dialog_content = "방금까진 당신이 그래도 비장의 수가 있겠거니 싶었는데,\n이제 보니 세상 물정 모르는 어린아이에 불과했군요.",
  ui_story_5075_50751102_47_dialog_content = "저는 부하들의 상황을 살피러 가야 하니, 이만 실례하도록 하지요.",
  ui_story_5075_50751102_48_dialog_content = "누가 린 가문에 영패를 건넸대?",
  ui_story_5075_50751102_49_dialog_content = "린 가문이 아니라도, 그래 봤자 함께 어울려 다니던 두 사람 중 하나겠지요.",
  ui_story_5075_50751102_50_dialog_content = "평민이나, 상인이나 별반 다를 게...",
  ui_story_5075_50751102_51_dialog_content = "평민이 아냐.",
  ui_story_5075_50751102_52_dialog_content = "<size=45><color=#FFB400>작화군주</color>거든.</size>",
  ui_story_5075_50751102_53_dialog_content = "제 말을 제대로 안 들은 모양이군요. 작화군주의 곁에 감시를 붙여 둔 이상, 절대로...",
  ui_story_5075_50751102_54_dialog_content = "<size=45>올 거야.</size>",
  ui_story_5075_50751102_55_dialog_content = "영패는 순검사를 상징하고, 주소는 린 가문을 가리켰어.\n그리고 나한테 가르침을 준 건 국사님이었지.",
  ui_story_5075_50751102_56_dialog_content = "그리고 이것들은 모두 해당화에 담겨 있었어.",
  ui_story_5075_50751102_57_dialog_content = "이 모든 걸 제대로 다룰 수 있는 건 단당 씨뿐이야!",
  ui_story_5075_50751102_58_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5075_50751102_59_dialog_content = "조금이라도 움직여 보아라. 네 머리와 작별 인사를 하게 될 테니.",
  ui_story_5075_50751102_60_dialog_content = "PlayerName 공자! 괜찮느냐?",
  ui_story_5075_50751102_61_dialog_content = "단당 씨! 구 씨!",
  ui_story_5075_50751102_62_dialog_content = "당신들이... 어떻게... 크윽!",
  ui_story_5075_50751102_63_dialog_content = "<color=#e8d9bb>단당은 영빈관 주사관의 얼굴을 붙잡고 힘껏 잡아당겼다.</color>",
  ui_story_5075_50751102_64_dialog_content = "<color=#e8d9bb>그러자 얇은 가면이 바닥으로 떨어지며, 그 아래의 낯선 얼굴이 드러났다.</color>",
  ui_story_5075_50751102_65_dialog_content = "역시 영빈관 주사관이 아니었구나. 그저 그 신분을 빌렸을 뿐인 게지.",
  ui_story_5075_50751102_66_dialog_content = "...저를 붙잡았다 한들 이 일에 아무런 영향도 주지 못할 것입니다.",
  ui_story_5075_50751102_67_dialog_content = "저희의 주인께서는 더없이 지혜로운 분이시고, 「<color=#FFB400>천명을 받은 자</color>」들은 어디에나 있습니다.",
  ui_story_5075_50751102_68_dialog_content = "계획은 이미 막바지에 이르렀습니다.\n해저의 봉인은 깨졌고, 깊은 잠에 빠져 있던 악몽은 이미 깨어났으니 말입니다!",
  ui_story_5075_50751102_69_dialog_content = "호진의 질서가 붕괴하면 저희는 틈을 노려 힘 하나 들이지 않고\n제나라를 수중에 넣을 수 있을 것입니다.",
  ui_story_5075_50751102_70_dialog_content = "신령께서 굽어살피신다면 또 모를까, 당신들은 이제... 크헉!",
  ui_story_5075_50751102_71_dialog_content = "누가 이 몸을 불렀느냐?",
  ui_story_5075_50751102_72_dialog_content = "윽...! 끄억!",
  ui_story_5075_50751102_73_dialog_content = "진예? 네가 왜 여기 있어?",
  ui_story_5075_50751102_74_dialog_content = "이 몸이 봉인을 파괴한 자를 찾겠다 하지 않았느냐? 일전에는 그자를 쫓다 놓치고 말았지.",
  ui_story_5075_50751102_75_dialog_content = "그래서 이 몸은 차라리 그자의 냄새를 추적하여,\n그자가 접촉한 상대와 갔던 장소를 모조리 찾아보았느니라.",
  ui_story_5075_50751102_76_dialog_content = "이곳 역시 그리하여 오게 된 게야~",
  ui_story_5075_50751102_77_dialog_content = "으윽! 으억──!",
  ui_story_5075_50751102_78_dialog_content = "게다가 도중에 설탕 인형 장수도 만났느니라.",
  ui_story_5075_50751102_79_dialog_content = "매화 사탕 만드는 설탕 인형 장수 말이야?!",
  ui_story_5075_50751102_80_dialog_content = "그렇지! 아주 통이 큰 사람이더구나. 이 몸에게 커다란 설탕 인형을 바쳤다.",
  ui_story_5075_50751102_81_dialog_content = "허나 소원은 하나만 빌더구나. 이 몸이 지나는 곳에 매화 가지를 하나 꽂아 달라고 말이다.",
  ui_story_5075_50751102_82_dialog_content = "그래서 그렇게 했어?",
  ui_story_5075_50751102_83_dialog_content = "물론이지. 공물을 받은 이상 이 몸이 한 말을 지켜야지.",
  ui_story_5075_50751102_84_dialog_content = "이 건물의 밖에도 꽂아 두었느니라.",
  ui_story_5075_50751102_85_dialog_content = "다행이야...\n단당 씨!",
  ui_story_5075_50751102_86_dialog_content = "여기 있다.",
  ui_story_5075_50751102_87_dialog_content = "린 가문 가주에게서 영패를 받았고, 린 가문 호위들의 엄호도 받았다.",
  ui_story_5075_50751102_88_dialog_content = "이제 호위들은 모두 종 대인의 지휘에 따라, 호진성 안의 요마와\n광기에 빠진 수요령을 제압하고 있다.",
  ui_story_5075_50751102_89_dialog_content = "순검사에서도 그 「천명을 받은 자」들을 처리하고 나면 지원에 나설 것이다.",
  ui_story_5075_50751102_90_dialog_content = "내가 마음에 둔 꽃을 쭉 기억하고 있어 주어 고맙구나...",
  ui_story_5075_50751102_91_dialog_content = "하하, 성공해서 다행이에요! 바깥 상황은 어때요?",
  ui_story_5075_50751102_92_dialog_content = "성안은 잠시 버틸 수 있겠으나, 성밖은 월백에게 맡기는 수밖에 없겠구나.",
  ui_story_5075_50751102_93_dialog_content = "성 밖이라면... 주사관이 그랬어요. 자기들 계획은 이제 막바지라고요.",
  ui_story_5075_50751102_94_dialog_content = "어쩌면 우룡이 이미 검은 기운이랑 완전히 융합했을 가능성도 있어요.",
  ui_story_5075_50751102_95_dialog_content = "그러니까 최대한 빨리 우룡이랑 이야기를 해 봐야 해요!",
  ui_story_5075_50751102_96_dialog_content = "그럼 이쪽으로 와.",
  ui_story_5075_50751102_97_dialog_content = "작은 배를 하나 준비해 뒀어. 수로를 통해 바로 해안으로 갈 수 있을 거야.",
  ui_story_5075_50751102_98_dialog_content = "성안은 단당 씨한테 맡길게요. 저랑 월백 씨는 가서 우룡을... 어라?",
  ui_story_5075_50751102_99_dialog_content = "용녀...님?",
  ui_story_5075_50751102_100_dialog_content = "잘은 모르겠지만, 봉인을 파괴한 녀석은 누군가 이 몸을 대신해 벌을 준 것이렷다?",
  ui_story_5075_50751102_101_dialog_content = "하면 이 몸도 그대들과 함께 바닷가로 가야겠구나~",
  ui_story_5075_50751102_102_dialog_content = "네 힘만으로는 녀석과 우룡이 만들어 내는 신기루를 당해내지 못할 게야.",
  ui_story_5075_50751201_1_dialog_content = "<color=#e8d9bb>철썩──</color>",
  ui_story_5075_50751201_2_dialog_content = "하암... 미안해요, 잠들어 버렸었나 봐요. 도착했나요? 월...",
  ui_story_5075_50751201_3_dialog_content = "어라...?",
  ui_story_5075_50751201_4_dialog_content = "(방금 내가 누구 이름을 부르려고 했더라?)",
  ui_story_5075_50751201_5_dialog_content = "(그러고 보니까 내가 왜 배에 타고 있는 거지?)",
  ui_story_5075_50751201_6_dialog_content = "(으... 머리가 아프네.)",
  ui_story_5075_50751201_7_dialog_content = "어이, 여기서 또 뭐 하고 있어? 빨리 내려가서 짐이나 마저 옮겨. 이제 곧 출항할 거라고.",
  ui_story_5075_50751201_8_dialog_content = "지, 짐을 옮기라고요? 제가요?",
  ui_story_5075_50751201_9_dialog_content = "여기 너 말고 다른 사람도 있나?",
  ui_story_5075_50751201_10_dialog_content = "너 가족이 아파서 약값을 벌어야 한다며? 무슨 스카이인가 뭔가 하는 이상한 이름이었나?\n아무튼 그래서 급하게 일을 구해놓고 뭘 빈둥대고 있어?",
  ui_story_5075_50751201_11_dialog_content = "하... 다만 이번 원양 항해에서 우리가 무사히 돌아갈 수 있을지 모르겠지만 말이야.",
  ui_story_5075_50751201_12_dialog_content = "뭐, 린 가문 상회가 규모는 작아도 이번 출항 품삯은 제일 두둑하게 쳐 줬어.\n게다가 절반은 선금으로 미리 받았다고.",
  ui_story_5075_50751201_13_dialog_content = "이 돈만 있으면, 우리 마누라랑 애들도 잘 챙겨 먹일 수 있겠지.",
  ui_story_5075_50751201_14_dialog_content = "네 가족 약값도 아마 당분간 걱정할 필요 없을 거다.",
  ui_story_5075_50751201_15_dialog_content = "(뭔가 이상한 느낌이야... 그러면서 맞는 것 같기도 하고...)",
  ui_story_5075_50751201_16_dialog_content = "(윽... 머리가 또 아파.)",
  ui_story_5075_50751201_17_dialog_content = "(일단 물건부터 옮기자.)",
  ui_story_5075_50751201_18_dialog_content = "<color=#e8d9bb>철썩──</color>",
  ui_story_5075_50751201_19_dialog_content = "어라? 어떻게 된 거죠?",
  ui_story_5075_50751201_20_dialog_content = "왜 갑자기 주변에 안개가 낀 건데요?",
  ui_story_5075_50751201_21_dialog_content = "이 친구 배가 고파서 까마귀 고기라도 주워 먹었나?\n배가 안개 속에 갇혀서 맴돌기만 한 게 벌써 보름째라고.",
  ui_story_5075_50751201_22_dialog_content = "이러다간 우리 전부 여기서 이렇게 끝장이야...",
  ui_story_5075_50751201_23_dialog_content = "마누라랑 애들이 날 기다리고 있단 말이야... 죽고 싶지 않다고...",
  ui_story_5075_50751201_24_dialog_content = "<color=#e8d9bb>남자가 한숨을 쉬자, 주변에서 탄식과 흐느낌이 터져 나왔다.</color>",
  ui_story_5075_50751201_25_dialog_content = "<color=#e8d9bb>눈앞에 보이는 것은 선원과 상인 모두 갑판에 늘어져,\n고단함이 담긴 절망의 한숨을 내쉬고 있는 모습뿐이었다.</color>",
  ui_story_5075_50751201_26_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5075_50751201_27_dialog_content = "(배에 뭐가 부딪혔나?!)",
  ui_story_5075_50751201_28_dialog_content = "다...다들 빨리 좀 봐!",
  ui_story_5075_50751201_29_dialog_content = "저 물고기들이 아래에서 배를 밀어주고 있어!",
  ui_story_5075_50751201_30_dialog_content = "저건 교룡어야! 좋은 징조라고! 지금은 마침 겨울이고, 교룡어들도 용주로 돌아가고 있는 거야!",
  ui_story_5075_50751201_31_dialog_content = "교룡어들만 따라가면 우리도 살 수 있어!",
  ui_story_5075_50751201_32_dialog_content = "다들 봤지?! 신령님이 우릴 지켜 주신 거라고!",
  ui_story_5075_50751201_33_dialog_content = "(...내 착각인가? 맨 앞에 있는 저 교룡어... 왠지 어디서 많이 본 느낌인데?)",
  ui_story_5075_50751201_34_dialog_content = "<color=#e8d9bb>철썩──</color>",
  ui_story_5075_50751201_35_dialog_content = "난... 교룡어야.",
  ui_story_5075_50751201_36_dialog_content = "바닷속을 헤엄치며 먹이를 잡아 배를 채우고, 가끔은 광력술를 익힌 동족에게 가르침을 받아.",
  ui_story_5075_50751201_37_dialog_content = "해마다 겨울이 되면, 우린 무리를 지어 우리가 태어난 곳... 용주로 돌아가.",
  ui_story_5075_50751201_38_dialog_content = "그날, 우리는 바다에서 길을 잃은 배를 하나 봤어.",
  ui_story_5075_50751201_39_dialog_content = "그 배는 우리와 함께 용주로 돌아갔고, 우리 대장과 합의했지.",
  ui_story_5075_50751201_40_dialog_content = "그때부터 우리는 매년 귀향 때마다 그 배와 함께 다니게 됐어.",
  ui_story_5075_50751201_41_dialog_content = "배가 무사히 돌아올 수 있게 이끌어 주면, 저들은 우리에게 음식을 줬어.",
  ui_story_5075_50751201_42_dialog_content = "이건 좋은 관계니까, 우린 기뻐해야 해.",
  ui_story_5075_50751201_43_dialog_content = "<color=#e8d9bb>철썩──</color>",
  ui_story_5075_50751201_44_dialog_content = "총관님, 총관님? 또 멍하니 교룡어를 보고 계셨군요.",
  ui_story_5075_50751201_45_dialog_content = "아무리 봐도, 교룡어들 중에 한 마리가... 유난히 낯이 익습니다.",
  ui_story_5075_50751201_46_dialog_content = "거 다 비슷하게 생긴 놈들이 뭘 그리 볼 게 있다고 그러십니까.\n차라리 와서 이거나 좀 보시지요.",
  ui_story_5075_50751201_47_dialog_content = "이번 항해의 수익금 중 총관님 몫입니다.",
  ui_story_5075_50751201_48_dialog_content = "...이거 너무 많은 거 아닙니까?!",
  ui_story_5075_50751201_49_dialog_content = "린 가문이 원양 항로를 개척한 이래로 수익은 점점 늘어 왔습니다. 이 정도면 푼돈이지요.",
  ui_story_5075_50751201_50_dialog_content = "혹시 돈을 더 벌고 싶진 않으십니까?",
  ui_story_5075_50751201_51_dialog_content = "이, 이것보다 더 말입니까...?",
  ui_story_5075_50751201_52_dialog_content = "오기 전에 다른 사람들과도 말을 해 봤습니다.\n린 가문 상회의 규모는 지금도 나날이 커지고 있지 않습니까.",
  ui_story_5075_50751201_53_dialog_content = "아스트라 등지의 무역 수요도 점점 늘고 있으니, 일 년에 한 번 항해로는 턱도 없지요!",
  ui_story_5075_50751201_54_dialog_content = "그러니 우리가 뜻을 모아 가주님께 항해 횟수를 한 번 더 늘리자고 말씀드리는 게 어떻겠습니까?",
  ui_story_5075_50751201_55_dialog_content = "한 해에 딱 두 번이면 됩니다. 생각해 보십시오.",
  ui_story_5075_50751201_56_dialog_content = "하지만 교룡어의 습성은 해마다 겨울에만 용주에 돌아오는 것이 아니었습니까?",
  ui_story_5075_50751201_57_dialog_content = "어차피 평소에도 바닷속을 내키는 대로 싸다니는 놈들인데,\n용주에 한 번 더 오는 게 뭐가 대수입니까?",
  ui_story_5075_50751201_58_dialog_content = "우린 돈을 벌고, 놈들 줄 먹이도 더 많이 살 수 있으니 피차 좋지 않습니까?",
  ui_story_5075_50751201_59_dialog_content = "교룡어들이 신경 쓰는 건 먹이가 아닐 텐데요.",
  ui_story_5075_50751201_60_dialog_content = "쳇, 이거 뭐 말이 통해야 말이지. 됐습니다.\n다른 사람들은 다 좋다고 하니, 당신 한 명 빠진다고 뭐 일이 틀어지겠습니까?",
  ui_story_5075_50751201_61_dialog_content = "잠깐만요, 전...",
  ui_story_5075_50751201_62_dialog_content = "<color=#e8d9bb>철썩──</color>",
  ui_story_5075_50751201_63_dialog_content = "대장은 이제부터 여름에도 용주에 돌아가야 한다고 했어.",
  ui_story_5075_50751201_64_dialog_content = "여름의 바다, 너무 더워, 그래서 싫어.",
  ui_story_5075_50751201_65_dialog_content = "하지만 배의 친구들은 도움이 필요해.",
  ui_story_5075_50751201_66_dialog_content = "그럼 괜찮아.",
  ui_story_5075_50751201_67_dialog_content = "하지만 멀리 헤엄치는 건, 조금 힘들어.",
  ui_story_5075_50751201_68_dialog_content = "<color=#e8d9bb>철썩──</color>",
  ui_story_5075_50751201_69_dialog_content = "오늘은 내 발표할 일이 하나 있어 모두를 오라 하였다.",
  ui_story_5075_50751201_70_dialog_content = "이번에 우리 린 가문은 앙경에서 들어온 주문을 받게 되었다.\n앙경의 요구에 따라 올해는 임시로 원항 횟수를 한 차례 늘리고자 한다.",
  ui_story_5075_50751201_71_dialog_content = "잠깐만요, 가주님. 애초에 교룡어들과 약속한 건 매년 한 번만 도움을 받는 것이었습니다.",
  ui_story_5075_50751201_72_dialog_content = "여름철에 용주로 돌아오는 것은 저들의 습성에 반하는 일이고, 게다가...",
  ui_story_5075_50751201_73_dialog_content = "조나라 황실과의 거래는 수많은 상회가 꿈에서도 바라 마지않는 일이다.",
  ui_story_5075_50751201_74_dialog_content = "이 거래가 향후 우리 린 가문에 얼마나 큰 이익을 가져올지 알고 있느냐?",
  ui_story_5075_50751201_75_dialog_content = "교룡어들이 불만을 품을 처사라는 것은 알고 있다.\n그러니 내 직접 그 수요령을 찾아가 사과하겠다.",
  ui_story_5075_50751201_76_dialog_content = "하면 이렇게 정한 것으로 하지.",
  ui_story_5075_50751201_77_dialog_content = "<color=#e8d9bb>철썩──</color>",
  ui_story_5075_50751201_78_dialog_content = "올해는 세 번 돌아가야 해.",
  ui_story_5075_50751201_79_dialog_content = "대장이 이번만이라고 했어. 배에 있는 친구가 곤란해졌대.",
  ui_story_5075_50751201_80_dialog_content = "하지만 두 번째 해에도 세 번이었고, 세 번째 해에도 세 번이었어.",
  ui_story_5075_50751201_81_dialog_content = "벌써 사라진 동족도 있어.",
  ui_story_5075_50751201_82_dialog_content = "그리고 대장도 때 이른 죽음을 맞이했어.",
  ui_story_5075_50751201_83_dialog_content = "이제부터는 내가 새 대장이야.",
  ui_story_5075_50751201_84_dialog_content = "배에 있던 친구가 왔어. 날 뭍으로 데려가더니, 한 나무 방에 있는 커다란 어항에 날 넣었어.",
  ui_story_5075_50751201_85_dialog_content = "어항이 너무 작아서, 헤엄치기 힘들어.",
  ui_story_5075_50751201_86_dialog_content = "너무 괴로워.",
  ui_story_5075_50751201_87_dialog_content = "네 번째 해에도, 또 세 번 돌아갔어.",
  ui_story_5075_50751201_88_dialog_content = "하지만 배가 바다 위를 지날 때도, 저들은 내가 바다에서 헤엄치게 해 주지 않았어.",
  ui_story_5075_50751201_89_dialog_content = "저들은 어항을 배로 옮기더니, 매일 나한테 먹을 걸 잔뜩 줬어.\n동족들에게 신호만 보내면 된다면서.",
  ui_story_5075_50751201_90_dialog_content = "저들은 이게 날 모시는 거라고 했어. 이게 수요령을 향한 예의라고.",
  ui_story_5075_50751201_91_dialog_content = "둔갑술을 익힌 것인가.",
  ui_story_5075_50751201_92_dialog_content = "......",
  ui_story_5075_50751201_93_dialog_content = "이제 막 둔갑술을 익혔으니, 말은 아직 못 하겠지.",
  ui_story_5075_50751201_94_dialog_content = "말을 배워 보겠느냐. 내가 가르쳐 주마. 너희를 향한 속죄인 셈 치거라...",
  ui_story_5075_50751201_95_dialog_content = "아니, 되었다. 네게 이런 말을 한들 알아들을 리가 있겠느냐.",
  ui_story_5075_50751201_96_dialog_content = "게다가 내 너희에게 범한 죄업은 능청스레 이런 사소한 일 한둘로\n씻을 수 있는 것도 아니지 않은가.",
  ui_story_5075_50751201_97_dialog_content = "(난 알아. 이 사람이 배의 대장이야.)",
  ui_story_5075_50751201_98_dialog_content = "(이 사람은 나한테 말을 가르쳐 주고, 글자를 가르쳐 줬어.)",
  ui_story_5075_50751201_99_dialog_content = "(그치만 난 알아. 이 사람, 정말 나쁜 사람이야.)",
  ui_story_5075_50751201_100_dialog_content = "<color=#e8d9bb>철썩──</color>",
  ui_story_5075_50751201_101_dialog_content = "네 번이라고요?!",
  ui_story_5075_50751201_102_dialog_content = "최근 제씨 쪽에서 린 가문의 황실 납품 상회 자리를 호시탐탐 노리고 있다.",
  ui_story_5075_50751201_103_dialog_content = "우리가 더 혁혁한 성과를 내지 못한다면, 이 자리를 보전하기 어려울 터.",
  ui_story_5075_50751201_104_dialog_content = "린 가문이 이어 온 백 년의 영광을 우리 손으로 헐어버릴 순 없다.",
  ui_story_5075_50751201_105_dialog_content = "몇 년 전부터 교룡어들의 사망률이 이상할 정도로 증가했습니다!\n정말 모른 체하실 작정이십니까?!",
  ui_story_5075_50751201_106_dialog_content = "그것이 뭐가 어떻다는 것이냐.",
  ui_story_5075_50751201_107_dialog_content = "뭐가 어떻냐니... 대체 뭘 어쩌시려는 겁니까?!",
  ui_story_5075_50751201_108_dialog_content = "상품이 부족하다고 일 년에 두 번으로 늘리고, 또 급한 주문이 들어왔다고\n일 년에 세 번으로 늘리지 않았습니까!",
  ui_story_5075_50751201_109_dialog_content = "그래 놓고 이젠 교룡어들에게 린 가문의 지위 보전에 대한 책임까지 지라는 말씀이십니까?!",
  ui_story_5075_50751201_110_dialog_content = "한때 교룡어들은 곤경에 처한 우릴 구해줬는데,\n지금 린 가문은 오히려 은혜를 원수로 갚고 있지 않습니까!",
  ui_story_5075_50751201_111_dialog_content = "자신의 욕심을 허울 좋은 말로 포장하지 마십시오!",
  ui_story_5075_50751201_112_dialog_content = "...PlayerName...",
  ui_story_5075_50751201_113_dialog_content = "(으윽... 방금 그건 뭐지...?)",
  ui_story_5075_50751201_114_dialog_content = "자네는 린 가문에서 주는 급료를 받으면서도, 도리어 교룡어들에게 더 충직하군.",
  ui_story_5075_50751201_115_dialog_content = "린 가문은 자네 같은 사람을 쓸 수 없다. 떠나라.",
  ui_story_5075_50751201_116_dialog_content = "나는 네 번째 출항을 논의하러 가야 하니, 이번 달 급료는 집사에게 직접 찾아가 받도록 해라.",
  ui_story_5075_50751201_117_dialog_content = "...정말 이러셔야겠습니까?",
  ui_story_5075_50751201_118_dialog_content = "뭘 하려는 게냐?",
  ui_story_5075_50751201_119_dialog_content = "전 교룡어들의 대장을 바다로 돌려보내야겠습니다.",
  ui_story_5075_50751201_120_dialog_content = "(찾았다! 바로 이 어항이야!)",
  ui_story_5075_50751201_121_dialog_content = "미안해. 잠깐 물 밖에 나와 있어야 할 것 같아. 그래도 바닷가에 도착하면 금방...",
  ui_story_5075_50751201_122_dialog_content = "저자를 막아라!",
  ui_story_5075_50751201_123_dialog_content = "(언제 저렇게 잔뜩 몰려왔어?! 빠져나갈 방법을 찾아야 하는데...)",
  ui_story_5075_50751201_124_dialog_content = "(강제 감응!)",
  ui_story_5075_50751201_125_dialog_content = "으어억!",
  ui_story_5075_50751201_126_dialog_content = "...어라? 감응이...",
  ui_story_5075_50751201_127_dialog_content = "PlayerName!",
  ui_story_5075_50751201_128_dialog_content = "진...예...?",
  ui_story_5075_50751201_129_dialog_content = "이제서야 이 몸을 눈치챈 게냐.",
  ui_story_5075_50751201_130_dialog_content = "배가 해안에 들어서고 얼마 지나지 않아 그대와 월백이 까무룩 잠이 들더니,\n아무리 찔러대도 깨어날 기미가 도통 보이지 않더구나.",
  ui_story_5075_50751201_131_dialog_content = "이 몸 혼자서는 무료하니, 둘 다 어서 깨어나란 말이다.",
  ui_story_5075_50751201_132_dialog_content = "기억났어! 해안에 들어선 순간, 거대한 검은 기운이 우릴 덮쳤어...",
  ui_story_5075_50751201_133_dialog_content = "그럼 그 힘이 우릴 이 꿈... 아니, 환상으로 빠트린 거야?",
  ui_story_5075_50751201_134_dialog_content = "음... 아무렴 어떻겠느냐.",
  ui_story_5075_50751201_135_dialog_content = "뭐 그런 대답이 다 있어?!",
  ui_story_5075_50751201_136_dialog_content = "검은 기운이 이것과 무슨 관계가 있는지는 중요치 않느니라.",
  ui_story_5075_50751201_137_dialog_content = "그보다는 어서 가서 월백을 찾는 게 좋겠구나.",
  ui_story_5075_50751201_138_dialog_content = "지금 무척 괴로워 보이니 말이다.",
  ui_story_5075_50751201_139_dialog_content = "검은 기운에 침식당하고 있는 거야...? 그럼 진예 네가 좀...",
  ui_story_5075_50751201_140_dialog_content = "가능은 하지. 허나 이번에 이 몸이 도움을 주는 건 여기까지다.",
  ui_story_5075_50751201_141_dialog_content = "뭐라고? 왜?",
  ui_story_5075_50751201_142_dialog_content = "매사 신의 도움을 바라는 것은 좋은 습관이 아니니라.",
  ui_story_5075_50751201_143_dialog_content = "자신의 일은 자신이 해결해야 마땅하지.",
  ui_story_5075_50751201_144_dialog_content = "...알겠어.",
  ui_story_5075_50751201_145_option_content = "[감응한다]",
  ui_story_5075_50751201_146_dialog_content = "월백 씨! 대체 어디 있어요...?",
  ui_story_5075_50751201_147_dialog_content = "PlayerName.",
  ui_story_5075_50751201_148_dialog_content = "이 교룡어가... 월백 씨?!",
  ui_story_5075_50751201_149_dialog_content = "멈춰라!",
  ui_story_5075_50751201_150_dialog_content = "또 왔어?!",
  ui_story_5075_50751201_151_dialog_content = "...일단 바닷가로 도망치자!",
  ui_story_5075_50751201_152_dialog_content = "휴, 후우... 겨우 도착했네.",
  ui_story_5075_50751201_153_dialog_content = "환상 속인데도 왜 이렇게 힘든 거냐고...",
  ui_story_5075_50751201_154_dialog_content = "월백 씨, 일단 물 안으로 들어가요. 그리고...",
  ui_story_5075_50751201_155_dialog_content = "월백 씨?!",
  ui_story_5075_50751201_156_dialog_content = "(물에 들어가자마자 없어져 버렸잖아...?!)",
  ui_story_5075_50751201_157_dialog_content = "(물밑이... 온통 검은 기운이야!)",
  ui_story_5075_50751201_158_dialog_content = "......",
  ui_story_5075_50751201_159_dialog_content = "(힘들어, 대장, 배고파, 대장, 괴로워, 대장.)",
  ui_story_5075_50751201_160_dialog_content = "(미워, 돌아갈래, 대장, 대장, 대장, 구해줘, 살려줘.)",
  ui_story_5075_50751201_161_dialog_content = "(우릴 구해줘, 살려줘... 대장.)",
  ui_story_5075_50751201_162_dialog_content = "(동족들이 보낸 신호야.)",
  ui_story_5075_50751201_163_dialog_content = "(제각각에, 뒤죽박죽이지만, 전부 녀석들... 교룡어들의 마음의 소리야.)",
  ui_story_5075_50751201_164_dialog_content = "저, 소리들.",
  ui_story_5075_50751201_165_dialog_content = "매일, 매일, 들려.",
  ui_story_5075_50751201_166_dialog_content = "언제나, 계속, 들려.",
  ui_story_5075_50751201_167_dialog_content = "다들, 증오해.",
  ui_story_5075_50751201_168_dialog_content = "우룡.",
  ui_story_5075_50751201_169_dialog_content = "그랬구나.",
  ui_story_5075_50751201_170_dialog_content = "내가 방금까지 겪은 일들, 네 기억인 거지?",
  ui_story_5075_50751201_171_dialog_content = "린, 가문.",
  ui_story_5075_50751201_172_dialog_content = "배, 신, 자.",
  ui_story_5075_50751201_173_dialog_content = "인간은, 약속을, 지키지, 않아.",
  ui_story_5075_50751201_174_dialog_content = "너도, 물고기, 잖아.",
  ui_story_5075_50751201_175_dialog_content = "인간을, 증오해야, 마땅해!",
  ui_story_5075_50751201_176_dialog_content = "월백 씨! 제 목소리 들려요?!",
  ui_story_5075_50751201_177_dialog_content = "지금 바로 찾으러 갈게요!",
  ui_story_5075_50751201_178_dialog_content = "그럴 필요 없어, PlayerName.",
  ui_story_5075_50751201_179_dialog_content = "네?",
  ui_story_5075_50751201_180_dialog_content = "린 가문이 우룡에게 면목이 없는 짓을 한 건 사실이야.",
  ui_story_5075_50751201_181_dialog_content = "그리고 난 지금 린 가문을 대표해 여기 온 거고, 우룡은 내게 책임을 물을 자격이 있어.",
  ui_story_5075_50751201_182_dialog_content = "......",
  ui_story_5075_50751201_183_dialog_content = "검은 기운이... 멈췄잖아?",
  ui_story_5075_50751201_184_dialog_content = "아니... 야...",
  ui_story_5075_50751201_185_dialog_content = "안... 돼...",
  ui_story_5075_50751201_186_dialog_content = "우룡이 왜 저러죠? 엄청 고통스러워 보이는데...",
  ui_story_5075_50751201_187_dialog_content = "이게 자기가 진정으로 바라던 게 아닐 테니까.",
  ui_story_5075_50751201_188_dialog_content = "내가 아는 우룡은 동족과 친구를 아끼는 아이야.\n설령 저 아이가 증오를 품는다 해도, 다른 수요령까지 끌어들일 리는 없어.",
  ui_story_5075_50751201_189_dialog_content = "게다가 모든 사람이 린 가문의 선조처럼 증오의 대상인 건 아냐.",
  ui_story_5075_50751201_190_dialog_content = "조금 전에 PlayerName의 행동은 너도 봤겠지.",
  ui_story_5075_50751201_191_dialog_content = "만약 그때 린 가문에 이 친구가 있었다면... 분명 똑같이 행동했을 거야.",
  ui_story_5075_50751201_192_dialog_content = "......",
  ui_story_5075_50751201_193_dialog_content = "린 가문은 너무 오랫동안 널 가뒀어.",
  ui_story_5075_50751201_194_dialog_content = "이제 더는 네가 타인에게 억지로 떠맡은 증오로 고통받지 않게 해 줄게.",
  ui_story_5075_50751201_195_dialog_content = "교룡어들의 목소리는 나도 들었어.",
  ui_story_5075_50751201_196_dialog_content = "내가 널 구해줄게.",
  ui_story_5075_50751201_197_dialog_content = "아, 니, 야!",
  ui_story_5075_50751201_198_dialog_content = "이 증오는, 내 거야!",
  ui_story_5075_50751201_199_dialog_content = "너도, 똑같아.",
  ui_story_5075_50751201_200_dialog_content = "<size=45>배, 신, 자!</size>",
  ui_story_5075_50751202_1_dialog_content = "선재, 선재라~ 드디어 깨어났구나. 자고로 늦잠을 자는 아이는 키가 잘 자라지 않는 법이니라.",
  ui_story_5075_50751202_2_dialog_content = "그래...? 그럼 이제부터라도 일찍 자고 일찍 일어나면... 키가 더 클까?",
  ui_story_5075_50751202_3_dialog_content = "이 몸에게 소원을 비는 것은 어떠하냐~",
  ui_story_5075_50751202_4_dialog_content = "월백 그대도 마찬가지니라.",
  ui_story_5075_50751202_5_dialog_content = "전 이제 어린아이가 아니에요.",
  ui_story_5075_50751202_6_dialog_content = "이 몸에 비하면 그대는 새파란 아가이니라.",
  ui_story_5075_50751202_7_dialog_content = "그러니 인상 쓸 거 없다. 우룡이 싸우는 대신 달아났을 뿐이지 않더냐.",
  ui_story_5075_50751202_8_dialog_content = "아직 물속에 있기만 한다면, 찾아내는 것이 무에 어려울꼬?",
  ui_story_5075_50751202_9_dialog_content = "<color=#e8d9bb>진예는 갑자기 손을 들더니 바다를 향해 한 줄기 금색 빛을 내뿜었다.</color>",
  ui_story_5075_50751202_10_dialog_content = "...지금 뭐 한 거냐고 안 물어보는 게 좋겠지?",
  ui_story_5075_50751202_11_dialog_content = "이미 소용없느니라. 이 몸이 남아 있던 봉인도 해제하였으니 말이야.",
  ui_story_5075_50751202_12_dialog_content = "<color=#e8d9bb>쿠구구!</color>",
  ui_story_5075_50751202_13_dialog_content = "<color=#e8d9bb>조금 전까지 잔잔했던 수면이 맹렬히 일렁이더니, 커다란 파도가 일기 시작했다.</color>",
  ui_story_5075_50751202_14_dialog_content = "<color=#e8d9bb>이윽고 바다에서 형체 하나가 하늘로 떠올랐다.</color>",
  ui_story_5075_50751202_15_dialog_content = "<color=#e8d9bb>수많은 소용돌이가 바다를 가르고, 그곳에서 끝없는 검은 기운이 피어올랐다.</color>",
  ui_story_5075_50751202_16_dialog_content = "녀석이 바로 그대들이 말하던 우룡인 게냐? 확실히 어리긴 하구나.",
  ui_story_5075_50751202_17_dialog_content = "너, 누구인지, 알아.",
  ui_story_5075_50751202_18_dialog_content = "진, 룡.",
  ui_story_5075_50751202_19_dialog_content = "원념 속 의식을 통해 알게 된 것이로구나. 이 몸을 이토록 오랫동안 기억해 주다니 고마운지고.",
  ui_story_5075_50751202_20_dialog_content = "복수, 할, 거야.",
  ui_story_5075_50751202_21_dialog_content = "넌, 나서지, 마.",
  ui_story_5075_50751202_22_dialog_content = "그렇지, 않으면.",
  ui_story_5075_50751202_23_dialog_content = "성을, 가라앉힐, 거야.",
  ui_story_5075_50751202_24_dialog_content = "설마... 그대는...",
  ui_story_5075_50751202_25_dialog_content = "(진예가 저렇게 심각한 표정인 건 처음 보는데?)",
  ui_story_5075_50751202_26_dialog_content = "(설마 진예도 방법이 없는 건가...?)",
  ui_story_5075_50751202_27_dialog_content = "저 말은 그럼 진예가 나선다면 호진을 통째로 물에 잠기게 만들겠다는 거죠?",
  ui_story_5075_50751202_28_dialog_content = "호진 사람들 전부를 인질로 삼은 거야.",
  ui_story_5075_50751202_29_dialog_content = "그 말인즉슨...",
  ui_story_5075_50751202_30_dialog_content = "이 몸에게 으름장을 놓고 있는 것이렷다!",
  ui_story_5075_50751202_31_dialog_content = "하아?",
  ui_story_5075_50751202_32_dialog_content = "누군가에게 위협을 받는 것도 수백 년 만이로구나. 감회가 새로운지고!",
  ui_story_5075_50751202_33_dialog_content = "허나 가만 생각해 보니 이 몸은 이번 일과 아무런 관련이 없지 않더냐.",
  ui_story_5075_50751202_34_dialog_content = "중간 과정이 복잡하여 이 몸은 이해가 잘 가지 않는구나.",
  ui_story_5075_50751202_35_dialog_content = "허나 봉인을 파괴한 것은 인간이고, 우룡이 증오를 품게 된 것 또한\n인간과 수요령 사이의 문제니라.",
  ui_story_5075_50751202_36_dialog_content = "그러니 인간과 수요령이 스스로 해결함이 마땅하다.",
  ui_story_5075_50751202_37_dialog_content = "음, 역시 이 몸은 늘 이치에 맞단 말이지!",
  ui_story_5075_50751202_38_dialog_content = "이럴 땐 그런 거 좀 안 따져도 되잖아!",
  ui_story_5075_50751202_39_dialog_content = "허나 아무리 감회가 새로워도 이 몸은 다른 이에게 위협받는 것을 좋아하지 않는다.",
  ui_story_5075_50751202_40_dialog_content = "그러니...",
  ui_story_5075_50751202_41_dialog_content = "(진예가 왜 갑자기 하늘로 날아오른 거지? 게다가 우룡 쪽으로 날아갔잖아...)",
  ui_story_5075_50751202_42_dialog_content = "콩~",
  ui_story_5075_50751202_43_dialog_content = "<color=#e8d9bb>진예는 주먹으로 우룡의 머리를 가볍게 두들겼다.</color>",
  ui_story_5075_50751202_44_dialog_content = "이 몸이 나섰느니라. 이제 어찌할 테냐?",
  ui_story_5075_50751202_45_dialog_content = "진예?!",
  ui_story_5075_50751202_46_dialog_content = "<color=#e8d9bb>쿠르르릉!</color>",
  ui_story_5075_50751202_47_dialog_content = "<color=#e8d9bb>마치 우룡의 분노를 대변하는 듯, 요란한 소리와 함께 큰 파도가 일기 시작했다.</color>",
  ui_story_5075_50751202_48_dialog_content = "<color=#e8d9bb>연달아 밀려드는 거대한 파도는 가라앉을 기미도 없었고,\n주변의 파도 소리와 함께 점점 높아질 뿐이었다.</color>",
  ui_story_5075_50751202_49_dialog_content = "<color=#e8d9bb>일행이 서 있던 해변도 빠르게 물에 잠기기 시작했다.</color>",
  ui_story_5075_50751202_50_dialog_content = "이러다간 우리가 먼저 물에 빠져 죽겠어요!",
  ui_story_5075_50751202_51_dialog_content = "괜찮아, 난 수영 잘하거든. 물에 빠지면 날 불러. 건져 줄 테니까.",
  ui_story_5075_50751202_52_dialog_content = "그냥 처음부터 안 빠지고 싶다구요!",
  ui_story_5075_50751202_53_dialog_content = "아, 하마터면 그대들을 잊을 뻔했구나.",
  ui_story_5075_50751202_54_dialog_content = "(뭐, 뭐야?! 몸이 갑자기 붕 떴잖아?!)",
  ui_story_5075_50751202_55_dialog_content = "어떠하냐? 이 몸의 신통력이 참으로 편리하지 않느냐?",
  ui_story_5075_50751202_56_dialog_content = "우룡은?",
  ui_story_5075_50751202_57_dialog_content = "도시를 <color=#FFB400>가라앉히겠다</color>고 하지 않더냐. 호진으로 하고 있다.",
  ui_story_5075_50751202_58_dialog_content = "그, 그럼 상황이 더 나빠진 거 아냐?!",
  ui_story_5075_50751202_59_dialog_content = "왜 굳이 우룡을 자극한 거야...?",
  ui_story_5075_50751202_60_dialog_content = "그리 긴장할 것 없느니라, PlayerName.",
  ui_story_5075_50751202_61_dialog_content = "이 몸은 기나긴 시간을 살아오며, 용주의 생명들을 아주 오랫동안 지켜봐 왔느니라.",
  ui_story_5075_50751202_62_dialog_content = "우룡도, 그리고 그대도 말이다.",
  ui_story_5075_50751202_63_dialog_content = "저들을 너무 얕봐서는 아니 된다.",
  ui_story_5075_50751301_1_dialog_content = "「급급여율──」",
  ui_story_5075_50751301_2_dialog_content = "캬오!",
  ui_story_5075_50751301_3_dialog_content = "(휴, 하나를 기절시키면 또 하나가 깨어나잖아.)",
  ui_story_5075_50751301_4_dialog_content = "(성안의 검은 기운이 점점 짙어져서, 벌써부터 저게 안 보이던 때가 그리워질 지경이야.)",
  ui_story_5075_50751301_5_dialog_content = "(밧줄만으로 광기에 휩싸인 수요령을 묶어 두는 건 역부족이야.\n만약 나도 녀석들의 몸속의 원념을 제거할 수 있다면...)",
  ui_story_5075_50751301_6_dialog_content = "지나갈게! 다들 좀 비켜 봐! 약을 가지고 왔어!",
  ui_story_5075_50751301_7_dialog_content = "수, 수요령들한테 약을 먹인다고?",
  ui_story_5075_50751301_8_dialog_content = "보면 몰라?",
  ui_story_5075_50751301_9_dialog_content = "하지만 녀석들이 이성을 잃은 건 병 때문이 아니라, 원념에 침식당해서...",
  ui_story_5075_50751301_10_dialog_content = "넌 의원이 병만 고칠 수 있다고 생각하는 모양이지?",
  ui_story_5075_50751301_11_dialog_content = "원념이란 것도 수요령의 몸 안에 들어가야지만 힘을 발휘하니까, 일종의 독이라고 볼 수 있어.",
  ui_story_5075_50751301_12_dialog_content = "독이란 건 그 작용을 없앨 해독법도 반드시 있기 마련이야.",
  ui_story_5075_50751301_13_dialog_content = "호진성이 검은 기운으로 가득 차는 바람에 작은꼬리... 우리 형도 영향을 받았어.",
  ui_story_5075_50751301_14_dialog_content = "근데 스승님한테 배웠던 몸속의 광력을 조절해 주는 약을 만들어 먹였더니 상태가 많이 나아졌어.",
  ui_story_5075_50751301_15_dialog_content = "그래서 도와주러 온 거야.",
  ui_story_5075_50751301_16_dialog_content = "냐아앙!",
  ui_story_5075_50751301_17_dialog_content = "형...? 그렇구나, 너도 <color=#FFB400>수요령</color>이구나.",
  ui_story_5075_50751301_18_dialog_content = "왜? 너도 수요령한테 불만 있어?",
  ui_story_5075_50751301_19_dialog_content = "아니, 아니야! 난 그냥 대단한 의원이구나 생각했을 뿐이야.",
  ui_story_5075_50751301_20_dialog_content = "진짜 그렇게 생각했다고? 헤헤, 그래도 보는 눈은 있네.",
  ui_story_5075_50751301_21_dialog_content = "근데 사실 난 그렇게 대단하진 않아...",
  ui_story_5075_50751301_22_dialog_content = "약을 가져오긴 했는데, 수요령들이 날뛰는 바람에 약을 먹일 기회를 못 잡고 있거든...",
  ui_story_5075_50751301_23_dialog_content = "그건 나한테 맡겨!",
  ui_story_5075_50751301_24_dialog_content = "수요령이 눈에 띄기만 하면 일격에 기절시켜서 약을 먹일 수 있게 네 앞에 데려다 줄 테니까!",
  ui_story_5075_50751301_25_dialog_content = "쉿! 쉿! 목소리 낮춰!",
  ui_story_5075_50751301_26_dialog_content = "우린 지금 집에서 몰래 나온 거라 들키면 곤란하다구.",
  ui_story_5075_50751301_27_dialog_content = "아, 그렇구나! 나도 어렸을 땐 자주 그랬거든.",
  ui_story_5075_50751301_28_dialog_content = "걱정 마, 그럼 다른 사람들한테 안 들키게 망을 봐 줄 테니까.",
  ui_story_5075_50751301_29_dialog_content = "난 나송이고, 이쪽은 내 단짝 아정이야.",
  ui_story_5075_50751301_30_dialog_content = "캬오!",
  ui_story_5075_50751301_31_dialog_content = "난 리청이고, 이쪽은 우리 형 작은꼬리야.",
  ui_story_5075_50751301_32_dialog_content = "냐아앙!",
  ui_story_5075_50751301_33_dialog_content = "그럼 잘해보자!",
  ui_story_5075_50751301_34_dialog_content = "크냐앙!",
  ui_story_5075_50751301_35_dialog_content = "찍찍찍!",
  ui_story_5075_50751301_36_dialog_content = "내가 가서 보고 올게. 리청 의원은 여기서 기다려 줘!",
  ui_story_5075_50751301_37_dialog_content = "엇, 잠깐만...!",
  ui_story_5075_50751301_38_dialog_content = "거 성격 한번 급하네.",
  ui_story_5075_50751301_39_dialog_content = "사, 사람 살려!",
  ui_story_5075_50751301_40_dialog_content = "가, 가까이 오지 마! 이 몽둥이는 장난감이 아니라고!",
  ui_story_5075_50751301_41_dialog_content = "찍찍찍!",
  ui_story_5075_50751301_42_dialog_content = "이 요괴 녀석들, 우리가 만만한 줄 알아?! 에잇──!",
  ui_story_5075_50751301_43_dialog_content = "다들 멈춰요! 크윽...",
  ui_story_5075_50751301_44_dialog_content = "나송!",
  ui_story_5075_50751301_45_dialog_content = "왜 그런 멍청한 짓을 하는 거야?! 그렇게 무턱대고 중간에 끼어드는 사람이 어딨어?",
  ui_story_5075_50751301_46_dialog_content = "이거 봐. 어깨엔 몽둥이 한 방, 배엔 발톱 한 방, 이게 다 뭐냐고.",
  ui_story_5075_50751301_47_dialog_content = "하하. 마음이 너무 급했지 뭐야.",
  ui_story_5075_50751301_48_dialog_content = "난 괜찮으니까, 우선 이 수요령한테 약을 먹여 줘. 방금 잽싸게 붙잡아 놨거든.",
  ui_story_5075_50751301_49_dialog_content = "...세심한 건지, 덜렁대는 건지 도통 알 수가 없네.",
  ui_story_5075_50751301_50_dialog_content = "저, 저기, 그... 미, 미안합니다... 그러려던 게 아닌데...",
  ui_story_5075_50751301_51_dialog_content = "신경 쓰지 마세요. 갑자기 끼어든 건 제 쪽이니까요.",
  ui_story_5075_50751301_52_dialog_content = "하, 하지만 저건 수요령이잖습니까! 왜 녀석을 감싸는 겁니까?",
  ui_story_5075_50751301_53_dialog_content = "오히려 나송이 당신을 감싼 거라고 해야 맞지 않아?",
  ui_story_5075_50751301_54_dialog_content = "아...",
  ui_story_5075_50751301_55_dialog_content = "갑자기 수요령에게 습격받는다면 누구라도 반격을 하겠죠.\n하지만 지금 인간을 공격하는 건 수요령들의 본심이 아니에요.",
  ui_story_5075_50751301_56_dialog_content = "모두가 무고한 피해자일 뿐이라고요.",
  ui_story_5075_50751301_57_dialog_content = "잘못을 저지른 사람이 없다면 그 누구도 다쳐서는 안 돼요.",
  ui_story_5075_50751301_58_dialog_content = "그게 당연한 이치 아닌가요?",
  ui_story_5075_50751301_59_dialog_content = "자, 약 다 먹였어. 이 녀석도 좀 괜찮아졌네.",
  ui_story_5075_50751301_60_dialog_content = "우린 벌써 호진성의 절반 정도는 돌아다녔으니까, 대부분의 수요령은 조치가 끝났을 거야.",
  ui_story_5075_50751301_61_dialog_content = "뀨.",
  ui_story_5075_50751301_62_dialog_content = "보셨죠? 수요령들은 외부의 힘에 조종당해서 사람들을 공격한 거예요.\n정상으로 돌아오기만 하면 괜찮아져요.",
  ui_story_5075_50751301_63_dialog_content = "...다른 사람이 그런 말을 했다면 아마 안 믿었겠죠.",
  ui_story_5075_50751301_64_dialog_content = "하지만 당신이 한 말이니 믿겠습니다.",
  ui_story_5075_50751301_65_dialog_content = "구해 주셔서 정말 감사합니다! 그럼 다른 사람들에게도 이 얘기를 전해서,\n수요령이 사람을 해치려 하면 큰 소리로 당신을 부르라고 하겠습니다.",
  ui_story_5075_50751301_66_dialog_content = "정말요? 그래 주시면 감사하죠!",
  ui_story_5075_50751301_67_dialog_content = "<color=#e8d9bb>쿠르르릉!</color>",
  ui_story_5075_50751301_68_dialog_content = "뭐야? 왜 하늘이 갑자기 이렇게 어두워진 거지?",
  ui_story_5075_50751301_69_dialog_content = "<color=#e8d9bb>후두두두──</color>",
  ui_story_5075_50751301_70_dialog_content = "비인가...?",
  ui_story_5075_50751301_71_dialog_content = "잠깐만, 이거 비가 아냐.",
  ui_story_5075_50751301_72_dialog_content = "<size=45>하늘도 어두워진 게 아니야... 거대한 파도가 해를 가린 거라구.</size>",
  ui_story_5075_50751301_73_dialog_content = "<size=45>이러다간 호진성이 물에 가라앉아 버리겠는데?!</size>",
  ui_story_5075_50751302_1_dialog_content = "<color=#e8d9bb>거리는 공황에 빠져 도망치려는 사람들로 가득했다.</color>",
  ui_story_5075_50751302_2_dialog_content = "요마 짓이다! 요마가 홍수를 일으켜 우릴 물에 빠뜨려 죽일 거라고!",
  ui_story_5075_50751302_3_dialog_content = "빨리 도망쳐!",
  ui_story_5075_50751302_4_dialog_content = "비나이다, 비나이다, 용녀님, 부디 저희를 지켜 주세요...",
  ui_story_5075_50751302_5_dialog_content = "이건 이미 사람이 해결할 수 있는 문제가 아니야...",
  ui_story_5075_50751302_6_dialog_content = "진예! 우릴 내려 줘! 적어도 사람들이 대피하는 걸 돕고 싶어.",
  ui_story_5075_50751302_7_dialog_content = "용녀님.",
  ui_story_5075_50751302_8_dialog_content = "으음... 그리 해야 할 필요는 없어 보이는구나.",
  ui_story_5075_50751302_9_dialog_content = "하지만...!",
  ui_story_5075_50751302_10_dialog_content = "PlayerName, 귀 기울여 듣거라.",
  ui_story_5075_50751302_11_dialog_content = "으앗! 돌부리 때문에 넘어졌잖아... 아, 아파...",
  ui_story_5075_50751302_12_dialog_content = "여긴 어디지... 아빠... 엄마...?",
  ui_story_5075_50751302_13_dialog_content = "흐앙...",
  ui_story_5075_50751302_14_dialog_content = "캬아악!",
  ui_story_5075_50751302_15_dialog_content = "으아아! 사, 살려줘!",
  ui_story_5075_50751302_16_dialog_content = "찍!",
  ui_story_5075_50751302_17_dialog_content = "<color=#e8d9bb>암귀의 공격이 소년에게 닿기 직전, 수요령이 쏜살같이 달려와 몸을 부딪쳐 암귀를 밀어냈다.</color>",
  ui_story_5075_50751302_18_dialog_content = "<color=#e8d9bb>암귀의 공격은 소년을 살짝 비껴갔다.</color>",
  ui_story_5075_50751302_19_dialog_content = "너, 넌...",
  ui_story_5075_50751302_20_dialog_content = "이거 가지곤 부족해! 하나 더!",
  ui_story_5075_50751302_21_dialog_content = "폭죽아! 수요령도 몰아내고 악운도 날려줘!",
  ui_story_5075_50751302_22_dialog_content = "찍...",
  ui_story_5075_50751302_23_dialog_content = "그때 그...",
  ui_story_5075_50751302_24_dialog_content = "캬오오!",
  ui_story_5075_50751302_25_dialog_content = "조심해!",
  ui_story_5075_50751302_26_dialog_content = "<color=#e8d9bb>소년은 암귀에게 달려들어 수요령을 품에 안고 진흙투성이 바닥을 굴러 피했다.</color>",
  ui_story_5075_50751302_27_dialog_content = "아정, 가라!",
  ui_story_5075_50751302_28_dialog_content = "그어억...",
  ui_story_5075_50751302_29_dialog_content = "음? 넌 저번에 그 꼬마잖아?",
  ui_story_5075_50751302_30_dialog_content = "무, 물이 떨어진다아아!",
  ui_story_5075_50751302_31_dialog_content = "찍!",
  ui_story_5075_50751302_32_dialog_content = "잠깐만! 같이 가──!",
  ui_story_5075_50751302_33_dialog_content = "<color=#e8d9bb>그 광경은 마치 하늘이 무너지는 듯했다.</color>",
  ui_story_5075_50751302_34_dialog_content = "<color=#e8d9bb>어마어마한 굉음과 함께, 거대한 파도가 하늘에서 떨어져 내리기 시작했다.</color>",
  ui_story_5075_50751302_35_dialog_content = "<color=#e8d9bb>그 압도적인 힘 앞에서, 사람들은 지상에 세워진 보잘것없는 성을 벗어날 엄두조차 내지 못했다.</color>",
  ui_story_5075_50751302_36_dialog_content = "으아아아──!",
  ui_story_5075_50751302_37_dialog_content = "......",
  ui_story_5075_50751302_38_dialog_content = "...어, 아무 일도 없잖아? 뭐지?",
  ui_story_5075_50751302_39_dialog_content = "...위를 봐.",
  ui_story_5075_50751302_40_dialog_content = "찍!",
  ui_story_5075_50751302_41_dialog_content = "<color=#e8d9bb>조그만 수요령이 하늘로 날아올라, 공중에서 무형의 방벽을 만들어 지탱하고 있었다.</color>",
  ui_story_5075_50751302_42_dialog_content = "<color=#e8d9bb>코앞까지 다가왔던 파도는 장벽 밖에서 전진을 멈추었다.</color>",
  ui_story_5075_50751302_43_dialog_content = "<color=#e8d9bb>짓누르는 힘에 온몸을 떨고 있으면서도, 수요령은 자그마한 앞발을 들고\n필사적으로 방벽을 지탱하고 있었다.</color>",
  ui_story_5075_50751302_44_dialog_content = "<color=#e8d9bb>이윽고, 멀지 않은 곳에서 또 하나의 방벽이 하늘로 떠올랐다.</color>",
  ui_story_5075_50751302_45_dialog_content = "캬오!",
  ui_story_5075_50751302_46_dialog_content = "<color=#e8d9bb>그리고 하나, 또 하나...</color>",
  ui_story_5075_50751302_47_dialog_content = "<color=#e8d9bb>수요령들이 지탱하는 방벽들이 하나씩 이어져 커다란 형태를 이루었다.</color>",
  ui_story_5075_50751302_48_dialog_content = "<color=#e8d9bb>천근처럼 짓누르던 무거운 파도도 이제 호진성 하늘 위에 멈추어,\n더는 한 치도 나아갈 수 없었다.</color>",
  ui_story_5075_50751302_49_dialog_content = "저건...",
  ui_story_5075_50751302_50_dialog_content = "이 천지가 광령만의 것이었던 적은 단 한 번도 없었느니라.",
  ui_story_5075_50751302_51_dialog_content = "수요령들 또한 늘 자신들의 터전을 지키려 했지.",
  ui_story_5075_50751302_52_dialog_content = "린 가문의 늙은이가 부탁하지 않았더라도, 우룡은 벗들을 위해 봉인을 찾아 나섰을 게야.\n이 또한 같은 이치니라.",
  ui_story_5075_50751302_53_dialog_content = "설령 광령들이 인정하고 싶지 않더라도, 발밑의 이 땅에는 수요령들의 몫도 있는 것이다.",
  ui_story_5075_50751302_54_dialog_content = "PlayerName, 들었느냐?",
  ui_story_5075_50751302_55_dialog_content = "응, 들었어.",
  ui_story_5075_50751302_56_dialog_content = "그리고 다른 사람들도 들어야 한다고 생각해.",
  ui_story_5075_50751302_57_dialog_content = "말을 전하는 것쯤은 어렵지 않지. 그거라면 이 몸이 살짝 힘을 보태 주마~",
  ui_story_5075_50751302_58_dialog_content = "자, 오너라──",
  ui_story_5075_50751302_59_option_content = "[감응한다]",
  ui_story_5075_50751302_60_dialog_content = "다리가 둘인 인간, 정말 못됐어, 우릴 볼 때마다 발로 걷어차.",
  ui_story_5075_50751302_61_dialog_content = "하지만 다리가 둘인 인간, 착하기도 해. 맛있는 사냥감을 잡을 수 있어.",
  ui_story_5075_50751302_62_dialog_content = "가끔 우리한테 나눠 주기도 해.",
  ui_story_5075_50751302_63_dialog_content = "이, 이게 뭐야?",
  ui_story_5075_50751302_64_dialog_content = "...수요령들의... 목소리?",
  ui_story_5075_50751302_65_dialog_content = "뜨거운 물건을 던지면 터져, 너무 무서워.",
  ui_story_5075_50751302_66_dialog_content = "쫓겨나는 거, 너무 무서워.",
  ui_story_5075_50751302_67_dialog_content = "여긴 우리 집이기도 한데.",
  ui_story_5075_50751302_68_dialog_content = "하, 하지만 무서운 건 우리도 마찬가지야! 걸핏하면 물건을 훔쳐 가고 식량을 망치잖아!",
  ui_story_5075_50751302_69_dialog_content = "게다가 우리가 다루지 못하는 요술도 부리고! 우, 우리한테 어쩌라는 거야?!",
  ui_story_5075_50751302_70_dialog_content = "다리가 둘인 인간, 멍청해.\n구석에 물건을 떨어뜨려. 그리고 못 찾고, 우리 탓을 해.",
  ui_story_5075_50751302_71_dialog_content = "다리가 둘인 인간, 진짜 멍청해.\n음식은 마당에 있는데, 표식을 안 남겨. 다른 사람이 먹어.",
  ui_story_5075_50751302_72_dialog_content = "하지만 다리가 둘인 인간, 똑똑하기도 해.\n저번에 다리를 다쳤는데, 나무로 고정해 줬어. 그러니까 다 나았어.",
  ui_story_5075_50751302_73_dialog_content = "우리가 수요령들한테 너무 심하게 굴었던 건 아닐까...",
  ui_story_5075_50751302_74_dialog_content = "수요령이라고 해도 따지고 보면 이제 막 철이 든 들짐승들이잖아...",
  ui_story_5075_50751302_75_dialog_content = "멍청한데, 똑똑해. 나쁘지만, 착해. 우릴 때리는데, 미안하다고 해.\n다리가 둘인 인간, 정말 이상해.",
  ui_story_5075_50751302_76_dialog_content = "하지만 어쩔 수 없어.",
  ui_story_5075_50751302_77_dialog_content = "어쩔 수 없어.",
  ui_story_5075_50751302_78_dialog_content = "우리는 같은 집에 사니까.",
  ui_story_5075_50751302_79_dialog_content = "물이 밀려와. 저들은 도망칠 수 없어.",
  ui_story_5075_50751302_80_dialog_content = "물이 밀려와. 집도 도망칠 수 없어.",
  ui_story_5075_50751302_81_dialog_content = "커다란 파도는 나빠. 빨리 가 버려...",
  ui_story_5075_50751302_82_dialog_content = "들어올 수 없어...",
  ui_story_5075_50751302_83_dialog_content = "<size=45>우리 집이야!</size>",
  ui_story_5075_50751302_84_dialog_content = "<color=#e8d9bb>호진성을 뒤덮고 있던 방벽에서 갑자기 금색 빛이 흘러나왔고,\n멈춰 있던 거대한 파도는 홀연히 터져 나온 힘에 산산이 흩어졌다.</color>",
  ui_story_5075_50751302_85_dialog_content = "<color=#e8d9bb>그리고는 짜디짠 비로 변해, 호진성에 소리 없이 쏟아져 내렸다.</color>",
  ui_story_5075_50751302_86_dialog_content = "방금 그 비... 역시 네가 도와준 거지?",
  ui_story_5075_50751302_87_dialog_content = "무얼 말하는 게냐~?",
  ui_story_5075_50751302_88_dialog_content = "아니... 아무것도 아냐.",
  ui_story_5075_50751302_89_dialog_content = "저 수요령들, 정말 대단하네.",
  ui_story_5075_50751302_90_dialog_content = "그럼 이제 남은 건, 우룡뿐이야.",
  ui_story_5075_50751302_91_dialog_content = "......",
  ui_story_5075_50751302_92_dialog_content = "사람들이랑 수요령들의 마음속 소리, 너도 들었지?",
  ui_story_5075_50751302_93_dialog_content = "저들은 서로 오해도 하고, 다투기도 하고, 심지어는 다양한 이유로 서로를 상처입히기도 해.",
  ui_story_5075_50751302_94_dialog_content = "하지만 서로 협력하고, 돕고, 같은 땅에서 살아간 시간들도 있어.",
  ui_story_5075_50751302_95_dialog_content = "저들은 모두 용주에서 태어난 같은 생명들일 뿐이야. 날 때부터 상대에게 악의를 품은 건 아냐.",
  ui_story_5075_50751302_96_dialog_content = "그러니까 적어도 서로가 서로를 못 잡아먹어 안달인 관계로 만들진 마.",
  ui_story_5075_50751302_97_dialog_content = "그리고...",
  ui_story_5075_50751302_98_dialog_content = "아까 그 마음속 소리들 중엔 너한테 사과하는 소리도 있었어.",
  ui_story_5075_50751302_99_dialog_content = "우룡아.",
  ui_story_5075_50751302_100_dialog_content = "미안하구나.",
  ui_story_5075_50751401_1_dialog_content = "사, 과?",
  ui_story_5075_50751401_2_dialog_content = "어, 째, 서?",
  ui_story_5075_50751401_3_dialog_content = "하, 나, 도.",
  ui_story_5075_50751401_4_dialog_content = "후회, 하지, 않으면서.",
  ui_story_5075_50751401_5_dialog_content = "싫어... 으으...!",
  ui_story_5075_50751401_6_dialog_content = "우룡이 해안으로 돌아갔어! 어서 쫓아가자!",
  ui_story_5075_50751401_7_dialog_content = "우룡!",
  ui_story_5075_50751401_8_dialog_content = "고작 말 몇 마디에 흔들리다니, 쓸모없는 것!",
  ui_story_5075_50751401_9_dialog_content = "아니야... 으...!",
  ui_story_5075_50751401_10_dialog_content = "네 증오가 고작 그 정도라면, 차라리 이 육체를 전부 내게 넘겨라!",
  ui_story_5075_50751401_11_dialog_content = "우룡이... 조종에서 벗어나려고 애쓰고 있어!",
  ui_story_5075_50751401_12_dialog_content = "(지금이 기회일지도 몰라!)",
  ui_story_5075_50751401_13_dialog_content = "흥, 육체는 뛰어남에도 의지는 너무나도 약하군.",
  ui_story_5075_50751401_14_dialog_content = "수요령임에도 광령의 손바닥 위에서 놀아나다니, 수치스러운 일 아니더냐.",
  ui_story_5075_50751401_15_dialog_content = "오랜만이로구나, 진예.",
  ui_story_5075_50751401_16_dialog_content = "오랜만? 그리 오래되지도 않은 듯한데 말이다. 눈을 몇 번 붙인 정도일 뿐이지 않느냐.",
  ui_story_5075_50751401_17_dialog_content = "변한 게 없군.",
  ui_story_5075_50751401_18_dialog_content = "우리는 스스로 변하고자 하여도 어려우니 말이야.",
  ui_story_5075_50751401_19_dialog_content = "허나 인간 세상은 꽤 많은 것이 변했다. 그대는 줄곧 바다밑에 있어서 볼 수 없었겠지.",
  ui_story_5075_50751401_20_dialog_content = "스스로 사람을 찾아다니는 기관조, 화려한 색을 지닌 서양화,\n그리고 자신의 힘으로 바다를 건널 수 있는 배도 존재한다.",
  ui_story_5075_50751401_21_dialog_content = "흥... 아무리 화려한 것을 만들어 낼지라도, 결국엔 하등한 존재들 아니더냐.",
  ui_story_5075_50751401_22_dialog_content = "그대는 수명의 길고 짧음으로 생명의 우열을 가늠하느냐?",
  ui_story_5075_50751401_23_dialog_content = "만약 그렇다면 이상하지 않느냐.",
  ui_story_5075_50751401_24_dialog_content = "광령은 수명이 짧으나, 지금 이 대륙을 손에 넣은 것은 물론이고, 저들은 어디에나 존재한다.",
  ui_story_5075_50751401_25_dialog_content = "도리어 그대가 고등한 존재라 말하는 우리 같은 이들은 하나 만나기도 쉽지 않지.",
  ui_story_5075_50751401_26_dialog_content = "어째서 스스로를 격하하는 것이냐.",
  ui_story_5075_50751401_27_dialog_content = "우리 수요령은 모두 <color=#FFB400>「시조」</color>의 후예로, 더없이 존귀한 신분이거늘,\n미천한 광령 따위를 어찌 우리와 두고 논한단 말이더냐!",
  ui_story_5075_50751401_28_dialog_content = "심지어 이제는 아무런 힘도 없는 광령조차 수요령을 저들의 노리개인 양 모욕하고 있다.",
  ui_story_5075_50751401_29_dialog_content = "동족이 이러한 처지에 놓여 있거늘, 그대는 이를 보고도 모른 척하는 것이냐!",
  ui_story_5075_50751401_30_dialog_content = "수요령은 힘도 혈통도 모두 광령보다 우위에 있는 존재다.",
  ui_story_5075_50751401_31_dialog_content = "그런 우리가 어찌 저들에게 고개를 숙이고, 이 용주를 함께 나눠야 한단 말이냐!",
  ui_story_5075_50751401_32_option_content = "(강제 감응!)",
  ui_story_5075_50751401_33_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5075_50751401_34_dialog_content = "(강제 감응!)",
  ui_story_5075_50751401_35_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5075_50751401_36_dialog_content = "(안 돼. 진짜 우룡의 존재는 희미하게밖에 안 느껴져.\n아무리 애를 써도 우룡의 의식에 닿을 수가 없어.)",
  ui_story_5075_50751401_37_dialog_content = "PlayerName, 우룡에게 내 의지를 전해 줄 수 있을까?",
  ui_story_5075_50751401_38_dialog_content = "최선을 다해 볼게요! 그치만 지금 상태에서 우룡이 우리 목소리를 들을 수 있을진 모르겠어요...",
  ui_story_5075_50751401_39_dialog_content = "괜찮아.",
  ui_story_5075_50751401_40_dialog_content = "심해를 자유롭게 누비는 교룡어가 저렇게 쉽게 「수몰」되진 않을 테니까.",
  ui_story_5075_50751401_41_dialog_content = "알겠어요. 그럼 준비하세요.",
  ui_story_5075_50751401_42_option_content = "(강제 감응!)",
  ui_story_5075_50751401_43_dialog_content = "우룡, 내 목소리 들려?",
  ui_story_5075_50751401_44_dialog_content = "......",
  ui_story_5075_50751401_45_dialog_content = "내가 여기 오기 전에 가주님께서 말씀해 주셨어.\n가주님은 직접 네게 미안하다는 말을 한 적이 없었다고.",
  ui_story_5075_50751401_46_dialog_content = "그건 네 아량으로 가주님 자신의 비열함을 포용하도록 강요하는 결과를 피하려고 그러셨던 거야.",
  ui_story_5075_50751401_47_dialog_content = "가주님은 알면서도 잘못을 저질렀고, 그 잘못이 가져다준 번영을 받아들였어.\n그러니 자신은 용서를 바랄 자격은 없다고 하셨어.",
  ui_story_5075_50751401_48_dialog_content = "린 가문도 마찬가지고.",
  ui_story_5075_50751401_49_dialog_content = "만약 네가 교룡어의 피가 흐르는 나도 배신자라 생각한다면,\n당연히 나 역시 그 안에 포함될 거야.",
  ui_story_5075_50751401_50_dialog_content = "우린 네 복수를 받아들일게.",
  ui_story_5075_50751401_51_dialog_content = "하지만 우리에게 복수하는 건, 그 누구에게도 조종받지 않는 우룡 너 자신이어야만 해.",
  ui_story_5075_50751401_52_dialog_content = "네 증오를, 교룡어들의 원한을, 그렇게 쉽게 다른 자의 손에 넘길 셈이야?!",
  ui_story_5075_50751401_53_dialog_content = "싫, 어.",
  ui_story_5075_50751401_54_dialog_content = "반응을 보였어요!",
  ui_story_5075_50751401_55_dialog_content = "우룡, 이제 난 네 몸을 조종하고 있는 사념을 쫓아내 보려고 해.",
  ui_story_5075_50751401_56_dialog_content = "그러니까 너도 도와줬으면 좋겠어.",
  ui_story_5075_50751401_57_dialog_content = "PlayerName, 월백, 이 아이들은 참으로 느리구나.",
  ui_story_5075_50751401_58_dialog_content = "그게 무슨 소리냐.",
  ui_story_5075_50751401_59_dialog_content = "이 몸이 더는 그대와 이런 무의미한 이야기를 나누고 싶지 않다는 뜻이니라.",
  ui_story_5075_50751401_60_dialog_content = "......?",
  ui_story_5075_50751401_61_dialog_content = "연기는 그만두거라.",
  ui_story_5075_50751401_62_dialog_content = "그대는 이 몸의 동족이 아니니라.",
  ui_story_5075_50751401_63_dialog_content = "!",
  ui_story_5075_50751401_64_dialog_content = "갓 눈을 떴을 무렵, 이 몸은 동족들에게 기별을 보냈었다.",
  ui_story_5075_50751401_65_dialog_content = "허나 다들 잠들어 있었기에, 가까운 용주에서부터 저 먼 운도까지,\n답을 전한 이는 얼마 되지 않았지.",
  ui_story_5075_50751401_66_dialog_content = "이 몸이 흑룡의 기운을 흉내 내는 그대의 말 상대를 해 준 것은 그러한 연유에서니라.",
  ui_story_5075_50751401_67_dialog_content = "허나 그대는 흑룡이 아니니라. 그저 육체의 기억을 훔친 음울한 감정의 덩어리일 뿐이지.",
  ui_story_5075_50751401_68_dialog_content = "그대는 흑룡의 마음에 오만함만을 남겼고, 우룡의 마음에는 증오만을 남겼다.",
  ui_story_5075_50751401_69_dialog_content = "그것은 그대가 지닌 감정이 그 두 가지뿐인 까닭일 터.",
  ui_story_5075_50751401_70_dialog_content = "그대는 입으로는 「동족」을 운운하나 수요령을 조금도 가엾이 여기지 않는다.",
  ui_story_5075_50751401_71_dialog_content = "그대는 「고귀」하다 자청하나 죽음을 두려워하고, 삶을 탐하는 가장 비열한 사욕만을 지녔지.",
  ui_story_5075_50751401_72_dialog_content = "더군다나 인격조차 지니지 못하여, 빙의한 가면에 숨어 구차하게 사는 수밖에 없지 않느냐.",
  ui_story_5075_50751401_73_dialog_content = "그럼에도 진정 자신이 고등한 존재라 여기는 것이냐?",
  ui_story_5075_50751401_74_dialog_content = "인격을 지니지 못한 것이 뭐가 어떻다는 것이냐. 나야말로 진정한 불사의 존재다!",
  ui_story_5075_50751401_75_dialog_content = "소위 신령이라 하는 너희 같은 것들도 나만큼 오래 살지는 못한다! 나는...",
  ui_story_5075_50751401_76_dialog_content = "지금이야! 녀석의 감정이 격해졌어!",
  ui_story_5075_50751401_77_option_content = "(강제 감응!)",
  ui_story_5075_50751401_78_dialog_content = "내, 몸, 에, 서.",
  ui_story_5075_50751401_79_dialog_content = "꺼, 져!",
  ui_story_5075_50751401_80_dialog_content = "크윽──!",
  ui_story_5075_50751401_81_dialog_content = "아니?!",
  ui_story_5075_50751401_82_dialog_content = "고마워, 진예. 네가 주의를 끌어 준 덕분에 우룡을 찾을 수 있었어!",
  ui_story_5075_50751401_83_dialog_content = "이제 우룡을 도와서 녀석의 힘을 몰아내기만 하면 돼...",
  ui_story_5075_50751401_84_dialog_content = "꿈도 꾸지 마라!",
  ui_story_5075_50751402_1_dialog_content = "크크크... 어차피 쓸모없는 몸뚱아리일 뿐이다. 네놈들에게 돌려준들 아무 의미도 없다.",
  ui_story_5075_50751402_2_dialog_content = "여긴 내 진짜 몸이 잠들어 있는 곳이란 말이다.",
  ui_story_5075_50751402_3_dialog_content = "빙의할 그릇이 없어졌다 해도, 네놈들도 날 어찌하진 못할 것이다!",
  ui_story_5075_50751402_4_dialog_content = "<color=#e8d9bb>먼바다가 또다시 요동치기 시작했다.</color>",
  ui_story_5075_50751402_5_dialog_content = "(...호진성이 물에 잠기려는 꼴을 또 보고 싶진 않아.)",
  ui_story_5075_50751402_6_dialog_content = "진예, 저번에 이 금장식을 너한테 주면 소원을 하나 빌어도 된다고 했지?",
  ui_story_5075_50751402_7_dialog_content = "호오?",
  ui_story_5075_50751402_8_dialog_content = "마음씨 고운 이여, 그대의 소원은 무엇인고?",
  ui_story_5075_50751402_9_dialog_content = "저 녀석은 오로리안도 아니고, 수요령도 아니고, 심지어 암귀도 아냐.",
  ui_story_5075_50751402_10_dialog_content = "그저 악의가 쌓여 만들어진 덩어리일 뿐이고, 존재할 가치조차 없어.",
  ui_story_5075_50751402_11_dialog_content = "그러니까 이 세상이 다시 평온해질 수 있도록, 저 악의를 없애 줘, 선녀용왕님.",
  ui_story_5075_50751402_12_dialog_content = "좋다.",
  ui_story_5075_50751402_13_dialog_content = "크하하하! 이미 팔백 년이 지났다. 네 그 선녀용왕은 내가 호진을 뒤덮을 때조차 나서지 못했다!",
  ui_story_5075_50751402_14_dialog_content = "분명 사람들의 숭배가 줄어 힘이 약해진 것이겠지──",
  ui_story_5075_50751402_15_dialog_content = "<color=#e8d9bb>찰나의 순간, 금빛 연꽃이 찬란하게 빛났다.</color>",
  ui_story_5075_50751402_16_dialog_content = "<color=#e8d9bb>그리고 바다와 하늘 사이에 유리처럼 맑은 형상이 떠올랐다.</color>",
  ui_story_5075_50751402_17_dialog_content = "<color=#e8d9bb>웅장한 금빛이 잔물결처럼 퍼져나갔고, 빛이 닿은 곳의 요마들은 모두 사라져 있었다.</color>",
  ui_story_5075_50751402_18_dialog_content = "<color=#e8d9bb>호진성 안</color>",
  ui_story_5075_50751402_19_dialog_content = "그어어어──",
  ui_story_5075_50751402_20_dialog_content = "성안의 요마들이... 전부 사라졌잖아?",
  ui_story_5075_50751402_21_dialog_content = "저기 하늘 좀 봐! 빨리!",
  ui_story_5075_50751402_22_dialog_content = "용녀님이시다! 용녀님이 현신하셔서 우릴 위해 요마들을 물리쳐 주신 거야!",
  ui_story_5075_50751402_23_dialog_content = "<color=#e8d9bb>검은 교룡의 형체를 이루던 암귀의 사념은 한 치의 망설임도 없이 고개를 돌려 달아났다.</color>",
  ui_story_5075_50751402_24_dialog_content = "<color=#e8d9bb>그러나 빛의 형상이 가볍게 손가락을 튕기자, 사념은 너무나도 쉽게 붙잡혔다.</color>",
  ui_story_5075_50751402_25_dialog_content = "이 몸의 힘이 쇠하였다 하였거늘, 어찌 두려워하는 게냐?",
  ui_story_5075_50751402_26_dialog_content = "크크... 크크크!",
  ui_story_5075_50751402_27_dialog_content = "이렇게 오랜 시간이 지났는데도, 아직 이 정도 힘이 남아 있을 줄이야.",
  ui_story_5075_50751402_28_dialog_content = "하지만 너흰 아직 이긴 게 아니다!",
  ui_story_5075_50751402_29_dialog_content = "암귀 시조의 힘이 있는 한, 나는 영원불멸에 가까운 존재다!",
  ui_story_5075_50751402_30_dialog_content = "네가 이 사념을 없앤다 해도, 나의 힘은 다시 모여들어 날 부활시킬 것이다.",
  ui_story_5075_50751402_31_dialog_content = "날 한두 번 없앨 순 있겠지. 허나 수천, 수만 번 없앨 수 있을 것 같으냐?",
  ui_story_5075_50751402_32_dialog_content = "나는──",
  ui_story_5075_50751402_33_dialog_content = "<color=#e8d9bb>원념은 마지막 말을 끝마칠 수 없었다.</color>",
  ui_story_5075_50751402_34_dialog_content = "마음도, 형태도 없는 것은 이 세상에 존재할 필요가 없나니.",
  ui_story_5075_50751402_35_dialog_content = "<color=#e8d9bb>빛의 형상은 원념을 집어 부수었다.</color>",
  ui_story_5075_50751402_36_dialog_content = "<color=#e8d9bb>그러나 다음 순간, 바다에서 또다시 검은 안개가 일었다.</color>",
  ui_story_5075_50751402_37_dialog_content = "<color=#e8d9bb>검은 안개 속에서 융합한 원념과 다크매터는 혼탁한 씨앗이 되어 빠른 속도로 재생을 시작했다.</color>",
  ui_story_5075_50751402_38_dialog_content = "인정하고 싶진 않지만, 녀석 말이 맞아. 우리가 영원히 여길 지키고 있을 순 없어.",
  ui_story_5075_50751402_39_dialog_content = "이 문제를 영구적으로 해결할 방법이 정말 없는 거라면...\n우리가 다음에도, 그리고 그다음에도 모두를 무사히 구해낼 수 있을까...?",
  ui_story_5075_50751402_40_dialog_content = "PlayerName, 그대는 어째서 자신들을 낮잡아 보는 것이냐.",
  ui_story_5075_50751402_41_dialog_content = "하지만...",
  ui_story_5075_50751402_42_dialog_content = "인간은 이 몸이 굽어살펴 자신들이 수천 년간 무사히 바다를 오갔다고들 말하지.",
  ui_story_5075_50751402_43_dialog_content = "허나 이 몸이 마지막으로 눈을 뜬 것은 이미 백년도 더 된 일이고,\n그동안 배들은 누가 지켜주지 않았음에도 여전히 바다를 오갔다.",
  ui_story_5075_50751402_44_dialog_content = "설령 신령의 가호가 없다 하여도, 저들은 자신을 지킬 수 있느니라.",
  ui_story_5075_50751402_45_dialog_content = "그 말, 마음에 드네요!",
  ui_story_5075_50751402_46_dialog_content = "이 목소리...",
  ui_story_5075_50751402_47_dialog_content = "선극 씨?!",
  ui_story_5075_50751402_48_dialog_content = "오랜만이야, PlayerName.",
  ui_story_5075_50751402_49_dialog_content = "서둘러 온 덕분에 어떻게든 마지막 순간에 등장할 수 있었네.",
  ui_story_5075_50751402_50_dialog_content = "자, 그럼 모두에게 업나라의 최신 작품을 보여줄게~",
  ui_story_5075_50751402_51_dialog_content = "동력원은 안정적이야. 전포 목표 조준, 최대 화력으로...",
  ui_story_5075_50751402_52_dialog_content = "<size=45>발사!</size>",
  ui_story_5075_50751402_53_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5075_50751402_54_dialog_content = "<color=#e8d9bb>눈부신 금빛 섬광이 바다를 가르고, 인조 벼락이 검은 하늘의 정중앙을 관통했다.</color>",
  ui_story_5075_50751402_55_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5075_50751402_56_dialog_content = "<color=#e8d9bb>다시 엉겨 뭉치려던 검은 기운은 구멍이 난 부분을 미처 메우지 못한 채,\n또다시 산산이 흩어졌다.</color>",
  ui_story_5075_50751402_57_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5075_50751402_58_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5075_50751402_59_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5075_50751402_60_dialog_content = "<color=#e8d9bb>한 차례의 호쾌한 벼락 폭격 후, 바다는 마침내 고요함을 되찾을 수 있었다.</color>",
  ui_story_5075_50751402_61_dialog_content = "또 부활하는 건 아니겠지?",
  ui_story_5075_50751402_62_dialog_content = "으음~ 녀석이 반응을 못 하는 틈을 노려, 이번에는 말끔히 없애 버렸구나.",
  ui_story_5075_50751402_63_dialog_content = "이 대포 또한 이 몸이 잠들어 있는 동안 새롭게 개발한 것이냐?",
  ui_story_5075_50751402_64_dialog_content = "포, 포신에 머리를 넣으면 안 되지!",
  ui_story_5075_50751402_65_dialog_content = "걱정 마. 전원을 꺼 뒀거든.",
  ui_story_5075_50751402_66_dialog_content = "선극 씨! 볼일 때문에 업나라로 돌아갔던 거 아니었어?",
  ui_story_5075_50751402_67_dialog_content = "맞아. 그런데 볼일이 끝나지도 않았는데 우리 작화군주 전하께서 날 부르셨지 뭐야.",
  ui_story_5075_50751402_68_dialog_content = "보니까 제나라 쪽 상황이 더 급하길래, 얼른 최고 성능의 <color=#FFB400>기관포</color>를 가지고 도우러 온 거야.",
  ui_story_5075_50751402_69_dialog_content = "뭐, 전하께선 마중도 안 나와 주셨지만...",
  ui_story_5075_50751402_70_dialog_content = "그래도 PlayerName 당신을 봤으니까 만족했어~",
  ui_story_5075_50751402_71_dialog_content = "단당 씨는 성안에 있어.",
  ui_story_5075_50751402_72_dialog_content = "이제 일도 다 해결됐으니까, 선극 씨도 우리랑 같이 호진성으로 가서 춘삭절을 지내자.",
  ui_story_5075_50751402_73_dialog_content = "아! 확실히 호진의 새해맞이 요수 퇴치 의식은 엄청 떠들썩하고 재미있었는데 말이야.",
  ui_story_5075_50751402_74_dialog_content = "하지만 아쉽게도 난 다시 업나라로 돌아가서 마저 일을 봐야 해.",
  ui_story_5075_50751402_75_dialog_content = "다들 얼른 돌아가. 제야 행사 놓치지 말고. 그럼 우린 다음에 또 보자.",
  ui_story_5075_50751402_76_dialog_content = "나 대신 전하께 안부 전해 줘.",
  ui_story_5075_50751402_77_dialog_content = "알겠어. 볼일이 있으면 어쩔 수 없지.",
  ui_story_5075_50751402_78_dialog_content = "무슨 일 있으면 기관조로 연락해~",
  ui_story_5075_50751402_79_dialog_content = "(하아, 왠지 좀 손해 본 느낌이네.)",
  ui_story_5075_50751402_80_dialog_content = "(저 멀리 업나라에서 기관포까지 가져왔는데, 이렇게 잠깐 나섰다가 퇴장해야 한다니.)",
  ui_story_5075_50751402_81_dialog_content = "하지만 마중 나와 준 사람은 없어도, 퇴장할 땐 자리가 꽤 성대하네.",
  ui_story_5075_50751402_82_dialog_content = "선극 님.",
  ui_story_5075_50751402_83_dialog_content = "선극 님께서는 허가 없이 고성능의 비밀 병기를 사적으로 유용하셨습니다.",
  ui_story_5075_50751402_84_dialog_content = "심지어 병기를 몰래 타국으로 가지고 오셨으니, 이는 이미 반역의 혐의입니다.",
  ui_story_5075_50751402_X84_dialog_content = "훗, 너희가 업나라 사람인지 아닌지는 일단 넘어가고...",
  ui_story_5075_50751402_85_dialog_content = "대왕께서 명하신 건가?",
  ui_story_5075_50751402_86_dialog_content = "예, 저희는 <color=#FFB400>업나라 대왕</color> 전하의 밀명에 따라 선극 님을 체포하여 재판에 회부할 것입니다.\n항명하실 생각이십니까?",
  ui_story_5075_50751402_87_dialog_content = "...그럴 생각은 없어.",
  ui_story_5075_50751402_88_dialog_content = "난 업나라 사람이고, 더욱이 한때 업나라의 모사이자 요인이었던 몸이니까.",
  ui_story_5075_50751402_89_dialog_content = "업나라의 국익에 해를 끼치는 자의 명은 따르지 않겠지만, 어명을 거스르진 않아.",
  ui_story_5075_50751402_90_dialog_content = "죄를 인정할게.",
  ui_story_5075_50751402_91_dialog_content = "......",
  ui_story_5075_50751402_92_dialog_content = "에이, 다들 표정이 왜 그리 딱딱해?",
  ui_story_5075_50751402_93_dialog_content = "감옥에서 새해를 보내는 건 나도 처음이니까, 부족한 게 있어도 많이들 이해해 줘.",
  ui_story_5075_50751501_1_dialog_content = "<color=#e8d9bb>펑! 퍼엉!</color>",
  ui_story_5075_50751501_2_dialog_content = "우와, 불꽃놀이예요!",
  ui_story_5075_50751501_3_dialog_content = "하룻밤 만에 성안이 이렇게 활기를 되찾았네요.",
  ui_story_5075_50751501_4_dialog_content = "요마는 사라졌고, 수요령들과의 오해도 이미 풀렸으니까.",
  ui_story_5075_50751501_5_dialog_content = "게다가 내일은 춘삭절이잖아. 다들 마음 놓고 실컷 축하하고 싶어 하는 것도 당연하지.",
  ui_story_5075_50751501_6_dialog_content = "우룡은 바다로 돌아간 거죠?",
  ui_story_5075_50751501_7_dialog_content = "맞아. 앞으로 자기가 뭘 해야 할지, 그리고 뭘 할 수 있을지 생각해 보겠다고 했어.",
  ui_story_5075_50751501_8_dialog_content = "우룡이 진짜 린 가문에 복수하러 올까요?",
  ui_story_5075_50751501_9_dialog_content = "모르지.",
  ui_story_5075_50751501_10_dialog_content = "하지만 적어도 지난 옛일은 서로 마무리를 지었잖아. 앞으로의 일은...",
  ui_story_5075_50751501_11_dialog_content = "내일부터 얘기하기로 하자.",
  ui_story_5075_50751501_12_dialog_content = "아무래도 역시 「새해잖아」. 그렇지?",
  ui_story_5075_50751501_13_dialog_content = "천간 씨가 거짓말을 한 게 아니었네요. 고대의 주문이라더니 진짜 효과가 있네요!",
  ui_story_5075_50751501_14_dialog_content = "...?",
  ui_story_5075_50751501_15_dialog_content = "...후훗.",
  ui_story_5075_50751501_16_dialog_content = "워, 월백 씨 지금 웃은 거예요?! 제가 뭐 엄청 웃긴 말이라도 한 건가요?!",
  ui_story_5075_50751501_17_dialog_content = "아니.",
  ui_story_5075_50751501_18_dialog_content = "그건 확실히 강력한 주문이 맞아.",
  ui_story_5075_50751501_19_dialog_content = "난 어젯밤 일을 마저 처리하러 린 가문에 가 봐야 해. 먼저 실례할게.",
  ui_story_5075_50751501_20_dialog_content = "네, 그럼 다음에 만나요.",
  ui_story_5075_50751501_21_dialog_content = "<color=#e8d9bb>펑펑! 타닥타탁!</color>",
  ui_story_5075_50751501_22_dialog_content = "무슨 소리지?",
  ui_story_5075_50751501_23_dialog_content = "요수 퇴치 의식의 행렬이 당도한 게다~",
  ui_story_5075_50751501_24_dialog_content = "진예? 넌 또 어디 갔었어...?",
  ui_story_5075_50751501_25_dialog_content = "...그 많은 간식은 다 어디서 난 거야?!",
  ui_story_5075_50751501_26_dialog_content = "조금 전에 이 몸이 뿔을 드러내고 거리를 한 바퀴 둘러보았는데,\n노점 주인들이 지극정성으로 공물을 바치더구나~",
  ui_story_5075_50751501_27_dialog_content = "이런, PlayerName 그대는 뿔도, 꼬리도 없구나.",
  ui_story_5075_50751501_28_dialog_content = "속상해하지 말거라. 자, 이 몸이 간식의 절반을 나누어 주마.",
  ui_story_5075_50751501_29_dialog_content = "고마워. 근데 나 그런 걸로 속상해하진 않아...",
  ui_story_5075_50751501_30_dialog_content = "보거라. 행렬 속에 나송도 있구나.",
  ui_story_5075_50751501_31_dialog_content = "진짜네. 게다가 행렬에 수요령도 엄청 많잖아?",
  ui_story_5075_50751501_32_dialog_content = "폭죽아! 요마도 몰아내고 악운도 날려줘!",
  ui_story_5075_50751501_33_dialog_content = "새해엔 복되고 길한 일만 들어오고, 다 같이 모여서 웃게 해 주세요!",
  ui_story_5075_50751501_34_dialog_content = "어라? 요수 퇴치 의식이라며? 근데 수요령도 쫓아내는 쪽 행렬에 서 있는데?",
  ui_story_5075_50751501_35_dialog_content = "올해부터 바뀌었습니다. 요수가 아니라 요마를 쫓아내는 것으로 말이지요.",
  ui_story_5075_50751501_36_dialog_content = "어젯밤에 용녀님께서 현신하셨는데, 못 보셨나요?\n용녀님께서 요마들을 모두 없애 주셨는데, 수요령들에겐 아무 일도 없었어요.",
  ui_story_5075_50751501_37_dialog_content = "이는 용녀님께서 수요령이 인간을 해치지 않는다고 여기시는 게 아니겠어요?",
  ui_story_5075_50751501_38_dialog_content = "다들 잘 들어! 강한 적과 맞서려면 협력하는 법을 배워야 해.",
  ui_story_5075_50751501_39_dialog_content = "자신의 특성을 잘 활용하고 서로 도우면, 힘은 덜 들이면서 몇 배의 효과를 낼 수 있어!",
  ui_story_5075_50751501_40_dialog_content = "아정, 사람들한테 너랑 새 친구들의 합동 기술을 보여 줘!",
  ui_story_5075_50751501_41_dialog_content = "캬오!",
  ui_story_5075_50751501_42_dialog_content = "냐앙!",
  ui_story_5075_50751501_43_dialog_content = "내가 잘못 봤나?",
  ui_story_5075_50751501_44_dialog_content = "행렬에 어디서 많이 보던 고양이도 있는 것 같은데?",
  ui_story_5075_50751501_45_dialog_content = "<color=#e8d9bb>펑펑! 타닥타탁!</color>",
  ui_story_5075_50751501_46_dialog_content = "폭죽아! 요마도 몰아내고 악운도... 으앗.",
  ui_story_5075_50751501_47_dialog_content = "죄송해요! 앞을 제대로 못 봐서... 아!",
  ui_story_5075_50751501_48_dialog_content = "흐음?",
  ui_story_5075_50751501_49_dialog_content = "어? 너 전에 수요령 괴롭히던 그 꼬마구나.",
  ui_story_5075_50751501_50_dialog_content = "저, 저기... 누나도 수요령인 거죠?",
  ui_story_5075_50751501_51_dialog_content = "이 사탕, 누나 줄게요!",
  ui_story_5075_50751501_52_dialog_content = "그리고... 혹시 우리가 전에 괴롭힌 수요령이랑 아는 사이면... 미안하다고 좀 전해 주세요!",
  ui_story_5075_50751501_53_dialog_content = "도망갔네...",
  ui_story_5075_50751501_54_dialog_content = "사람들이 수요령을 보는 시선도 바뀌기 시작한 것 같아.",
  ui_story_5075_50751501_55_dialog_content = "으음... 냠.",
  ui_story_5075_50751501_56_dialog_content = "참으로 달구나.",
  ui_story_5075_50751501_57_dialog_content = "난 진예 네가 저 모습을 보고 되게 기뻐할 줄 알았는데.",
  ui_story_5075_50751501_58_dialog_content = "기뻐하고 있느니라.",
  ui_story_5075_50751501_59_dialog_content = "근데 왠지...",
  ui_story_5075_50751501_60_dialog_content = "어제나 엊그제 기뻐하던 모습이랑 별 차이가 없는 것 같아서.",
  ui_story_5075_50751501_61_dialog_content = "이 세상이란 본래 그런 것이기 때문이니라.",
  ui_story_5075_50751501_62_dialog_content = "인간은 어제까진 수요령이 두려워 저들을 핍박하였으나,\n오늘은 양심의 가책을 느껴 저들을 잘 대접해 주고 있지.",
  ui_story_5075_50751501_63_dialog_content = "하면 내일은 또 어떤 이유로 수요령을 핍박할지 누가 알겠느냐.",
  ui_story_5075_50751501_64_dialog_content = "어제는 맛있던 간식이 오늘은 맛이 없다가, 내일은 또 맛있어질지도 모르는 것처럼 말이다.",
  ui_story_5075_50751501_65_dialog_content = "무릇 좋음이 있으면, 나쁨이 있기 마련이지. 항상 좋은 것도, 반대로 항상 나쁜 것도 없느니라.",
  ui_story_5075_50751501_66_dialog_content = "허나 이 몸은 이대로도 족하다.",
  ui_story_5075_50751501_67_dialog_content = "난... 역시 네 마음이 잘 이해되진 않네.",
  ui_story_5075_50751501_68_dialog_content = "그래도 많은 일을 겪고 나니까, 지금은 조금이나마 알 것 같아.",
  ui_story_5075_50751501_69_dialog_content = "진예 네 눈엔 인간이나 수요령뿐만 아니라, 이 대륙의 모든 생명이 똑같이 보이는 거겠지.",
  ui_story_5075_50751501_70_dialog_content = "모든 생명은 저마다 존재의 의미가 있어.",
  ui_story_5075_50751501_71_dialog_content = "넌 그 존재의 의미를 존중하니까, 오히려 쉽게 간섭하려 하지 않는 거고.",
  ui_story_5075_50751501_72_dialog_content = "겉보기엔 무심해 보이지만, 사실 넌 모든 걸 동등하게 배려해 주고 있었던 거였어.",
  ui_story_5075_50751501_73_dialog_content = "그렇게 보면 며칠 동안 우리가 함께 겪은 일들도 너한테는 사소한 일일지도 모르겠네.",
  ui_story_5075_50751501_74_dialog_content = "그건 왠지 조금 서운한걸.",
  ui_story_5075_50751501_75_dialog_content = "그럼 진예 넌 이제부터 뭐 할 거야?",
  ui_story_5075_50751501_76_dialog_content = "이 몸은 시끄러워 잠이 깨서 나온 것이다.",
  ui_story_5075_50751501_77_dialog_content = "조만간 돌아가서 다시 잠을 청해야지.",
  ui_story_5075_50751501_78_dialog_content = "이렇게 빨리?",
  ui_story_5075_50751501_79_dialog_content = "사절 나리, 궁으로 들어오시라는 대왕님의 전언이옵니다.",
  ui_story_5075_50751501_80_dialog_content = "앗, 알겠어요.",
  ui_story_5075_50751501_81_dialog_content = "진예, 아니면 너도... 어라?",
  ui_story_5075_50751501_82_dialog_content = "벌써 가 버린 거야?",
  ui_story_5075_50751501_83_dialog_content = "PlayerName 공자, 고생이 많았다.",
  ui_story_5075_50751501_84_dialog_content = "이번에는...",
  ui_story_5075_50751501_85_dialog_content = "PlayerName! PlayerName!",
  ui_story_5075_50751501_86_dialog_content = "단당한테 다 들었어! 그대가 목숨도 아끼지 않고 용감하고 현명하게 활약했다고 말이야!",
  ui_story_5075_50751501_87_dialog_content = "제나라 조정에 숨은 간적도 찾아냈고, 어제 홍수를 제때 물리친 것도 전부 그대의 공로다!",
  ui_story_5075_50751501_88_dialog_content = "세자, 내 그리 과장해서 말하지는 않았습니다만.",
  ui_story_5075_50751501_89_dialog_content = "아무튼 PlayerName 그대가 대영웅이란 건 알겠어!",
  ui_story_5075_50751501_90_dialog_content = "대영웅은 훌륭해! <size=45>그러니까 난 PlayerName 그대와 혼인할래!</size>",
  ui_story_5075_50751501_91_dialog_content = "<size=45>...하?</size>",
  ui_story_5075_50751501_92_dialog_content = "세상 사람들이 이르기를 부부는 하나라고 했어.\n그대 같은 훌륭한 정혼자가 있으니까 나도 곧 영웅이 될 수 있겠네!",
  ui_story_5075_50751501_93_dialog_content = "<size=45>어험!</size>",
  ui_story_5075_50751501_94_dialog_content = "여봐라, 어서 세자를 데려가거라!",
  ui_story_5075_50751501_95_dialog_content = "그리고 부부가 무엇인지도 똑바로 다시 가르쳐 두라고 학사들에게 고하거라.\n허구한 날 허튼소리를 하여 과인이 오해를 하게 만들다니...",
  ui_story_5075_50751501_96_dialog_content = "다만 세자의 다른 말에는 거짓이 없었다.",
  ui_story_5075_50751501_97_dialog_content = "호진에 위기가 닥친 것은 과인의 오판 탓이고, 그대들의 공로 덕분에 국면을 다스릴 수 있었다.",
  ui_story_5075_50751501_98_dialog_content = "원하는 바가 있다면 얼마든지 고하라. 과인이 반드시 들어주마.",
  ui_story_5075_50751501_99_dialog_content = "그럼... 제가 단당 군주와 준비한 양 대륙의 교류 계획을 전하께서 들어 주셨으면 좋겠어요!",
  ui_story_5075_50751501_100_dialog_content = "단지 그것뿐인가? 정녕 재물이나 권세, 지위는 원하지 않는단 말이냐?",
  ui_story_5075_50751501_101_dialog_content = "솔직히 말씀드리자면 원하지 않는 건 아니에요.\n하지만 전 이번엔 아스트라 대륙의 사절 자격으로 용주에 온 거니까요.",
  ui_story_5075_50751501_102_dialog_content = "사명을 완수하는 게 제일 중요하죠.",
  ui_story_5075_50751501_103_dialog_content = "하하하, 그대와 같은 걸출한 청년을 그냥 돌려보내는 것이 아쉽구나.",
  ui_story_5075_50751501_104_dialog_content = "허나 그대는 용주에 남을 뜻이 없으니, 이렇게 함이 어떠한가.",
  ui_story_5075_50751501_105_dialog_content = "과인은 그대를 제나라의 명예 국민으로 봉하겠다.",
  ui_story_5075_50751501_106_dialog_content = "앞으로 그대가 어디로 가서, 무슨 일을 겪든지, 제나라는 늘 그대를 환영할 것이다.",
  ui_story_5075_50751501_107_dialog_content = "감사합니다, 전하!",
  ui_story_5075_50751501_108_dialog_content = "(휴... 궁에서 엄청 오래 있었네... 시간이 벌써 이렇게 됐잖아.)",
  ui_story_5075_50751501_109_dialog_content = "(주사관이 체포되고 나니까, 영빈관 시녀랑 호위들도 드디어 없어졌구나.)",
  ui_story_5075_50751501_110_dialog_content = "(여기 이렇게 혼자 있는 건 처음인 것 같네.)",
  ui_story_5075_50751501_111_dialog_content = "(...되게 조용한걸.)",
  ui_story_5075_50751501_112_dialog_content = "(그리고 갑자기 한가해지니까 뭘 해야 할지 모르겠어.)",
  ui_story_5075_50751501_113_dialog_content = "(참, 내일이 드디어 춘삭절이잖아.)",
  ui_story_5075_50751501_114_dialog_content = "(용주 사람들은 오늘 밤에 다 같이 모여서 식사도 하고, 밤새 이야기를 나눈다고 그랬었지.)",
  ui_story_5075_50751501_115_dialog_content = "(지나간 한 해에 작별을 고하고, 새로운 한 해를 맞이한다는 의미라고 말이야.)",
  ui_story_5075_50751501_116_dialog_content = "(나도 해 볼까... 아니다, 혼자 밤을 새워 봐야 무슨 재미가 있다고.)",
  ui_story_5075_50751501_117_dialog_content = "다들 뭐 하고 있으려나...",
  ui_story_5075_50751501_118_dialog_content = "PlayerName 그대가 이 몸을 발견할 때까지 기다리고 있느니라.",
  ui_story_5075_50751501_119_dialog_content = "어?! 진예 너 언제 들어온 거야?",
  ui_story_5075_50751501_120_dialog_content = "그대가 돌아오기 전부터 와 있었느니라.",
  ui_story_5075_50751501_121_dialog_content = "허나 PlayerName 그대는 한참 동안이나 혼자 어슬렁거리고,\n이 몸에게는 눈길도 주지 않기에, 하는 수 없이 직접 나선 것이다.",
  ui_story_5075_50751501_122_dialog_content = "다 봤구나...",
  ui_story_5075_50751501_123_dialog_content = "난 네가 벌써 떠난 줄 알았어.",
  ui_story_5075_50751501_124_dialog_content = "조만간 바다로 돌아가겠다고 했었잖아.",
  ui_story_5075_50751501_125_dialog_content = "그렇다. 오래 머물지는 않을 것이다.",
  ui_story_5075_50751501_126_dialog_content = "아마 몇십 년 정도 있다가 돌아가겠지.",
  ui_story_5075_50751501_127_dialog_content = "잠깐만... 네가 말한 「조만간」이 몇십 년이란 뜻이었어?!",
  ui_story_5075_50751501_128_dialog_content = "너무 짧은 게냐?",
  ui_story_5075_50751501_129_dialog_content = "이 몸은 PlayerName 그대와 노는 것이 재미있다.",
  ui_story_5075_50751501_130_dialog_content = "그러니 PlayerName 그대가 바란다면 일이백 년 정도 머물러 줄 수도 있느니라.",
  ui_story_5075_50751501_131_dialog_content = "...미안, 대수요령의 시간관념은 보통 사람이랑 다르단 걸 깜빡했어.",
  ui_story_5075_50751501_132_dialog_content = "그나저나 어찌 이곳에는 아무것도 없는 것이냐?",
  ui_story_5075_50751501_133_dialog_content = "지금은 제야 만찬을 즐길 시간이 아니더냐.",
  ui_story_5075_50751501_134_dialog_content = "하하하, 내가 신경을 못 썼어.",
  ui_story_5075_50751501_135_dialog_content = "하는 수 없지. 이것은 이 몸이 방금 공물로 받은  「천장권」이라는 음식이다. 그대에게 주마.",
  ui_story_5075_50751501_136_dialog_content = "고마워... 어? 천장권...?",
  ui_story_5075_50751501_137_dialog_content = "PlayerName── 진예──",
  ui_story_5075_50751501_138_dialog_content = "다들 어디 있어?",
  ui_story_5075_50751501_139_dialog_content = "나송 목소리 같은데?",
  ui_story_5075_50751501_140_dialog_content = "나송! 여기야!",
  ui_story_5075_50751501_141_dialog_content = "PlayerName! 진예! 드디어 찾았네.",
  ui_story_5075_50751501_142_dialog_content = "내가 정신이 없어서 헤어질 때 주소를 물어본다는 걸 깜빡했지 뭐야.",
  ui_story_5075_50751501_143_dialog_content = "설마 거리에서 계속 우리 이름을 외치면서 찾아다닌 건 아니지?",
  ui_story_5075_50751501_144_dialog_content = "하하, 좀 멍청한 방법이긴 했지만, 그래도 이렇게 찾았잖아?",
  ui_story_5075_50751501_145_dialog_content = "어렵게 만난 인연인데, 혹시 괜찮으면 둘 다 올해 제야는 나랑 같이 보내지 않을래?",
  ui_story_5075_50751501_146_dialog_content = "당연히 좋지!",
  ui_story_5075_50751501_147_dialog_content = "그럼 다행이네.",
  ui_story_5075_50751501_148_dialog_content = "참, 아까 어떤 할머니를 도와서 물건을 좀 옮겨 드렸는데, 고맙다고 미나리 한 봉지를 받았거든.",
  ui_story_5075_50751501_149_dialog_content = "마침 이걸로 제야 만찬에 요리를 하나 더 추가할 수 있을 거야.",
  ui_story_5075_50751501_150_dialog_content = "아이고, 여긴 어째 제 길거리 점집보다 더 한산하답니까?",
  ui_story_5075_50751501_151_dialog_content = "천간 씨? 여긴 어떻게 찾아왔어요?",
  ui_story_5075_50751501_152_dialog_content = "물론 한 끼 얻어... 아니, PlayerName 공이 이국땅에서 새해를 맞는 게\n익숙하지 않으실까 걱정이 되어 와 봤습니다.",
  ui_story_5075_50751501_153_dialog_content = "역시나, 제야 만찬조차 준비하지 않으셨군요. 소생이 마침 잘 온 모양입니다.",
  ui_story_5075_50751501_154_dialog_content = "받으시지요. 소생이 준비한 새해 선물입니다.",
  ui_story_5075_50751501_155_dialog_content = "신경 써 줘서 진짜 고맙긴 한데... 이게 웬 채소죠?",
  ui_story_5075_50751501_156_dialog_content = "이건 평범한 채소가 아니라, 냉이라는 것입니다. 겨울철에는 무척 구하기 힘들지요.",
  ui_story_5075_50751501_157_dialog_content = "소생이 지난 며칠간 설탕 인형을 팔아 번 돈을 전부 털어서,\n간신히 따뜻한 실내에서 기른 냉이 한 바구니를 산 것입니다.",
  ui_story_5075_50751501_158_dialog_content = "냉이는 「제채」라고도 하는데, 「재」물이 「채」워진다는 길한 뜻이 연상되는 채소지요.\n제야에 냉이를 먹으면 새해에 돈을 많이 벌 수 있을 것입니다!",
  ui_story_5075_50751501_159_dialog_content = "호오, 천장권도 가지고 계셨군요. 이 역시 길한 음식입니다.\n「천」세 만세 「장」구할 「권」세의 뜻이 있으니 말입니다.",
  ui_story_5075_50751501_160_dialog_content = "미나리도 물론 좋습니다. 미나리의 다른 이름은 「근채」인데,\n「근」면히 일하여 재물이 「채」워진다는 뜻이니, 이 어찌 좋은 뜻이 아니겠습니까?",
  ui_story_5075_50751501_161_dialog_content = "PlayerName, 와서 좀 도와줘.",
  ui_story_5075_50751501_162_dialog_content = "상회에서 방금 나한테 연근을 한 수레 갖다줬거든.\n당신이 머무는 곳엔 먹을 게 별로 없을 것 같아서 가져와 봤어.",
  ui_story_5075_50751501_163_dialog_content = "한 수레나요?!",
  ui_story_5075_50751501_164_dialog_content = "좋은 연근이로군요. 받아 두시지요.",
  ui_story_5075_50751501_165_dialog_content = "연근은 쪼개면 안에 구멍이 숭숭 뚫려 있지요.\n여기에는 앞으로 앞길이 시원시원하게 뚫린다는 축복이 담겨 있습니다.",
  ui_story_5075_50751501_166_dialog_content = "천간 씨는 어떻게 뭘 보든 전부 거기서 좋은 의미를 찾아낼 수 있는 거죠?",
  ui_story_5075_50751501_167_dialog_content = "새해잖습니까. 당연히 만사대길하여야지요.",
  ui_story_5075_50751501_168_dialog_content = "이천간 이 작자가 또 남을 속이는 소리가 저 멀리서부터 들린다 싶었거늘.",
  ui_story_5075_50751501_169_dialog_content = "그 새해 덕담들만큼은 그래도 나쁘지 않구나.",
  ui_story_5075_50751501_170_dialog_content = "오랜만에 뵙습니다, PlayerName 님.",
  ui_story_5075_50751501_171_dialog_content = "어? 단당 씨랑 구 씨는 궁에서 제야를 안 보내도 괜찮은 건가요?",
  ui_story_5075_50751501_172_dialog_content = "본래라면 그래야 마땅하지.",
  ui_story_5075_50751501_173_dialog_content = "허나 이번에 PlayerName 공자가 큰 공을 세운 고로,\n국군께서 특별히 내게 임무를 하나 내리셨다.",
  ui_story_5075_50751501_174_dialog_content = "그대가 즐거운 새해를 맞이하도록 대접하라 하셨지.",
  ui_story_5075_50751501_175_dialog_content = "궁에서 넉넉히 보내 준 식재도 문밖에 있으니, 내 직접 요리를 하여\n제야에 걸맞을 명절 요리를 해 주마.",
  ui_story_5075_50751501_176_dialog_content = "참, 모두 식재로 덕담을 전했으니, 나도 꽃으로 전해야겠구나.",
  ui_story_5075_50751501_177_dialog_content = "이 찬란한 「금잠초」를 PlayerName 공자에게 선물하마.",
  ui_story_5075_50751501_178_dialog_content = "그대의 앞날이 이처럼 양양하길 바란다.",
  ui_story_5075_50751501_179_dialog_content = "그렇다면 저는 이 완두콩잎을 드리지요.\n나뭇가지에 가득 핀 봄이라는 뜻을 담고 있으니, 이 역시 덕담이 아니겠습니까.",
  ui_story_5075_50751501_180_dialog_content = "우와, 여기 뭐 이렇게 사람이 많아?",
  ui_story_5075_50751501_181_dialog_content = "올해 마지막 밤을 PlayerName 혼자 보내면 어쩌나 걱정했는데 말이야.",
  ui_story_5075_50751501_182_dialog_content = "넓은 교분을 이룬 것은 좋은 일이오.",
  ui_story_5075_50751501_183_dialog_content = "리청! 종서 씨도 오셨군요!",
  ui_story_5075_50751501_184_dialog_content = "상에 식재가 왜 이렇게 많아? 아, 알겠다!",
  ui_story_5075_50751501_185_dialog_content = "「십경채」 만들려는 거지?",
  ui_story_5075_50751501_186_dialog_content = "십경채가 뭔데?",
  ui_story_5075_50751501_187_dialog_content = "제나라의 전통 음식이오. 열 가지 채소를 잘게 썰고, 기름에 볶아 낸 요리를 「십경」이라 하지.",
  ui_story_5075_50751501_188_dialog_content = "그리하면 채소들이 품은 좋은 의미가 모두 하나가 되는 것이오.",
  ui_story_5075_50751501_189_dialog_content = "제나라에서는 춘삭절에 없어서는 안 될 요리 중 하나일세.",
  ui_story_5075_50751501_190_dialog_content = "허나 여기 있는 채소들만으로는 아직 부족함이 있소이다.",
  ui_story_5075_50751501_191_dialog_content = "하여 종 모가 갓을 가져와 보았소.\n「설리홍」이라는 이명처럼 부디 제위의 만사가 뜨겁게 흥성하길 바라겠소.",
  ui_story_5075_50751501_192_dialog_content = "그럼 전 쇠비름을 넣을게요.",
  ui_story_5075_50751501_193_dialog_content = "쇠비름은 나물로도 먹을 수 있고, 열을 내리고 독을 없애는 약재도 되죠.",
  ui_story_5075_50751501_194_dialog_content = "모두가 가져온 식재가 이토록 제각각이라니, 그야말로 내 솜씨를 시험하려 드는구나.",
  ui_story_5075_50751501_195_dialog_content = "전하께는 전혀 어려운 일도 아니지 않습니까.",
  ui_story_5075_50751501_196_dialog_content = "구야, 어찌 너까지 바람을 넣는 것이냐. 하면 너도 함께 주방으로 가자꾸나.",
  ui_story_5075_50751501_197_dialog_content = "저도 도울게요.",
  ui_story_5075_50751501_198_dialog_content = "맛을 보는 것은 소생이...",
  ui_story_5075_50751501_199_dialog_content = "이 몸도 맛을 봐 줄 수 있느니라!",
  ui_story_5075_50751501_200_dialog_content = "어이쿠, 소생이 어찌 낭랑님의 것을 빼앗겠습니까. 부디 맡아 주시지요.",
  ui_story_5075_50751501_201_dialog_content = "그럼 난 밖에 있는 식재부터 좀 정리하고, 필요한 것들은 들고 올게.",
  ui_story_5075_50751501_202_dialog_content = "장식할 재료들도 좀 가져왔어. 방을 꾸밀 때 쓸 수 있을 거야.",
  ui_story_5075_50751501_203_dialog_content = "잘됐네! 여긴 명절 분위기가 너무 안 난다고 아까부터 말하고 싶었다고. 이래서야 되겠어?",
  ui_story_5075_50751501_204_dialog_content = "모두가 가져온 식재로 만든 십경채가 완성되었다.",
  ui_story_5075_50751501_205_dialog_content = "이제 곧 용녀 사당의 종이 울리겠구나.\n새로운 한 해가 시작되기 전에 내 그대에게 전하고 싶은 말이 있다...",
  ui_story_5075_50751501_206_dialog_content = "PlayerName 공자, 지난 한 해 동안 신세를 많이 졌구나. 진심으로 감사하마.",
  ui_story_5075_50751501_207_dialog_content = "저는 언변이 좋지 못해 그저 감사하다는 말씀만 드리겠습니다.",
  ui_story_5075_50751501_208_dialog_content = "한 해 동안 소생의 사업에 힘을 보태 주셔서 감사드립니다. 내년에도 잘 부탁드리지요.",
  ui_story_5075_50751501_209_dialog_content = "일전의 여정에서는 종 모가 많은 도움을 받았소. 감사하오.\n새로운 한 해에도 귀공의 앞길이 순탄하기를 바라겠소.",
  ui_story_5075_50751501_210_dialog_content = "여러 가지로 고마웠어! 새해에도 나한테 약 지어 달라고 할 일 없게 건강해야 돼!",
  ui_story_5075_50751501_211_dialog_content = "얼굴을 익힌 지 오래된 건 아니지만, 넌 이미 내가 인정하는 친구야.",
  ui_story_5075_50751501_212_dialog_content = "새해엔 네가 어떤 요마나 악령과 마주쳐도 단번에 쓰러트릴 만큼 강해지길 바랄게!",
  ui_story_5075_50751501_213_dialog_content = "새해 복 많이 받아. 건배.",
  ui_story_5075_50751501_214_dialog_content = "...딸꾹.",
  ui_story_5075_50751501_215_dialog_content = "아이고, 아직 새해도 안 됐는데 뭘 먼저 달리고 있습니까? 벌써부터 마시다니...",
  ui_story_5075_50751501_216_dialog_content = "PlayerName, PlayerName.",
  ui_story_5075_50751501_217_dialog_content = "왜? 진예.",
  ui_story_5075_50751501_218_dialog_content = "고개를 숙여 보아라.",
  ui_story_5075_50751501_219_dialog_content = "응, 근데 고개는 왜?",
  ui_story_5075_50751501_220_dialog_content = "쓰담쓰담, 쓰담쓰담.",
  ui_story_5075_50751501_221_dialog_content = "PlayerName 그대가 날마다 기쁘고, 모든 일이 잘 풀리게 해 주마.",
  ui_story_5075_50751501_222_dialog_content = "이 용녀가 친히 꺼낸 말이니 분명히 영험할 것이야~",
  ui_story_5075_50751501_223_dialog_content = "<color=#e8d9bb>땡── 땡──</color>",
  ui_story_5075_50751501_224_dialog_content = "<color=#e8d9bb>남쪽 사당에서 시작된 용녀 사당의 종소리는 차츰차츰 호진성 전체로 퍼져 나갔다.</color>",
  ui_story_5075_50751501_225_dialog_content = "<color=#e8d9bb>백팔 번 울려 퍼진 종소리는 모든 번뇌를 씻어 내리고, 행운과 평안을 가져왔다.</color>",
  ui_story_5075_50751501_226_dialog_content = "그럼 이걸로 춘삭절이... 새로운 한 해가 시작된 거네요.",
  ui_story_5075_50751501_227_dialog_content = "PlayerName 공자.",
  ui_story_5075_50751501_228_dialog_content = "PlayerName 님.",
  ui_story_5075_50751501_229_dialog_content = "PlayerName 공.",
  ui_story_5075_50751501_230_dialog_content = "PlayerName.",
  ui_story_5075_50751501_231_dialog_content = "PlayerName.",
  ui_story_5075_50751501_232_dialog_content = "PlayerName.",
  ui_story_5075_50751501_233_dialog_content = "PlayerName.",
  ui_story_5075_50751501_234_dialog_content = "PlayerName!",
  ui_story_5075_50751501_235_dialog_content = "<size=45>PlayerName의 즐거운 새해를 위하여!</size>"
}
return config
